INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(46765, 801, 772, '<td valign="top">I think that this is a very good interpretation of the "stopped motion" challenge.  I also like the composition of this photo.  I like action shots and this is a great example of that.  Your depth of field nicely blurs out the background and brings the subject of the photo to my immediate attention.  There are two things that would make this an even better photo.  The tires on the ATV are not frozen in time.  A faster shutter speed or possibly a flash on a shot like this would improve that.  A flash may have also improved the detail of the rider.  The rider is a little dark.  Excellent shot!</td>', 'I think that this is a very good interpretation of the "stopped motion" challenge.  I also like the composition of this photo.  I like action shots and this is a great example of that.  Your depth of field nicely blurs out the background and brings the subject of the photo to my immediate attention.  There are two things that would make this an even better photo.  The tires on the ATV are not frozen in time.  A faster shutter speed or possibly a flash on a shot like this would improve that.  A flash may have also improved the detail of the rider.  The rider is a little dark.  Excellent shot!', '2002-04-15 07:28:00.000000', NULL, 1),
(46766, 801, 92, '<td valign="top">Great capture. The tires have just a little bit too much action but I still think you did a great job.</td>', 'Great capture. The tires have just a little bit too much action but I still think you did a great job.', '2002-04-15 07:54:00.000000', NULL, 1),
(46767, 801, 656, '<td valign="top">Excellent shot.  If you''d been lower (if you could ) you could have taken this against the sky and it would have been even stronger, rather than against the fairly ''muddy'' background.</td>', 'Excellent shot.  If you''d been lower (if you could ) you could have taken this against the sky and it would have been even stronger, rather than against the fairly ''muddy'' background.', '2002-04-15 08:06:00.000000', NULL, 1),
(46768, 801, 641, '<td valign="top">A little blurring on the wheels, but a really good shot though. I like how the yellow catches your attention in this.</td>', 'A little blurring on the wheels, but a really good shot though. I like how the yellow catches your attention in this.', '2002-04-15 10:07:00.000000', NULL, 1),
(46769, 801, 205, '<td valign="top">I like to see landings in the composition</td>', 'I like to see landings in the composition', '2002-04-15 10:16:00.000000', NULL, 1),
(46770, 801, 139, '<td valign="top">Nice focus and nice composition.</td>', 'Nice focus and nice composition.', '2002-04-15 11:06:00.000000', NULL, 1),
(46771, 801, 813, '<td valign="top">Good action, good framing, needs levels adjusted.</td>', 'Good action, good framing, needs levels adjusted.', '2002-04-15 12:20:00.000000', NULL, 1),
(46772, 801, 661, '<td valign="top">Fast wheels</td>', 'Fast wheels', '2002-04-15 19:31:00.000000', NULL, 1),
(46773, 801, 724, '<td valign="top">What posters are made of, nice job.</td>', 'What posters are made of, nice job.', '2002-04-15 23:06:00.000000', NULL, 1),
(46774, 801, 2, '<td valign="top">Great picture, and nice crop to keep the action big and bold.</td>', 'Great picture, and nice crop to keep the action big and bold.', '2002-04-16 11:23:00.000000', NULL, 1),
(46775, 801, 748, '<td valign="top">I like the shot even though the wheels still seem to have motion.</td>', 'I like the shot even though the wheels still seem to have motion.', '2002-04-16 16:58:00.000000', NULL, 1),
(46776, 801, 441, '<td valign="top">good interesting shot with rider stopped dead but wheels still in motion</td>', 'good interesting shot with rider stopped dead but wheels still in motion', '2002-04-17 04:38:00.000000', NULL, 1),
(46777, 801, 472, '<td valign="top">good shot!  it is a bit dark though. i would have preferred to blow out the sky a bit more so we could see the rider better.</td>', 'good shot!  it is a bit dark though. i would have preferred to blow out the sky a bit more so we could see the rider better.', '2002-04-17 11:54:00.000000', NULL, 1),
(46778, 801, 1132, '<td valign="top">This would be an awesome picture if it was a little brighter and sharper.</td>', 'This would be an awesome picture if it was a little brighter and sharper.', '2002-04-17 16:14:00.000000', NULL, 1),
(46779, 801, 749, '<td valign="top">Good composition, but needs a bit more light to help pick up the details</td>', 'Good composition, but needs a bit more light to help pick up the details', '2002-04-17 16:52:00.000000', NULL, 1),
(46780, 801, 587, '<td valign="top">great photo, like how you stopped motion in atleast 3 places (background, tires, and quad) cool.</td>', 'great photo, like how you stopped motion in atleast 3 places (background, tires, and quad) cool.', '2002-04-18 07:04:00.000000', NULL, 1),
(46781, 801, 543, '<td valign="top">A fill flash would have worked well here to get more detail in the rider and under the bike.  The dark rider against the bright sky / bright bike against the dark hills works real good.</td>', 'A fill flash would have worked well here to get more detail in the rider and under the bike.  The dark rider against the bright sky / bright bike against the dark hills works real good.', '2002-04-18 09:28:00.000000', NULL, 1),
(46782, 801, 142, '<td valign="top">You captured the movement well.  With a little stronger focus this would be a fantastic shot.</td>', 'You captured the movement well.  With a little stronger focus this would be a fantastic shot.', '2002-04-18 11:07:00.000000', NULL, 1),
(46783, 801, 933, '<td valign="top">Nicely framed photo!  Could be a tad brighter.</td>', 'Nicely framed photo!  Could be a tad brighter.', '2002-04-18 11:39:00.000000', NULL, 1),
(46784, 801, 811, '<td valign="top">Good angle, and I like the way the image fills up the viewing area.</td>', 'Good angle, and I like the way the image fills up the viewing area.', '2002-04-18 19:16:00.000000', NULL, 1),
(46785, 801, 739, '<td valign="top">The first shot where the background is blurred to enhance the impression of motion.  Did you try more blurring?</td>', 'The first shot where the background is blurred to enhance the impression of motion.  Did you try more blurring?', '2002-04-19 01:39:00.000000', NULL, 1),
(46786, 801, 797, '<td valign="top">this is a great one. in the air. defying gravity. and colors are nice combination.</td>', 'this is a great one. in the air. defying gravity. and colors are nice combination.', '2002-04-19 02:33:00.000000', NULL, 1),
(46787, 801, 245, '<td valign="top">great mix of sharp bike and blurred wheels. unfortuanely I took something similar a week too early and couldn''t use it!</td>', 'great mix of sharp bike and blurred wheels. unfortuanely I took something similar a week too early and couldn''t use it!', '2002-04-19 02:47:00.000000', NULL, 1),
(46788, 801, 1175, '<td valign="top">This is a great image.  Only thing to make it better might be a change in background.  Higher shutter speed to stop the wheels would be cool as well.</td>', 'This is a great image.  Only thing to make it better might be a change in background.  Higher shutter speed to stop the wheels would be cool as well.', '2002-04-19 19:49:00.000000', NULL, 1),
(46789, 801, 113, '<td valign="top">Good angle.  Good comp.  I like it.</td>', 'Good angle.  Good comp.  I like it.', '2002-04-20 05:09:00.000000', NULL, 1),
(46790, 801, 1202, '<td valign="top">Not true stop action, photographer is following reider and the background id blurred as a result.   If the background had been stopped it would be excellent.   The wheels still in motion add to the interest of this photo.</td>', 'Not true stop action, photographer is following reider and the background id blurred as a result.   If the background had been stopped it would be excellent.   The wheels still in motion add to the interest of this photo.', '2002-04-20 10:49:00.000000', NULL, 1),
(46791, 801, 1, '<td valign="top">Cool shot, nicely panned, perfect crop.  There''s really nothing technically wrong with this shot.</td>', 'Cool shot, nicely panned, perfect crop.  There''s really nothing technically wrong with this shot.', '2002-04-21 12:07:00.000000', NULL, 1),
(46792, 801, 806, '<td valign="top">great action!</td>', 'great action!', '2002-04-21 18:55:00.000000', NULL, 1),
(46793, 801, 1040, '<td valign="top">Great picture!</td>', 'Great picture!', '2002-04-21 23:52:00.000000', NULL, 1),
(46794, 803, 641, '<td valign="top">Interesting angle. I like that. And the b/w makes it.</td>', 'Interesting angle. I like that. And the b/w makes it.', '2002-04-15 09:54:00.000000', NULL, 1),
(46795, 803, 92, '<td valign="top">Nice angle:)))</td>', 'Nice angle:)))', '2002-04-15 10:47:00.000000', NULL, 1),
(46796, 803, 139, '<td valign="top">I personally don''t like band photos, but I''m able to look at this objectively and I really do think it''s a good photo.</td>', 'I personally don''t like band photos, but I''m able to look at this objectively and I really do think it''s a good photo.', '2002-04-15 10:57:00.000000', NULL, 1),
(46797, 803, 656, '<td valign="top">Keep turning my head on this one.  Not a whole lot of motion going on really.</td>', 'Keep turning my head on this one.  Not a whole lot of motion going on really.', '2002-04-15 12:01:00.000000', NULL, 1),
(46798, 803, 189, '<td valign="top">oooh Action!</td>', 'oooh Action!', '2002-04-15 12:36:00.000000', NULL, 1),
(46799, 803, 509, '<td valign="top">Nice angle, but I would have liked more light, would have helped to separate the guy''s shirt from the background.  BTW, is that a Gibson les Paul? If it is, NICE</td>', 'Nice angle, but I would have liked more light, would have helped to separate the guy''s shirt from the background.  BTW, is that a Gibson les Paul? If it is, NICE', '2002-04-15 14:26:00.000000', NULL, 1),
(46800, 803, 748, '<td valign="top">Not much motion on a G chord!</td>', 'Not much motion on a G chord!', '2002-04-15 15:11:00.000000', NULL, 1),
(46801, 803, 772, '<td valign="top">I do like black and whites and I like Les Pauls also.. I have a ''65 standard myself.  Plays like a dream and sounds even better.  I''m looking for the motion that is supposed to be stopped.  The perspective of this shot is very nice...</td>', 'I do like black and whites and I like Les Pauls also.. I have a ''65 standard myself.  Plays like a dream and sounds even better.  I''m looking for the motion that is supposed to be stopped.  The perspective of this shot is very nice...', '2002-04-15 19:23:00.000000', NULL, 1),
(46802, 803, 910, '<td valign="top">I''m sure he''s moving, but you don''t get that sense from the picture.  A good pic otherwise.</td>', 'I''m sure he''s moving, but you don''t get that sense from the picture.  A good pic otherwise.', '2002-04-16 03:56:00.000000', NULL, 1),
(46803, 803, 245, '<td valign="top">I''d like to see more of his head, he''s peeling back off the photo!</td>', 'I''d like to see more of his head, he''s peeling back off the photo!', '2002-04-16 04:19:00.000000', NULL, 1),
(46804, 803, 255, '<td valign="top">great angle, great shot.</td>', 'great angle, great shot.', '2002-04-16 15:41:00.000000', NULL, 1),
(46805, 803, 524, '<td valign="top">no action</td>', 'no action', '2002-04-16 18:11:00.000000', NULL, 1),
(46806, 803, 811, '<td valign="top">Good perspective  Glad you got the guy singing, otherwise it may have looked like he was just standing there.  Perhaps a stopped shot of a drummer would''ve been more, um, obvious?</td>', 'Good perspective  Glad you got the guy singing, otherwise it may have looked like he was just standing there.  Perhaps a stopped shot of a drummer would''ve been more, um, obvious?', '2002-04-17 16:28:00.000000', NULL, 1),
(46807, 803, 441, '<td valign="top">good pic</td>', 'good pic', '2002-04-17 17:34:00.000000', NULL, 1),
(46808, 803, 472, '<td valign="top">good angled photo, with interesting light, but not a very strong example of ''stopped motion''</td>', 'good angled photo, with interesting light, but not a very strong example of ''stopped motion''', '2002-04-17 18:06:00.000000', NULL, 1),
(46809, 803, 2, '<td valign="top">I like the angle you''ve chosen -- it definitely makes the shot.</td>', 'I like the angle you''ve chosen -- it definitely makes the shot.', '2002-04-18 00:17:00.000000', NULL, 1),
(46810, 803, 205, '<td valign="top">Maybe if it was dude jumping in the air with a guitar I would know why this qualifys as stop motion.</td>', 'Maybe if it was dude jumping in the air with a guitar I would know why this qualifys as stop motion.', '2002-04-18 02:37:00.000000', NULL, 1),
(46811, 803, 301, '<td valign="top">doesn''t really fall into my definition of stopped motion.  Yes the guy is playing a guitar</td>', 'doesn''t really fall into my definition of stopped motion.  Yes the guy is playing a guitar', '2002-04-18 10:07:00.000000', NULL, 1),
(46812, 803, 543, '<td valign="top">Better not rotated 90° CW.  Not the greatest use of negative space, but okay.  Right side (top) needs some flash, too.  Looks like the flash auto sensor was tricked by the glare from the pickup.</td>', 'Better not rotated 90° CW.  Not the greatest use of negative space, but okay.  Right side (top) needs some flash, too.  Looks like the flash auto sensor was tricked by the glare from the pickup.', '2002-04-18 10:08:00.000000', NULL, 1),
(46813, 803, 330, '<td valign="top">Nice picture and I like the angle but I really don''t see much action.</td>', 'Nice picture and I like the angle but I really don''t see much action.', '2002-04-18 10:58:00.000000', NULL, 1),
(46814, 803, 933, '<td valign="top">Not a bad shot.  Interesting composition.  Like it better the more I look at it.</td>', 'Not a bad shot.  Interesting composition.  Like it better the more I look at it.', '2002-04-18 14:13:00.000000', NULL, 1),
(46815, 803, 714, '<td valign="top">I like the lighting <br/></td>', 'I like the lighting ', '2002-04-18 19:09:00.000000', NULL, 1),
(46816, 803, 739, '<td valign="top">He might have been moving, but he could just as easy posed for this shot.  Doesn''t convene the message of motion in this picture.</td>', 'He might have been moving, but he could just as easy posed for this shot.  Doesn''t convene the message of motion in this picture.', '2002-04-19 01:24:00.000000', NULL, 1),
(46817, 803, 797, '<td valign="top">i had the same problem.. a stop action looking like a still life. or maybe this IS a still life? i see you really love your guitar! so do i.</td>', 'i had the same problem.. a stop action looking like a still life. or maybe this IS a still life? i see you really love your guitar! so do i.', '2002-04-19 02:26:00.000000', NULL, 1),
(46818, 803, 1175, '<td valign="top">Nice piece.  I''d prefer more implied motion.</td>', 'Nice piece.  I''d prefer more implied motion.', '2002-04-19 08:48:00.000000', NULL, 1),
(46819, 803, 1164, '<td valign="top">what motion did you stop</td>', 'what motion did you stop', '2002-04-19 10:32:00.000000', NULL, 1),
(46820, 803, 361, '<td valign="top">Good perspective on this photo. Somehow, even though I know his hand is moving, I just don''t like this photo for this challenge. It still scores above average.</td>', 'Good perspective on this photo. Somehow, even though I know his hand is moving, I just don''t like this photo for this challenge. It still scores above average.', '2002-04-19 18:35:00.000000', NULL, 1),
(46821, 803, 113, '<td valign="top">Nice angle.  I like it in black and white.</td>', 'Nice angle.  I like it in black and white.', '2002-04-20 06:24:00.000000', NULL, 1),
(46822, 803, 637, '<td valign="top">not clear that there is any motion here</td>', 'not clear that there is any motion here', '2002-04-20 13:32:00.000000', NULL, 1),
(46823, 803, 1, '<td valign="top">Bland subject that I think should''ve been rotated 90 degrees CW.</td>', 'Bland subject that I think should''ve been rotated 90 degrees CW.', '2002-04-21 12:05:00.000000', NULL, 1),
(46824, 803, 734, '<td valign="top">All of the water pics did better than yours.... go figure</td>', 'All of the water pics did better than yours.... go figure', '2002-04-25 13:56:00.000000', NULL, 0),
(46825, 803, 2, '<td valign="top">a guitar picture.. go figure</td>', 'a guitar picture.. go figure', '2002-04-23 11:35:00.000000', NULL, 0),
(46826, 805, 656, '<td valign="top">Nice framing and good shot.  Not convinced this is digital though, due to the spots</td>', 'Nice framing and good shot.  Not convinced this is digital though, due to the spots', '2002-04-15 08:05:00.000000', NULL, 1),
(46827, 805, 92, '<td valign="top">GREAT capture !!!!!</td>', 'GREAT capture !!!!!', '2002-04-15 09:36:00.000000', NULL, 1),
(46828, 805, 509, '<td valign="top">This is a very cool shot.  Where are you from? There aren''t any jets like that in the United States, I''m pretty sure, you get a 10 from me</td>', 'This is a very cool shot.  Where are you from? There aren''t any jets like that in the United States, I''m pretty sure, you get a 10 from me', '2002-04-15 10:23:00.000000', NULL, 1),
(46829, 805, 189, '<td valign="top">Did you take this?</td>', 'Did you take this?', '2002-04-15 12:35:00.000000', NULL, 1),
(46830, 805, 641, '<td valign="top">lucky you, airshow in town? nice colors in the blues and whites.</td>', 'lucky you, airshow in town? nice colors in the blues and whites.', '2002-04-15 12:47:00.000000', NULL, 1),
(46831, 805, 772, '<td valign="top">Is this the Eurofighter?  This is a nice photo.  I wish the subject were larger in the frame and i wish the stopped motion wasn''t smoke.  Since there are no moving parts on the outside of the plane, this is like a gliding bird.  It''s not really moving.. you are moving the camera to follow it.  I used the analogy of photographing a ferrari on a flatbad railcar in a previous comment on a photo like this...</td>', 'Is this the Eurofighter?  This is a nice photo.  I wish the subject were larger in the frame and i wish the stopped motion wasn''t smoke.  Since there are no moving parts on the outside of the plane, this is like a gliding bird.  It''s not really moving.. you are moving the camera to follow it.  I used the analogy of photographing a ferrari on a flatbad railcar in a previous comment on a photo like this...', '2002-04-15 12:50:00.000000', NULL, 1),
(46832, 805, 203, '<td valign="top">Original for the challenge and a very nice shot.  I do see motion blurr on the kanards however.</td>', 'Original for the challenge and a very nice shot.  I do see motion blurr on the kanards however.', '2002-04-15 14:14:00.000000', NULL, 1),
(46833, 805, 441, '<td valign="top">composion and colour ok but subject not sharp.</td>', 'composion and colour ok but subject not sharp.', '2002-04-15 15:16:00.000000', NULL, 1),
(46834, 805, 527, '<td valign="top">So you had to come along and destroy the field? I see how it is. Well, you just wht til the next challenge. I''m gonna really, really, really try hard.     Most excellent!</td>', 'So you had to come along and destroy the field? I see how it is. Well, you just wht til the next challenge. I''m gonna really, really, really try hard.     Most excellent!', '2002-04-15 18:19:00.000000', NULL, 1),
(46835, 805, 245, '<td valign="top">I really wish the plane were slightly to the right so the contrail was furter from the edge. Like it''s easy to take a shot like this! :)</td>', 'I really wish the plane were slightly to the right so the contrail was furter from the edge. Like it''s easy to take a shot like this! :)', '2002-04-16 04:40:00.000000', NULL, 1),
(46836, 805, 748, '<td valign="top">I like the shot.  Just a little better focus and a bit closer would have really helped.</td>', 'I like the shot.  Just a little better focus and a bit closer would have really helped.', '2002-04-16 10:47:00.000000', NULL, 1),
(46837, 805, 813, '<td valign="top">Wow, very good and I imagine hard to get. Nice job!</td>', 'Wow, very good and I imagine hard to get. Nice job!', '2002-04-16 12:39:00.000000', NULL, 1),
(46838, 805, 715, '<td valign="top">Capturing a fighterplane mid-air, now that''s what I call stop motion. The position of the plane and it''s trail combined with the contrast between the blue sky and the white clouds, make it a fascinating photo.<br/></td>', 'Capturing a fighterplane mid-air, now that''s what I call stop motion. The position of the plane and it''s trail combined with the contrast between the blue sky and the white clouds, make it a fascinating photo.', '2002-04-16 13:40:00.000000', NULL, 1),
(46839, 805, 205, '<td valign="top">The plane is a little out of focus but this is still a great shot. Do the planes fly low where your from or do you just have a gigantic zoom lense attached to your camera?</td>', 'The plane is a little out of focus but this is still a great shot. Do the planes fly low where your from or do you just have a gigantic zoom lense attached to your camera?', '2002-04-16 18:11:00.000000', NULL, 1),
(46840, 805, 301, '<td valign="top">There is too much sky in this picture IMO.  Cropping would certainly have helped</td>', 'There is too much sky in this picture IMO.  Cropping would certainly have helped', '2002-04-17 09:15:00.000000', NULL, 1),
(46841, 805, 798, '<td valign="top">the smoke was captured perfectly</td>', 'the smoke was captured perfectly', '2002-04-17 12:03:00.000000', NULL, 1),
(46842, 805, 472, '<td valign="top">dang, that''s a killer shot!  the way the cloud arches over really adds to the interest of the picture.  good use of zoom</td>', 'dang, that''s a killer shot!  the way the cloud arches over really adds to the interest of the picture.  good use of zoom', '2002-04-17 12:06:00.000000', NULL, 1),
(46843, 805, 749, '<td valign="top">Hmm... forward canards, but twin engine, so it''s not a Gripen, and there aren''t enough hardpoints for a Typhoon... Rafale?</td>', 'Hmm... forward canards, but twin engine, so it''s not a Gripen, and there aren''t enough hardpoints for a Typhoon... Rafale?', '2002-04-17 18:39:00.000000', NULL, 1),
(46844, 805, 933, '<td valign="top">This is a pretty nice shot.  Seems just a tad out of focus though.</td>', 'This is a pretty nice shot.  Seems just a tad out of focus though.', '2002-04-17 19:00:00.000000', NULL, 1),
(46845, 805, 587, '<td valign="top">wow, must have one hell of a zoom! Great photo. something about the top right corner...to much cloud? Not sure.</td>', 'wow, must have one hell of a zoom! Great photo. something about the top right corner...to much cloud? Not sure.', '2002-04-18 07:13:00.000000', NULL, 1),
