(46847, 805, 811, '<td valign="top">There''s a lot of empty space (well, cloudy space) at the top.  If you could have zoomed in more, wow.  Beautiful sky.</td>', 'There''s a lot of empty space (well, cloudy space) at the top.  If you could have zoomed in more, wow.  Beautiful sky.', '2002-04-18 19:06:00.000000', NULL, 1),
(46848, 805, 142, '<td valign="top">This is a unique entry and I like the focus on the airplane.  Good job.</td>', 'This is a unique entry and I like the focus on the airplane.  Good job.', '2002-04-18 21:13:00.000000', NULL, 1),
