(46966, 818, 656, '<td valign="top">Cool shot, nice framing, great perspective.  Some fill flash might have brought out the subject more.</td>', 'Cool shot, nice framing, great perspective.  Some fill flash might have brought out the subject more.', '2002-04-15 08:26:00.000000', NULL, 1),
(46967, 818, 156, '<td valign="top">utilizing a flash would have made this better, the subject is too dark</td>', 'utilizing a flash would have made this better, the subject is too dark', '2002-04-15 08:47:00.000000', NULL, 1),
(46968, 818, 641, '<td valign="top">Good colors and looks like you caught it at the perfect moment. :) There is too much shadow on him though would like to see his expression better.</td>', 'Good colors and looks like you caught it at the perfect moment. :) There is too much shadow on him though would like to see his expression better.', '2002-04-15 09:53:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(46969, 818, 361, '<td valign="top">Good shot of the sky. Subject is too dark. Otherwise, it''s a good idea.</td>', 'Good shot of the sky. Subject is too dark. Otherwise, it''s a good idea.', '2002-04-15 11:32:00.000000', NULL, 1),
(46970, 818, 279, '<td valign="top">Too dark.</td>', 'Too dark.', '2002-04-15 13:05:00.000000', NULL, 1),
(46971, 818, 718, '<td valign="top">nice height, but the subject a little dark.</td>', 'nice height, but the subject a little dark.', '2002-04-15 14:15:00.000000', NULL, 1),
(46972, 818, 885, '<td valign="top">the jumper is a bit underexposed, maybe fill flash would have helped?</td>', 'the jumper is a bit underexposed, maybe fill flash would have helped?', '2002-04-15 14:47:00.000000', NULL, 1),
(46973, 818, 772, '<td valign="top">This is an interesting shot.  The framing is nice.  A fill flash may have made the detail of GOD stand out a little more.</td>', 'This is an interesting shot.  The framing is nice.  A fill flash may have made the detail of GOD stand out a little more.', '2002-04-15 16:14:00.000000', NULL, 1),
(46974, 818, 441, '<td valign="top">good shot well captured.</td>', 'good shot well captured.', '2002-04-15 17:04:00.000000', NULL, 1),
(46975, 818, 527, '<td valign="top">God is capitalized, and a god you are not. It''s still pretty interesting.</td>', 'God is capitalized, and a god you are not. It''s still pretty interesting.', '2002-04-15 17:13:00.000000', NULL, 1),
(46976, 818, 142, '<td valign="top">God looks younger than I pictured him.  Seriosly, this photo fits the challenge quite well.  If there were more lighting on the boy this would be an outstanding entry.</td>', 'God looks younger than I pictured him.  Seriosly, this photo fits the challenge quite well.  If there were more lighting on the boy this would be an outstanding entry.', '2002-04-15 18:52:00.000000', NULL, 1),
(46977, 818, 661, '<td valign="top">Figure is too dark.</td>', 'Figure is too dark.', '2002-04-15 19:33:00.000000', NULL, 1),
(46978, 818, 554, '<td valign="top">Sorry, but I don''t believe that is God.  Maybe the devil?<br/>You do good work but your title spoils the shot.....probably shouldn''t, but it does for some.  I think you enter for shock value anyway.</td>', 'Sorry, but I don''t believe that is God.  Maybe the devil?You do good work but your title spoils the shot.....probably shouldn''t, but it does for some.  I think you enter for shock value anyway.', '2002-04-15 21:35:00.000000', NULL, 1),
(46979, 818, 352, '<td valign="top">Cool angle!</td>', 'Cool angle!', '2002-04-15 22:55:00.000000', NULL, 1),
(46980, 818, 813, '<td valign="top">very good, nice composition, wish I could make out the face though</td>', 'very good, nice composition, wish I could make out the face though', '2002-04-16 12:32:00.000000', NULL, 1),
(46981, 818, 378, '<td valign="top">The subject needs to have better lighting</td>', 'The subject needs to have better lighting', '2002-04-16 14:48:00.000000', NULL, 1),
(46982, 818, 714, '<td valign="top">Good job.</td>', 'Good job.', '2002-04-16 15:19:00.000000', NULL, 1),
(46983, 818, 255, '<td valign="top">this is a very nicely framed shot, perhaps crop out just a little of the sky? I like it!</td>', 'this is a very nicely framed shot, perhaps crop out just a little of the sky? I like it!', '2002-04-16 15:47:00.000000', NULL, 1),
(46984, 818, 446, '<td valign="top">You definitely captured the spirit of motion here.  Nice composition.  You included just enough of the trees to give the photo depth and perspective, making the viewer feel that the subject is "way up in the air"  Almost in the clouds!  .  A little more exposure would have made this photo a winner.  Keep up the good work.</td>', 'You definitely captured the spirit of motion here.  Nice composition.  You included just enough of the trees to give the photo depth and perspective, making the viewer feel that the subject is "way up in the air"  Almost in the clouds!  .  A little more exposure would have made this photo a winner.  Keep up the good work.', '2002-04-16 17:51:00.000000', NULL, 1),
(46985, 818, 862, '<td valign="top">Nice stop.  I''d like it better if you compensated for the bright background or perhaps used a fill flash.</td>', 'Nice stop.  I''d like it better if you compensated for the bright background or perhaps used a fill flash.', '2002-04-17 07:44:00.000000', NULL, 1),
(46986, 818, 472, '<td valign="top">common mistake with backlit photos: either meter for the guy, not the whole scene, or use a fill flash.  either of those will make sure the guy isnt so dark.</td>', 'common mistake with backlit photos: either meter for the guy, not the whole scene, or use a fill flash.  either of those will make sure the guy isnt so dark.', '2002-04-17 18:03:00.000000', NULL, 1),
(46987, 818, 749, '<td valign="top">Needs light!</td>', 'Needs light!', '2002-04-17 18:33:00.000000', NULL, 1),
(46988, 818, 587, '<td valign="top">Well, maybe just another Bible Banger pouncing on his next victim!  :)  Wish he wasn''t so blurry and dark, good originality though.</td>', 'Well, maybe just another Bible Banger pouncing on his next victim!  :)  Wish he wasn''t so blurry and dark, good originality though.', '2002-04-17 19:53:00.000000', NULL, 1),
(46989, 818, 1132, '<td valign="top">Wish the main subject was not so dark. Should use spot metering in these situations if you can.</td>', 'Wish the main subject was not so dark. Should use spot metering in these situations if you can.', '2002-04-17 23:32:00.000000', NULL, 1),
(46990, 818, 543, '<td valign="top">If gawd looks like that, then all kinds of things suddenly make sense to me.  Fill flash would have saved this.</td>', 'If gawd looks like that, then all kinds of things suddenly make sense to me.  Fill flash would have saved this.', '2002-04-18 10:00:00.000000', NULL, 1),
(46991, 818, 671, '<td valign="top">Nice and dramatic, but too dark.  We need to see the expression more clearly.</td>', 'Nice and dramatic, but too dark.  We need to see the expression more clearly.', '2002-04-18 11:11:00.000000', NULL, 1),
(46992, 818, 933, '<td valign="top">Subject is too dark.  Good stop action though!</td>', 'Subject is too dark.  Good stop action though!', '2002-04-18 14:16:00.000000', NULL, 1),
(46993, 818, 205, '<td valign="top">Thats a little bit risky, but I won''t say anything because what if this really is god?</td>', 'Thats a little bit risky, but I won''t say anything because what if this really is god?', '2002-04-18 14:19:00.000000', NULL, 1),
(46994, 818, 797, '<td valign="top">would''ve gone for more exposure or a silhouette. but GOD falling?</td>', 'would''ve gone for more exposure or a silhouette. but GOD falling?', '2002-04-19 02:39:00.000000', NULL, 1),
(46995, 818, 1175, '<td valign="top">Fits critiera.  Bad lighting.</td>', 'Fits critiera.  Bad lighting.', '2002-04-19 08:47:00.000000', NULL, 1),
(46996, 818, 811, '<td valign="top">Lighter clothing or different lighting angle would have made this easy to see.  the subject''s face is really dark. It looks like he is jumping over the trees. :-)</td>', 'Lighter clothing or different lighting angle would have made this easy to see.  the subject''s face is really dark. It looks like he is jumping over the trees. :-)', '2002-04-19 09:27:00.000000', NULL, 1),
(46997, 818, 878, '<td valign="top">I think this one would of turned out a bit better if your subject was a bit brighter.</td>', 'I think this one would of turned out a bit better if your subject was a bit brighter.', '2002-04-19 16:14:00.000000', NULL, 1),
(46998, 818, 1191, '<td valign="top">Shame about the under-exposure</td>', 'Shame about the under-exposure', '2002-04-19 16:42:00.000000', NULL, 1),
(46999, 818, 689, '<td valign="top">Timing is good ... try going manual and that would let you bring out the face more.</td>', 'Timing is good ... try going manual and that would let you bring out the face more.', '2002-04-19 21:19:00.000000', NULL, 1),
(47000, 818, 113, '<td valign="top">NIce shot, good angle, maybe a little more light on the subject...</td>', 'NIce shot, good angle, maybe a little more light on the subject...', '2002-04-20 05:53:00.000000', NULL, 1),
(47001, 818, 1, '<td valign="top">Nice framing of the guy above the trees.  Work on your titles though.</td>', 'Nice framing of the guy above the trees.  Work on your titles though.', '2002-04-20 09:46:00.000000', NULL, 1),
(47002, 818, 1202, '<td valign="top">The boy is stopped nut exposure is poor, and if it were improved it make a major dofference in results.   The palm frawns'' sharp tips lead the eye to the subject, good there.</td>', 'The boy is stopped nut exposure is poor, and if it were improved it make a major dofference in results.   The palm frawns'' sharp tips lead the eye to the subject, good there.', '2002-04-20 11:19:00.000000', NULL, 1),
(47003, 818, 637, '<td valign="top">a little dark, otherwise great composition</td>', 'a little dark, otherwise great composition', '2002-04-20 13:23:00.000000', NULL, 1),
(47004, 818, 739, '<td valign="top">The subject is too dark.</td>', 'The subject is too dark.', '2002-04-20 20:21:00.000000', NULL, 1),
(47005, 818, 889, '<td valign="top">No motion blur but, Im betting the sun was up above/behind him because he is way too dark. <br/>Might want to try shooting the same shot later in afternoon with sun behind you.</td>', 'No motion blur but, Im betting the sun was up above/behind him because he is way too dark. Might want to try shooting the same shot later in afternoon with sun behind you.', '2002-04-21 17:09:00.000000', NULL, 1),
(47006, 818, 806, '<td valign="top">subject is too dark.</td>', 'subject is too dark.', '2002-04-21 18:41:00.000000', NULL, 1),
(47007, 818, 245, '<td valign="top">It''s too bad the sky was so bright, you lose a lot of detail in the underexposed flying guy. Did you try pumping the low/mid-tones with a levels adjustment? It would be hard to brighten the exposure in-camera without totally blowing out the sky!</td>', 'It''s too bad the sky was so bright, you lose a lot of detail in the underexposed flying guy. Did you try pumping the low/mid-tones with a levels adjustment? It would be hard to brighten the exposure in-camera without totally blowing out the sky!', '2002-04-22 00:40:00.000000', NULL, 1),
(47008, 820, 193, '<td valign="top">Kind of a new wave 80''s music video groove.  CDs and water?  It''s a bit busy, thus confusing.</td>', 'Kind of a new wave 80''s music video groove.  CDs and water?  It''s a bit busy, thus confusing.', '2002-04-15 07:53:00.000000', NULL, 1),
