(47158, 823, 714, '<td valign="top">This one makes me thirsty.  The water looks so clear.  Good job.</td>', 'This one makes me thirsty.  The water looks so clear.  Good job.', '2002-04-15 18:49:00.000000', NULL, 1),
(47159, 823, 131, '<td valign="top">looks like more water</td>', 'looks like more water', '2002-04-15 19:44:00.000000', NULL, 1),
(47160, 823, 813, '<td valign="top">Nice use of color</td>', 'Nice use of color', '2002-04-16 12:56:00.000000', NULL, 1),
(47161, 823, 715, '<td valign="top">I really like the atmosphere of the colors in this photo.</td>', 'I really like the atmosphere of the colors in this photo.', '2002-04-16 13:51:00.000000', NULL, 1),
(47162, 823, 378, '<td valign="top">Love the colors but I would like to see some of the bottom cropped.</td>', 'Love the colors but I would like to see some of the bottom cropped.', '2002-04-16 14:52:00.000000', NULL, 1),
(47163, 823, 255, '<td valign="top">cool color contrast-- i like the mix of hot and cold.</td>', 'cool color contrast-- i like the mix of hot and cold.', '2002-04-16 15:43:00.000000', NULL, 1),
(47164, 823, 2, '<td valign="top">Your amazing colors here have turned a mundane shot into an outstanding one.  Photo borders, though, are an circumvent challenge rules -- and they will be banned in the next challenge (they were supposed to be already).</td>', 'Your amazing colors here have turned a mundane shot into an outstanding one.  Photo borders, though, are an circumvent challenge rules -- and they will be banned in the next challenge (they were supposed to be already).', '2002-04-16 16:28:00.000000', NULL, 1),
(47165, 823, 205, '<td valign="top">I love the blue and the red,  getting closer could of help hear I''m finding that if your crop about two inches of the bottom I would of found this more favorable. Whats that red thing anyhow?</td>', 'I love the blue and the red,  getting closer could of help hear I''m finding that if your crop about two inches of the bottom I would of found this more favorable. Whats that red thing anyhow?', '2002-04-16 18:17:00.000000', NULL, 1),
(47166, 823, 509, '<td valign="top">Like the red and blues.  A bit overexposed though it seems</td>', 'Like the red and blues.  A bit overexposed though it seems', '2002-04-16 19:30:00.000000', NULL, 1),
(47167, 823, 910, '<td valign="top">nice colors</td>', 'nice colors', '2002-04-16 21:50:00.000000', NULL, 1),
(47168, 823, 689, '<td valign="top">C.L.R. will take care of those mineral deposits .... nice lighting on the water and the side</td>', 'C.L.R. will take care of those mineral deposits .... nice lighting on the water and the side', '2002-04-16 21:50:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(47169, 823, 441, '<td valign="top">nice use of colour to liven-up this otherwise mundane object.</td>', 'nice use of colour to liven-up this otherwise mundane object.', '2002-04-17 04:55:00.000000', NULL, 1),
(47170, 823, 472, '<td valign="top">what makes this pic for me are the colors.  please clean your soap scum off the metal : )</td>', 'what makes this pic for me are the colors.  please clean your soap scum off the metal : )', '2002-04-17 11:49:00.000000', NULL, 1),
(47171, 823, 811, '<td valign="top">The red really adds energy to the picture.</td>', 'The red really adds energy to the picture.', '2002-04-17 14:25:00.000000', NULL, 1),
(47172, 823, 933, '<td valign="top">Man, I hope you dont drink out of that thing!</td>', 'Man, I hope you dont drink out of that thing!', '2002-04-17 19:01:00.000000', NULL, 1),
(47173, 823, 1132, '<td valign="top">Neat colors but not quite sharp enough.</td>', 'Neat colors but not quite sharp enough.', '2002-04-17 19:52:00.000000', NULL, 1),
(47174, 823, 587, '<td valign="top">I like the twist in the water but the background pulls my eye away from it.</td>', 'I like the twist in the water but the background pulls my eye away from it.', '2002-04-18 07:02:00.000000', NULL, 1),
(47175, 823, 543, '<td valign="top">Very eye-catching colors, and nicely sharp.  Composition is a bit chopped at the bottom.</td>', 'Very eye-catching colors, and nicely sharp.  Composition is a bit chopped at the bottom.', '2002-04-18 12:03:00.000000', NULL, 1),
(47176, 823, 142, '<td valign="top">The lighting makes this photo more interesting.  Somehow the blue and red hues in the water look 3d.  Good job.</td>', 'The lighting makes this photo more interesting.  Somehow the blue and red hues in the water look 3d.  Good job.', '2002-04-18 21:04:00.000000', NULL, 1),
(47177, 823, 739, '<td valign="top">Wow! A simple title, but certainly a great shot.  Love the lighting.  The reflection of the red bottle in the water is phenomenal.  I love the texture of the water.  It looks like clear ice.  Great job!!...except for the calcium deposits ;-p</td>', 'Wow! A simple title, but certainly a great shot.  Love the lighting.  The reflection of the red bottle in the water is phenomenal.  I love the texture of the water.  It looks like clear ice.  Great job!!...except for the calcium deposits ;-p', '2002-04-19 01:30:00.000000', NULL, 1),
(47178, 823, 245, '<td valign="top">where did the rest of the picture go? the colors are nice, but the size isn''t legal...</td>', 'where did the rest of the picture go? the colors are nice, but the size isn''t legal...', '2002-04-19 02:41:00.000000', NULL, 1),
(47179, 823, 797, '<td valign="top">nice colors. and i like the shape of water here.</td>', 'nice colors. and i like the shape of water here.', '2002-04-19 03:45:00.000000', NULL, 1),
(47180, 823, 301, '<td valign="top">lighting gives this an interesting effect. I would have given the tap a shine ... the old watermarks are just too ugly for my liking</td>', 'lighting gives this an interesting effect. I would have given the tap a shine ... the old watermarks are just too ugly for my liking', '2002-04-19 07:33:00.000000', NULL, 1),
(47181, 823, 1041, '<td valign="top">I like the red glass in the background.  Would''ve been nicer if the tap had been cleaned.</td>', 'I like the red glass in the background.  Would''ve been nicer if the tap had been cleaned.', '2002-04-19 08:24:00.000000', NULL, 1),
(47182, 823, 1164, '<td valign="top">great colors</td>', 'great colors', '2002-04-19 10:58:00.000000', NULL, 1),
(47183, 823, 1175, '<td valign="top">Over done.</td>', 'Over done.', '2002-04-19 15:26:00.000000', NULL, 1),
(47184, 823, 113, '<td valign="top">It''s alive!!  Cool colors.  Chopped off its head.  I think you would have had a better photo minus the faucet.</td>', 'It''s alive!!  Cool colors.  Chopped off its head.  I think you would have had a better photo minus the faucet.', '2002-04-20 04:45:00.000000', NULL, 1),
(47185, 823, 1202, '<td valign="top">Interesting color mix and the water is stopped, however it is a subject that has been beat to death.</td>', 'Interesting color mix and the water is stopped, however it is a subject that has been beat to death.', '2002-04-20 10:52:00.000000', NULL, 1),
(47186, 823, 346, '<td valign="top">great detail on the sink, water.</td>', 'great detail on the sink, water.', '2002-04-21 08:01:00.000000', NULL, 1),
(47187, 823, 1, '<td valign="top">Great colors, although I''m not sure they blend well together by where they are placed.  The offset red is distracting, but does add a nice touch to the water.</td>', 'Great colors, although I''m not sure they blend well together by where they are placed.  The offset red is distracting, but does add a nice touch to the water.', '2002-04-21 12:05:00.000000', NULL, 1),
(47188, 823, 1135, '<td valign="top">Nice color</td>', 'Nice color', '2002-04-21 18:05:00.000000', NULL, 1),
(47189, 823, 734, '<td valign="top">Even thought it was a water shot, I had fun shooting it,.. and yes I should clean that tap.  As far as the boarders I was having a hard time getting the photo scaled to 640x480 so I had to get creative so I wouldnt loose the quality of the image.  Well good luck to all the winners.</td>', 'Even thought it was a water shot, I had fun shooting it,.. and yes I should clean that tap.  As far as the boarders I was having a hard time getting the photo scaled to 640x480 so I had to get creative so I wouldnt loose the quality of the image.  Well good luck to all the winners.', '2002-04-22 22:45:00.000000', NULL, 0),
(47194, 826, 656, '<td valign="top">The background kills this for me - maybe lying on your back on the blue mat, shooting up would have been better - if you could have talked your way in :)</td>', 'The background kills this for me - maybe lying on your back on the blue mat, shooting up would have been better - if you could have talked your way in :)', '2002-04-15 10:47:00.000000', NULL, 1),
(47195, 826, 640, '<td valign="top">Looks like he''s sitting on the fence</td>', 'Looks like he''s sitting on the fence', '2002-04-15 11:49:00.000000', NULL, 1),
(47196, 826, 361, '<td valign="top">Would have liked it better if it had been cropped to remove some of the busy background and enlarge the stopped motion subject.</td>', 'Would have liked it better if it had been cropped to remove some of the busy background and enlarge the stopped motion subject.', '2002-04-15 11:59:00.000000', NULL, 1),
(47197, 826, 189, '<td valign="top">Original</td>', 'Original', '2002-04-15 12:39:00.000000', NULL, 1),
(47198, 826, 734, '<td valign="top">another angles might have been more dramatic.. nice shot though</td>', 'another angles might have been more dramatic.. nice shot though', '2002-04-15 12:40:00.000000', NULL, 1),
(47199, 826, 279, '<td valign="top">Wow, tighter framing would''ve made this a REALLY cool shot. I''d have been embarassed to just go up and ask to photograph them though!</td>', 'Wow, tighter framing would''ve made this a REALLY cool shot. I''d have been embarassed to just go up and ask to photograph them though!', '2002-04-15 12:58:00.000000', NULL, 1),
(47200, 826, 641, '<td valign="top">good stop motion, but the contrast is a little too bright.</td>', 'good stop motion, but the contrast is a little too bright.', '2002-04-15 13:00:00.000000', NULL, 1),
(47201, 826, 714, '<td valign="top">This photo is to busy for me. Maybe if you got under or even closer to the subject.  :)</td>', 'This photo is to busy for me. Maybe if you got under or even closer to the subject.  :)', '2002-04-15 14:41:00.000000', NULL, 1),
(47202, 826, 1031, '<td valign="top">I like the contrast of the repeating straight lines in the foreground with the cacophony of curvature in the background.</td>', 'I like the contrast of the repeating straight lines in the foreground with the cacophony of curvature in the background.', '2002-04-15 14:49:00.000000', NULL, 1),
(47203, 826, 772, '<td valign="top">This is an interesting photo.  I have commented on some other photos similarly.  I don''t like photos of people from behind.  This shot would be more impressive taken from the side of the vaulter rather than from behind possibly.  The cropping should have attempted to include or eliminate the person on the right edge rather than splitting him.</td>', 'This is an interesting photo.  I have commented on some other photos similarly.  I don''t like photos of people from behind.  This shot would be more impressive taken from the side of the vaulter rather than from behind possibly.  The cropping should have attempted to include or eliminate the person on the right edge rather than splitting him.', '2002-04-15 17:42:00.000000', NULL, 1),
(47204, 826, 536, '<td valign="top">I think shooting from the other side of the mat would have been more interesting.  This is a little passive and confused. It almost looks like he is trying to clear the fence.  Good job on meeting the challenge.</td>', 'I think shooting from the other side of the mat would have been more interesting.  This is a little passive and confused. It almost looks like he is trying to clear the fence.  Good job on meeting the challenge.', '2002-04-15 20:16:00.000000', NULL, 1),
(47205, 826, 813, '<td valign="top">would be a lot more effective if shot from opposite side,  lower angel and tightly framed, that way you might empasive the vaulters objective of clearing the high bar</td>', 'would be a lot more effective if shot from opposite side,  lower angel and tightly framed, that way you might empasive the vaulters objective of clearing the high bar', '2002-04-16 15:02:00.000000', NULL, 1),
(47206, 826, 445, '<td valign="top">Could have been so much better a second later.</td>', 'Could have been so much better a second later.', '2002-04-16 17:11:00.000000', NULL, 1),
(47207, 826, 689, '<td valign="top">Seems a little blurred ... you might have tried shooting this from the side or in front ...</td>', 'Seems a little blurred ... you might have tried shooting this from the side or in front ...', '2002-04-16 21:52:00.000000', NULL, 1),
(47208, 826, 301, '<td valign="top">good stop motion.  I find the background distracting though.  Do well to crop the head in the foreground and person on the right</td>', 'good stop motion.  I find the background distracting though.  Do well to crop the head in the foreground and person on the right', '2002-04-17 09:10:00.000000', NULL, 1),
(47209, 826, 472, '<td valign="top">good sports shot. would be better if you went closer in on the 2 boys. they tend to get lost in the overall composition as it is.</td>', 'good sports shot. would be better if you went closer in on the 2 boys. they tend to get lost in the overall composition as it is.', '2002-04-17 12:01:00.000000', NULL, 1),
(47210, 826, 441, '<td valign="top">did he get over? - nice shot, bit closer in portrait position and later would have been better.</td>', 'did he get over? - nice shot, bit closer in portrait position and later would have been better.', '2002-04-17 17:10:00.000000', NULL, 1),
(47211, 826, 2, '<td valign="top">Really good idea for stopped action, though I think maybe a closer shot or lower angle would have made it that much better.</td>', 'Really good idea for stopped action, though I think maybe a closer shot or lower angle would have made it that much better.', '2002-04-18 00:27:00.000000', NULL, 1),
(47212, 826, 205, '<td valign="top">A closer up shot would have been more favorable plus having tooken the picture at the apex and a different angle</td>', 'A closer up shot would have been more favorable plus having tooken the picture at the apex and a different angle', '2002-04-18 02:57:00.000000', NULL, 1),
(47213, 826, 142, '<td valign="top">Good capture.  It would be more dramatic if you zoomed in on the pole vaulter more.</td>', 'Good capture.  It would be more dramatic if you zoomed in on the pole vaulter more.', '2002-04-18 11:21:00.000000', NULL, 1),
(47214, 826, 811, '<td valign="top">From the side or front, and being closer may have made this more interesting.</td>', 'From the side or front, and being closer may have made this more interesting.', '2002-04-18 15:34:00.000000', NULL, 1),
(47215, 826, 1164, '<td valign="top">You should have gotten this picture from the front angel, just an idea</td>', 'You should have gotten this picture from the front angel, just an idea', '2002-04-18 16:10:00.000000', NULL, 1),
(47216, 826, 245, '<td valign="top">i would have tried moving the framing down a little so you could see the whole kid in the front, and the mat to boot. it would also make the valut feel higher and more daring!</td>', 'i would have tried moving the framing down a little so you could see the whole kid in the front, and the mat to boot. it would also make the valut feel higher and more daring!', '2002-04-19 02:18:00.000000', NULL, 1),
(47217, 826, 587, '<td valign="top">great shot! Hope he made it ;)</td>', 'great shot! Hope he made it ;)', '2002-04-19 07:54:00.000000', NULL, 1),
(47218, 826, 797, '<td valign="top">great moment.</td>', 'great moment.', '2002-04-19 08:30:00.000000', NULL, 1),
(47219, 826, 1175, '<td valign="top">Nice try.  This would have been great if you could have gotten the guy as he was going over the cross bar.</td>', 'Nice try.  This would have been great if you could have gotten the guy as he was going over the cross bar.', '2002-04-19 09:22:00.000000', NULL, 1),
(47220, 826, 739, '<td valign="top">Feels too much like a snap shot...I don''t like the head in the lower right corner.  And the color is washed out.  Overall, it''s not compositional interesting.</td>', 'Feels too much like a snap shot...I don''t like the head in the lower right corner.  And the color is washed out.  Overall, it''s not compositional interesting.', '2002-04-20 01:25:00.000000', NULL, 1),
(47221, 826, 113, '<td valign="top">Good subject idea, maybe a different angle wouldn''t have lost the subject in the background.</td>', 'Good subject idea, maybe a different angle wouldn''t have lost the subject in the background.', '2002-04-20 05:15:00.000000', NULL, 1),
(47222, 826, 543, '<td valign="top">I used to do that.  What was I thinking!?  Probably more impact from the other side of the pit, and a chance to catch the vaulter''s face and get him framed against the sky instead of those trees.  Tell him to straighten that left arm and get his head back, too, or he''ll never break 10''.</td>', 'I used to do that.  What was I thinking!?  Probably more impact from the other side of the pit, and a chance to catch the vaulter''s face and get him framed against the sky instead of those trees.  Tell him to straighten that left arm and get his head back, too, or he''ll never break 10''.', '2002-04-20 05:46:00.000000', NULL, 1),
(47223, 826, 1202, '<td valign="top">Background way to busy.   Would have had better effect if taken from the side of subject.</td>', 'Background way to busy.   Would have had better effect if taken from the side of subject.', '2002-04-20 09:49:00.000000', NULL, 1),
(47224, 826, 933, '<td valign="top">Too many distracting elements - the guy coming into the frame on the right, the head in the lower right, the guy in the white shirt.  I think a tighter crop would really benefit this image.</td>', 'Too many distracting elements - the guy coming into the frame on the right, the head in the lower right, the guy in the white shirt.  I think a tighter crop would really benefit this image.', '2002-04-21 02:57:00.000000', NULL, 1),
(47225, 826, 1, '<td valign="top">A better crop of the actual vaulter would''ve been more suitable for this type of shot.</td>', 'A better crop of the actual vaulter would''ve been more suitable for this type of shot.', '2002-04-21 11:40:00.000000', NULL, 1),
(47226, 826, 1135, '<td valign="top">Did he make it?</td>', 'Did he make it?', '2002-04-21 18:07:00.000000', NULL, 1),
(47227, 826, 806, '<td valign="top">a side view would have been prime!</td>', 'a side view would have been prime!', '2002-04-21 18:16:00.000000', NULL, 1),
(47228, 826, 428, '<td valign="top">Thanks for all the comments! I had really intended to get this picture of him going over the bar, but alas, my timing was off. It has taken me several more tries to figure out exactly how to get my camera to do exactly what I want it to do! <br/><br/>I know that most of you wanted to see a shot from the front or side, but it is not allowed to be in that part of the pit, (too distracting for the valuter and also dangerous!) In fact, I was too close as it was and was asked to move!  Plus if I could have gotten the timing perfect, you could have seen the front because as the vaulter goes over the bar they turn  and then they are facing this direction. <br/><br/>Now as for composition, I wanted to show the height of the bar, hence the bigger framing.  The boys on either side are there for the safety of the vaulter, (like a spotter) and there is no way to get them out of the shot without cropping.  <br/><br/>As for cropping, I am limited by my camera on this one, as it takes a max shot of 640x480 and to do any cropping leads to distortion of the pic to get it back to the required size.  I am trying to get the compostion to the right size to start off with. That is a challenge in itself!!<br/><br/>Actually I liked the trees in the background, I know many of you said it was too busy, but I thought they gave an interesting look to the pic, rather than just a blue sky.<br/><br/>He actually did make it over the bar, but hit it with his body on the way down. <br/><br/>Thanks again for all the comments, I appreciate them all!</td>', 'Thanks for all the comments! I had really intended to get this picture of him going over the bar, but alas, my timing was off. It has taken me several more tries to figure out exactly how to get my camera to do exactly what I want it to do! I know that most of you wanted to see a shot from the front or side, but it is not allowed to be in that part of the pit, (too distracting for the valuter and also dangerous!) In fact, I was too close as it was and was asked to move!  Plus if I could have gotten the timing perfect, you could have seen the front because as the vaulter goes over the bar they turn  and then they are facing this direction. Now as for composition, I wanted to show the height of the bar, hence the bigger framing.  The boys on either side are there for the safety of the vaulter, (like a spotter) and there is no way to get them out of the shot without cropping.  As for cropping, I am limited by my camera on this one, as it takes a max shot of 640x480 and to do any cropping leads to distortion of the pic to get it back to the required size.  I am trying to get the compostion to the right size to start off with. That is a challenge in itself!!Actually I liked the trees in the background, I know many of you said it was too busy, but I thought they gave an interesting look to the pic, rather than just a blue sky.He actually did make it over the bar, but hit it with his body on the way down. Thanks again for all the comments, I appreciate them all!', '2002-04-22 09:19:00.000000', NULL, 0),
(47229, 827, 107, '<td valign="top">what a waste of Jack Daniels!!!!  Captures the moment wonderfully.</td>', 'what a waste of Jack Daniels!!!!  Captures the moment wonderfully.', '2002-04-15 06:28:00.000000', NULL, 1),
(47230, 827, 157, '<td valign="top">mmmmmmmmmm.....whiskeyyyyyy</td>', 'mmmmmmmmmm.....whiskeyyyyyy', '2002-04-15 07:58:00.000000', NULL, 1),
(47231, 827, 156, '<td valign="top">well now that was a waste of good whiskey ;o)</td>', 'well now that was a waste of good whiskey ;o)', '2002-04-15 08:22:00.000000', NULL, 1),
(47232, 827, 641, '<td valign="top">Outstanding... color, stop action and fun. I like it ;)</td>', 'Outstanding... color, stop action and fun. I like it ;)', '2002-04-15 09:41:00.000000', NULL, 1),
(47233, 827, 656, '<td valign="top">what a waste!  I hope that''s tea and not booze you are splashing around...</td>', 'what a waste!  I hope that''s tea and not booze you are splashing around...', '2002-04-15 10:34:00.000000', NULL, 1),
(47234, 827, 509, '<td valign="top">would have benifitted from a longer exposure</td>', 'would have benifitted from a longer exposure', '2002-04-15 10:36:00.000000', NULL, 1),
(47235, 827, 92, '<td valign="top">GREAT action ! Well done:)</td>', 'GREAT action ! Well done:)', '2002-04-15 10:44:00.000000', NULL, 1),
(47236, 827, 640, '<td valign="top">Nice! It has style</td>', 'Nice! It has style', '2002-04-15 11:50:00.000000', NULL, 1),
(47237, 827, 139, '<td valign="top">Nice "shot"''.</td>', 'Nice "shot"''.', '2002-04-15 12:36:00.000000', NULL, 1),
(47238, 827, 714, '<td valign="top">Great photo, don''t care for the drink, but i like how you got the bottle in the background and the lighting is great. You did a great job.</td>', 'Great photo, don''t care for the drink, but i like how you got the bottle in the background and the lighting is great. You did a great job.', '2002-04-15 12:41:00.000000', NULL, 1),
(47239, 827, 675, '<td valign="top">mmmmm, whiskey</td>', 'mmmmm, whiskey', '2002-04-15 13:32:00.000000', NULL, 1),
(47240, 827, 734, '<td valign="top">I think this is a wonderful shot</td>', 'I think this is a wonderful shot', '2002-04-15 14:04:00.000000', NULL, 1),
(47241, 827, 203, '<td valign="top">Tell me you didn''t waste that "Old No. 7".  You got an extra point because it is not water.</td>', 'Tell me you didn''t waste that "Old No. 7".  You got an extra point because it is not water.', '2002-04-15 14:19:00.000000', NULL, 1),
(47242, 827, 1031, '<td valign="top">I''m only concerned for how much JD had to be sacrificed to achieve this "shot."</td>', 'I''m only concerned for how much JD had to be sacrificed to achieve this "shot."', '2002-04-15 14:52:00.000000', NULL, 1),
(47243, 827, 748, '<td valign="top">What a great shot!  I like the dark backfround and the focus.</td>', 'What a great shot!  I like the dark backfround and the focus.', '2002-04-15 14:52:00.000000', NULL, 1),
(47244, 827, 804, '<td valign="top">Excellent shot!!  Good lighting, composition and balance. I like that you used Jack rather than water....adds much needed color to the photo.</td>', 'Excellent shot!!  Good lighting, composition and balance. I like that you used Jack rather than water....adds much needed color to the photo.', '2002-04-15 15:54:00.000000', NULL, 1),
(47245, 827, 772, '<td valign="top">Excellent photo!  This scores well with me.  I would like to see the JD bottle pulled all the way into the frame.  I also commend you on your use of the lighting from an angled source rather than your camera flash.  This really improves the quality of this photo :)</td>', 'Excellent photo!  This scores well with me.  I would like to see the JD bottle pulled all the way into the frame.  I also commend you on your use of the lighting from an angled source rather than your camera flash.  This really improves the quality of this photo :)', '2002-04-15 16:17:00.000000', NULL, 1),
(47246, 827, 527, '<td valign="top">This is very well done. I bet you needed a drink when you were finished.</td>', 'This is very well done. I bet you needed a drink when you were finished.', '2002-04-15 18:40:00.000000', NULL, 1),
(47247, 827, 661, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2002-04-15 19:44:00.000000', NULL, 1),
