(47289, 829, 724, '<td valign="top">I tried this same idea and couldn''t get the timing down.  Congratulations, nice job.</td>', 'I tried this same idea and couldn''t get the timing down.  Congratulations, nice job.', '2002-04-15 22:46:00.000000', NULL, 1),
(47290, 829, 245, '<td valign="top">You could have taken an even shorter exposure, the water in the glass is pretty bright. You need more depth of field, too, a lot of the glass isn''t crisp. The lip is nice and sharp, but all the water splashing around is hard to see.</td>', 'You could have taken an even shorter exposure, the water in the glass is pretty bright. You need more depth of field, too, a lot of the glass isn''t crisp. The lip is nice and sharp, but all the water splashing around is hard to see.', '2002-04-16 04:29:00.000000', NULL, 1),
(47291, 829, 352, '<td valign="top">Did you try this with more ambient light and no flash?  It leaves a hot spot at the bottom of the pictue which is not appealing to me.</td>', 'Did you try this with more ambient light and no flash?  It leaves a hot spot at the bottom of the pictue which is not appealing to me.', '2002-04-16 10:47:00.000000', NULL, 1),
