(47431, 835, 813, '<td valign="top">nice focus, action freeze, but lacks point of intrerest, my eye wanders around not knowing whre to rest</td>', 'nice focus, action freeze, but lacks point of intrerest, my eye wanders around not knowing whre to rest', '2002-04-16 13:40:00.000000', NULL, 1),
(47432, 835, 441, '<td valign="top">lots of action stopped here</td>', 'lots of action stopped here', '2002-04-16 14:42:00.000000', NULL, 1),
(47433, 835, 472, '<td valign="top">good bubbly water texture.</td>', 'good bubbly water texture.', '2002-04-17 11:52:00.000000', NULL, 1),
(47434, 835, 749, '<td valign="top">Great focus, with all the ripples visible. Maybe a different lighting angle would have helped?</td>', 'Great focus, with all the ripples visible. Maybe a different lighting angle would have helped?', '2002-04-17 16:14:00.000000', NULL, 1),
(47435, 835, 811, '<td valign="top">Needs something -- maybe a different angle so the drain isn''t so straight on.</td>', 'Needs something -- maybe a different angle so the drain isn''t so straight on.', '2002-04-17 16:33:00.000000', NULL, 1),
(47436, 835, 361, '<td valign="top">Good stopped action. Clean sink (wow!).</td>', 'Good stopped action. Clean sink (wow!).', '2002-04-17 18:20:00.000000', NULL, 1),
