(47539, 838, 2, '<td valign="top">The frame of the picture sugguests that the surroundings have something to do with the object splashing -- but since we can''t see that object, I''m left just wondering what I''m missing.</td>', 'The frame of the picture sugguests that the surroundings have something to do with the object splashing -- but since we can''t see that object, I''m left just wondering what I''m missing.', '2002-04-16 15:02:00.000000', NULL, 1),
(47540, 838, 361, '<td valign="top">Reminds me of when I was younger and liked to throw rocks in the lake. I like this... the action is close, and there is enough background to "set the mood."</td>', 'Reminds me of when I was younger and liked to throw rocks in the lake. I like this... the action is close, and there is enough background to "set the mood."', '2002-04-16 18:44:00.000000', NULL, 1),
(47541, 838, 205, '<td valign="top">A big splash and nice contrast on the rocks.</td>', 'A big splash and nice contrast on the rocks.', '2002-04-16 19:02:00.000000', NULL, 1),
(47542, 838, 441, '<td valign="top">nice composure and well caught and stopped.</td>', 'nice composure and well caught and stopped.', '2002-04-17 04:59:00.000000', NULL, 1),
(47543, 838, 472, '<td valign="top">this looks like some place interesting like lake powell</td>', 'this looks like some place interesting like lake powell', '2002-04-17 12:09:00.000000', NULL, 1),
