(47739, 844, 1175, '<td valign="top">Wow.  Anit-cliche (fire instead of water)</td>', 'Wow.  Anit-cliche (fire instead of water)', '2002-04-19 11:08:00.000000', NULL, 1),
(47740, 844, 689, '<td valign="top">I tried this, but my parents always said I shouldnt play with fire, so I stopped, but still you did well with this one.</td>', 'I tried this, but my parents always said I shouldnt play with fire, so I stopped, but still you did well with this one.', '2002-04-19 21:19:00.000000', NULL, 1),
(47741, 844, 113, '<td valign="top">Very pretty.  Fire is so hard to capture.  Center of flame is clear but the outer is blurred.</td>', 'Very pretty.  Fire is so hard to capture.  Center of flame is clear but the outer is blurred.', '2002-04-20 05:26:00.000000', NULL, 1),
(47742, 844, 1202, '<td valign="top">Difficult subject with good exposure, but not stopped action.</td>', 'Difficult subject with good exposure, but not stopped action.', '2002-04-20 09:28:00.000000', NULL, 1),
(47743, 844, 244, '<td valign="top">I like this one alot, the fire looks to have a life of it''s own <br/></td>', 'I like this one alot, the fire looks to have a life of it''s own ', '2002-04-20 16:21:00.000000', NULL, 1),
(47744, 844, 889, '<td valign="top">all that light, where is it going?</td>', 'all that light, where is it going?', '2002-04-21 17:29:00.000000', NULL, 1),
(47745, 844, 806, '<td valign="top">bye bye ink spots, hello fire pictures... "i think i see....."<br/>:-)</td>', 'bye bye ink spots, hello fire pictures... "i think i see.....":-)', '2002-04-21 18:21:00.000000', NULL, 1),
(47746, 844, 48, '<td valign="top">the reason the focus is off on the outside of the flame is because this is from the top. the center was about 2 feet away, and the outside, which is the top of the flame, was about 2 inches away. i accidentally left some shoe polish on my hand and it flashed up at me</td>', 'the reason the focus is off on the outside of the flame is because this is from the top. the center was about 2 feet away, and the outside, which is the top of the flame, was about 2 inches away. i accidentally left some shoe polish on my hand and it flashed up at me', '2002-04-22 03:12:00.000000', NULL, 0),
(47747, 844, 48, '<td valign="top">i meant nail polish remover. i had just woken up when i typed that</td>', 'i meant nail polish remover. i had just woken up when i typed that', '2002-04-22 06:07:00.000000', NULL, 0),
(47748, 845, 689, '<td valign="top">Your timing was FANTASTIC ... just off of that, you get my high score ... unless your family owns a light bulb factory.</td>', 'Your timing was FANTASTIC ... just off of that, you get my high score ... unless your family owns a light bulb factory.', '2002-04-15 01:10:00.000000', NULL, 1),
(47749, 845, 156, '<td valign="top">COOL! great capture</td>', 'COOL! great capture', '2002-04-15 08:26:00.000000', NULL, 1),
(47750, 845, 92, '<td valign="top">I love this capture ! Great job ! The only thing I would have done differently is crop the bottom out more, making it appear a bit more of a close up.</td>', 'I love this capture ! Great job ! The only thing I would have done differently is crop the bottom out more, making it appear a bit more of a close up.', '2002-04-15 09:30:00.000000', NULL, 1),
(47751, 845, 1055, '<td valign="top">this is terrific.  there is almost a feeling of drama to this picture.  i wonder, how many lightbulbs did you go through before you got this result?</td>', 'this is terrific.  there is almost a feeling of drama to this picture.  i wonder, how many lightbulbs did you go through before you got this result?', '2002-04-15 09:56:00.000000', NULL, 1),
(47752, 845, 173, '<td valign="top">Excellent! Mind ''shattering'' that you were able to capture that shot.</td>', 'Excellent! Mind ''shattering'' that you were able to capture that shot.', '2002-04-15 10:39:00.000000', NULL, 1),
(47753, 845, 813, '<td valign="top">Great timing! How many bulbs did you have to smash to get this?</td>', 'Great timing! How many bulbs did you have to smash to get this?', '2002-04-15 10:39:00.000000', NULL, 1),
(47754, 845, 714, '<td valign="top">Wow.  Great idea.  That thought never crossed my mind.<br/>I really like it.  Not fun to clean up though</td>', 'Wow.  Great idea.  That thought never crossed my mind.I really like it.  Not fun to clean up though', '2002-04-15 11:03:00.000000', NULL, 1),
