(47757, 845, 142, '<td valign="top">This is a beautifully done photo.  It is creative, shows good technique, and is definately stop action.</td>', 'This is a beautifully done photo.  It is creative, shows good technique, and is definately stop action.', '2002-04-15 12:24:00.000000', NULL, 1),
(47758, 845, 139, '<td valign="top">Excellent!  I tried this shot, and could not get it.  Great job, I love it.</td>', 'Excellent!  I tried this shot, and could not get it.  Great job, I love it.', '2002-04-15 12:32:00.000000', NULL, 1),
(47759, 845, 189, '<td valign="top">Original</td>', 'Original', '2002-04-15 12:33:00.000000', NULL, 1),
(47760, 845, 301, '<td valign="top">wow ... being picky - the camera is tilted, and I think a more even lighting may have helped (ie on the left hand side)... otherwise, I hope u didn''t have too many bulbs to clean up :)</td>', 'wow ... being picky - the camera is tilted, and I think a more even lighting may have helped (ie on the left hand side)... otherwise, I hope u didn''t have too many bulbs to clean up :)', '2002-04-15 12:42:00.000000', NULL, 1),
