(47762, 845, 641, '<td valign="top">whew..that had to be a mess to clean up. Good shot, but the speckles distract.</td>', 'whew..that had to be a mess to clean up. Good shot, but the speckles distract.', '2002-04-15 12:44:00.000000', NULL, 1),
(47763, 845, 279, '<td valign="top">Someone built themselves a flash trigger. Awesome shot! Could''ve used a horizontal surface for the bulb tho.</td>', 'Someone built themselves a flash trigger. Awesome shot! Could''ve used a horizontal surface for the bulb tho.', '2002-04-15 13:15:00.000000', NULL, 1),
(47764, 845, 718, '<td valign="top">Excellent timing, excellent picture.</td>', 'Excellent timing, excellent picture.', '2002-04-15 14:23:00.000000', NULL, 1),
(47765, 845, 885, '<td valign="top">great photo. maybe a little less black at the bottom?</td>', 'great photo. maybe a little less black at the bottom?', '2002-04-15 15:00:00.000000', NULL, 1),
(47766, 845, 772, '<td valign="top">This is cool!  Maybe I should have bought stock in GE before you started this project.  Please message me and tell me how many light bulbs it took to get this shot!  Excellent shot!  My only complaing is that I think a more interesting crop could have been applied.  There''s a lot of emptiness in the lower half of this photo.  The void in the bottom of this shot is the ONLY thing that is holding me back from a perfect 10.</td>', 'This is cool!  Maybe I should have bought stock in GE before you started this project.  Please message me and tell me how many light bulbs it took to get this shot!  Excellent shot!  My only complaing is that I think a more interesting crop could have been applied.  There''s a lot of emptiness in the lower half of this photo.  The void in the bottom of this shot is the ONLY thing that is holding me back from a perfect 10.', '2002-04-15 15:28:00.000000', NULL, 1),
(47767, 845, 308, '<td valign="top">Excellent shot - you fired this off right at an incredible moment and got a great stopped/frozen picture.</td>', 'Excellent shot - you fired this off right at an incredible moment and got a great stopped/frozen picture.', '2002-04-15 15:57:00.000000', NULL, 1),
(47768, 845, 527, '<td valign="top">Really cool. Other have to be wondering if this is scanned because of the colored specks. I''m giving you the benifit of the doubt and assumming they are just ''hot'' pixels or something else.</td>', 'Really cool. Other have to be wondering if this is scanned because of the colored specks. I''m giving you the benifit of the doubt and assumming they are just ''hot'' pixels or something else.', '2002-04-15 17:03:00.000000', NULL, 1),
(47769, 845, 675, '<td valign="top">damn good job</td>', 'damn good job', '2002-04-15 17:57:00.000000', NULL, 1),
(47770, 845, 554, '<td valign="top">Very Well Done ! In the top three. I did it with an egg but the results were not apparant without an explination. I would have prefered some backlighting. 10</td>', 'Very Well Done ! In the top three. I did it with an egg but the results were not apparant without an explination. I would have prefered some backlighting. 10', '2002-04-15 18:25:00.000000', NULL, 1),
(47771, 845, 782, '<td valign="top">By far the best demonstration of stopped motion so far</td>', 'By far the best demonstration of stopped motion so far', '2002-04-15 19:13:00.000000', NULL, 1),
(47772, 845, 536, '<td valign="top">I like this a lot.  It is original and interesting.  I''m ignoring the noise because of the difficulty of your photo.  Great job on meeting the challenge.</td>', 'I like this a lot.  It is original and interesting.  I''m ignoring the noise because of the difficulty of your photo.  Great job on meeting the challenge.', '2002-04-15 19:16:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(47773, 845, 446, '<td valign="top">Very Creative.  Extremely sharp.  The blown pixels (or noise?) is somewhat distracting to me.  Would have liked to see it cropped even tighter.  Keep up the good work.</td>', 'Very Creative.  Extremely sharp.  The blown pixels (or noise?) is somewhat distracting to me.  Would have liked to see it cropped even tighter.  Keep up the good work.', '2002-04-15 19:19:00.000000', NULL, 1),
(47774, 845, 773, '<td valign="top">Very creative idea....</td>', 'Very creative idea....', '2002-04-15 20:15:00.000000', NULL, 1),
(47775, 845, 145, '<td valign="top">Great shot! How many lightbulbs did you go through?</td>', 'Great shot! How many lightbulbs did you go through?', '2002-04-15 22:56:00.000000', NULL, 1),
(47776, 845, 1031, '<td valign="top">Hope you had a stash of burned-out bulbs available!</td>', 'Hope you had a stash of burned-out bulbs available!', '2002-04-16 00:04:00.000000', NULL, 1),
(47777, 845, 881, '<td valign="top">Wow, nice!  Are the colored dots noise?</td>', 'Wow, nice!  Are the colored dots noise?', '2002-04-16 01:37:00.000000', NULL, 1),
(47778, 845, 878, '<td valign="top">Really nice idea and shot, there a bit too many hot pixels though.  I dont know if Blank and White would "clear" them up a bit.</td>', 'Really nice idea and shot, there a bit too many hot pixels though.  I dont know if Blank and White would "clear" them up a bit.', '2002-04-16 10:19:00.000000', NULL, 1),
(47779, 845, 215, '<td valign="top">This is shocking... How did you manage to take the photo? Or shoud I be asking how many light bulbs did you have to break before you got a shot you were happy with? Hehe...</td>', 'This is shocking... How did you manage to take the photo? Or shoud I be asking how many light bulbs did you have to break before you got a shot you were happy with? Hehe...', '2002-04-16 13:13:00.000000', NULL, 1),
(47780, 845, 715, '<td valign="top">Very good shot!  I would have liked it even more if the impact was shown at the bottom half of the picture.</td>', 'Very good shot!  I would have liked it even more if the impact was shown at the bottom half of the picture.', '2002-04-16 13:30:00.000000', NULL, 1),
(47781, 845, 441, '<td valign="top">must have  been a heck of a job getting the timing anywhere near - unless you used electronic firing gear?</td>', 'must have  been a heck of a job getting the timing anywhere near - unless you used electronic firing gear?', '2002-04-16 14:22:00.000000', NULL, 1),
(47782, 845, 1078, '<td valign="top">I love this one.  Too bad about the digital hot spots, but you can''t do much about that without post-processing.  I wish the surface it was shattering on was either closer to or further away from level.</td>', 'I love this one.  Too bad about the digital hot spots, but you can''t do much about that without post-processing.  I wish the surface it was shattering on was either closer to or further away from level.', '2002-04-16 16:57:00.000000', NULL, 1),
(47783, 845, 361, '<td valign="top">Wow! Only suggestion is to maybe have the extra "blank space" above the bulb and not below.</td>', 'Wow! Only suggestion is to maybe have the extra "blank space" above the bulb and not below.', '2002-04-16 18:01:00.000000', NULL, 1),
(47784, 845, 205, '<td valign="top">I always wanted to try this but with a glass bottle of some kind, I don''t know why but I''m seeing pink and green dots, are these like digital dust spots?</td>', 'I always wanted to try this but with a glass bottle of some kind, I don''t know why but I''m seeing pink and green dots, are these like digital dust spots?', '2002-04-16 18:15:00.000000', NULL, 1),
(47785, 845, 332, '<td valign="top">Like the idea. But it''s kinda rough. High ISO speed?</td>', 'Like the idea. But it''s kinda rough. High ISO speed?', '2002-04-16 20:59:00.000000', NULL, 1),
(47786, 845, 445, '<td valign="top">Super stop!</td>', 'Super stop!', '2002-04-16 21:12:00.000000', NULL, 1),
