(47793, 845, 1009, '<td valign="top">Incredible idea and execution.</td>', 'Incredible idea and execution.', '2002-04-17 16:57:00.000000', NULL, 1),
(47794, 845, 749, '<td valign="top">Wow, great timing! The light is perfectly angled to pick up all the fragments too. Its a shame about all the artifacts though.</td>', 'Wow, great timing! The light is perfectly angled to pick up all the fragments too. Its a shame about all the artifacts though.', '2002-04-17 17:36:00.000000', NULL, 1),
(47795, 845, 884, '<td valign="top">Very pretty, good idea! I love the glimmering effect on the black.</td>', 'Very pretty, good idea! I love the glimmering effect on the black.', '2002-04-17 17:54:00.000000', NULL, 1),
(47796, 845, 255, '<td valign="top">this is a really cool shot.</td>', 'this is a really cool shot.', '2002-04-17 18:22:00.000000', NULL, 1),
(47797, 845, 933, '<td valign="top">Nice timing on this shot.</td>', 'Nice timing on this shot.', '2002-04-17 18:42:00.000000', NULL, 1),
(47798, 845, 1138, '<td valign="top">Excellent subject choice.  Reminiscent of the Harold Edgerton work.  No visible blur.</td>', 'Excellent subject choice.  Reminiscent of the Harold Edgerton work.  No visible blur.', '2002-04-17 21:56:00.000000', NULL, 1),
(47799, 845, 1132, '<td valign="top">Nicely captured. I wish the lightbulb would fill more of the frame or at least be placed lower within the frame. Perhaps shooting it in landscape would have been better. Still a well captured and sharp photo.</td>', 'Nicely captured. I wish the lightbulb would fill more of the frame or at least be placed lower within the frame. Perhaps shooting it in landscape would have been better. Still a well captured and sharp photo.', '2002-04-17 22:54:00.000000', NULL, 1),
(47800, 845, 2, '<td valign="top">This must have cost a fortune to shoot.  How''d you drop the lightbulb hard enough to break it and still catch the timing?  And where''d all the pink dots come from ... is this scanned?</td>', 'This must have cost a fortune to shoot.  How''d you drop the lightbulb hard enough to break it and still catch the timing?  And where''d all the pink dots come from ... is this scanned?', '2002-04-18 00:16:00.000000', NULL, 1),
