(47802, 845, 862, '<td valign="top">Now that is cool.  Great idea.</td>', 'Now that is cool.  Great idea.', '2002-04-18 08:32:00.000000', NULL, 1),
(47803, 845, 543, '<td valign="top">Appears to be drastically oversharpened judging from the noise.  A good idea, and well captured (cropping could improve the composition - too much room at the bottom), but something happened on the way to the web.</td>', 'Appears to be drastically oversharpened judging from the noise.  A good idea, and well captured (cropping could improve the composition - too much room at the bottom), but something happened on the way to the web.', '2002-04-18 12:22:00.000000', NULL, 1),
(47804, 845, 797, '<td valign="top">i hope that was an old bulb. nicely timed. great shot.</td>', 'i hope that was an old bulb. nicely timed. great shot.', '2002-04-19 04:00:00.000000', NULL, 1),
(47805, 845, 587, '<td valign="top">This is awesome. Great idea, great photo.</td>', 'This is awesome. Great idea, great photo.', '2002-04-19 07:48:00.000000', NULL, 1),
(47806, 845, 1175, '<td valign="top">Wow, great timing.</td>', 'Wow, great timing.', '2002-04-19 11:17:00.000000', NULL, 1),
