(47809, 845, 1202, '<td valign="top">This is a superb shot.  No background distractions, excellent focus, and excellent stop action.   Has qualities of a professional at work.</td>', 'This is a superb shot.  No background distractions, excellent focus, and excellent stop action.   Has qualities of a professional at work.', '2002-04-20 11:42:00.000000', NULL, 1),
