(47812, 845, 280, '<td valign="top">How many light bulbs did you smash to get this shot? Its a shame about the white speckles.</td>', 'How many light bulbs did you smash to get this shot? Its a shame about the white speckles.', '2002-04-20 18:12:00.000000', NULL, 1),
(47813, 845, 739, '<td valign="top">Very artistic.  Love the contrast.  Your timing is incredible.</td>', 'Very artistic.  Love the contrast.  Your timing is incredible.', '2002-04-20 20:17:00.000000', NULL, 1),
(47814, 845, 1135, '<td valign="top">Great Timing!!</td>', 'Great Timing!!', '2002-04-21 01:19:00.000000', NULL, 1),
(47815, 845, 1, '<td valign="top">Very well done.  Perfect timing, perfect framing, and a perfect black background.</td>', 'Very well done.  Perfect timing, perfect framing, and a perfect black background.', '2002-04-21 12:02:00.000000', NULL, 1),
(47816, 845, 806, '<td valign="top">i might straighten and crop some of the dark bottom off, but great shot.</td>', 'i might straighten and crop some of the dark bottom off, but great shot.', '2002-04-21 18:35:00.000000', NULL, 1),
