(47857, 847, 138, '<td valign="top">water.. go figure</td>', 'water.. go figure', '2002-04-15 14:59:00.000000', NULL, 1),
(47858, 847, 772, '<td valign="top">I like the artistic side of this photo.  The out of focus drops in the foreground and background make this a difficult photo to read where stopped motion is concerned.  It appears that your thin focal point is getting the drops in the center of this spray.  There are not enough ''focused and sharp'' drops here to really fire me up about stopped motion.</td>', 'I like the artistic side of this photo.  The out of focus drops in the foreground and background make this a difficult photo to read where stopped motion is concerned.  It appears that your thin focal point is getting the drops in the center of this spray.  There are not enough ''focused and sharp'' drops here to really fire me up about stopped motion.', '2002-04-15 15:46:00.000000', NULL, 1),
(47859, 847, 933, '<td valign="top">Kind of trippy.  Very nice.</td>', 'Kind of trippy.  Very nice.', '2002-04-15 15:50:00.000000', NULL, 1),
