(47910, 848, 689, '<td valign="top">Nice variation on the water theme ... plus having the drill bit ... thumbs up!</td>', 'Nice variation on the water theme ... plus having the drill bit ... thumbs up!', '2002-04-19 21:22:00.000000', NULL, 1),
(47911, 848, 113, '<td valign="top">Don''t know what it is, but you could have left out the lower half of this photo and had a winner.  Its beautiful and you did an excellent job of capturing.  Too bad about the bottom.</td>', 'Don''t know what it is, but you could have left out the lower half of this photo and had a winner.  Its beautiful and you did an excellent job of capturing.  Too bad about the bottom.', '2002-04-20 05:55:00.000000', NULL, 1),
(47912, 848, 1202, '<td valign="top">Boring can be interpreted more than one way.   Bad choice for name of picture.   An interesting shot but the observer needs to have knowledge of the machine word to appreciate it.  Good stopping of motion both in the coolant and the drill bit.   I don''t see any chips so the drill might not be actually turning so then it would just be a picture of stopped coolant.</td>', 'Boring can be interpreted more than one way.   Bad choice for name of picture.   An interesting shot but the observer needs to have knowledge of the machine word to appreciate it.  Good stopping of motion both in the coolant and the drill bit.   I don''t see any chips so the drill might not be actually turning so then it would just be a picture of stopped coolant.', '2002-04-20 10:37:00.000000', NULL, 1),
(47913, 848, 346, '<td valign="top">great catch of an explosion.</td>', 'great catch of an explosion.', '2002-04-20 22:39:00.000000', NULL, 1),
(47914, 848, 889, '<td valign="top">The best use of liquid Ive seen all day</td>', 'The best use of liquid Ive seen all day', '2002-04-21 17:49:00.000000', NULL, 1),
