(48132, 861, 881, '<td valign="top">I think more cards would have looked better.</td>', 'I think more cards would have looked better.', '2002-04-16 01:42:00.000000', NULL, 1),
(48133, 861, 245, '<td valign="top">how many times did you try to get the cards not to clump together? I do not envy you.</td>', 'how many times did you try to get the cards not to clump together? I do not envy you.', '2002-04-16 04:23:00.000000', NULL, 1),
(48134, 861, 1, '<td valign="top">The cards are way to clumped together for this photograph to have any effect.  A more scattered deck is definitely needed.</td>', 'The cards are way to clumped together for this photograph to have any effect.  A more scattered deck is definitely needed.', '2002-04-16 12:32:00.000000', NULL, 1),
(48135, 861, 813, '<td valign="top">like the white gloves, would love to see more cards or something</td>', 'like the white gloves, would love to see more cards or something', '2002-04-16 13:34:00.000000', NULL, 1),
(48136, 861, 1078, '<td valign="top">Being a magician, I would have REALLY loved this shot if the cards had been a bit less clumped up</td>', 'Being a magician, I would have REALLY loved this shot if the cards had been a bit less clumped up', '2002-04-16 16:44:00.000000', NULL, 1),
(48137, 861, 361, '<td valign="top">Sharp! I like the blacked out background and the added touch of the white gloves.</td>', 'Sharp! I like the blacked out background and the added touch of the white gloves.', '2002-04-16 18:21:00.000000', NULL, 1),
