(48140, 861, 472, '<td valign="top">the gloves are a nice touch. the different alternating directions of the cards are good.  too bad that the cards clumped together.</td>', 'the gloves are a nice touch. the different alternating directions of the cards are good.  too bad that the cards clumped together.', '2002-04-17 11:44:00.000000', NULL, 1),
(48141, 861, 798, '<td valign="top">Very nice!</td>', 'Very nice!', '2002-04-17 11:56:00.000000', NULL, 1),
