(48145, 861, 1061, '<td valign="top">good idea, but the cards should be more dispersed</td>', 'good idea, but the cards should be more dispersed', '2002-04-18 00:34:00.000000', NULL, 1),
(48146, 861, 2, '<td valign="top">Very cool idea and nicely executed :)  How did you set up the lighting for this shot?</td>', 'Very cool idea and nicely executed :)  How did you set up the lighting for this shot?', '2002-04-18 00:34:00.000000', NULL, 1),
(48147, 861, 205, '<td valign="top">The only thing that could have made this better is less reflection on the gloves and a better spread of the cards</td>', 'The only thing that could have made this better is less reflection on the gloves and a better spread of the cards', '2002-04-18 02:30:00.000000', NULL, 1),
