(48212, 865, 1055, '<td valign="top">Nice concept, but I wish the cat and its thing were more focused.  I can''t tell what it has ...</td>', 'Nice concept, but I wish the cat and its thing were more focused.  I can''t tell what it has ...', '2002-04-15 09:28:00.000000', NULL, 1),
(48213, 865, 641, '<td valign="top">Really cool angle and composition. But it looks a tad bit blurry.</td>', 'Really cool angle and composition. But it looks a tad bit blurry.', '2002-04-15 10:19:00.000000', NULL, 1),
(48214, 865, 205, '<td valign="top">the cat being in focus could have made this a ten<br/></td>', 'the cat being in focus could have made this a ten', '2002-04-15 10:21:00.000000', NULL, 1),
(48215, 865, 1041, '<td valign="top">Great idea and angle.  Shame that the cat is not more in focus.</td>', 'Great idea and angle.  Shame that the cat is not more in focus.', '2002-04-15 11:10:00.000000', NULL, 1),
(48216, 865, 656, '<td valign="top">Bit blurred/ out of focus.  Nice idea.</td>', 'Bit blurred/ out of focus.  Nice idea.', '2002-04-15 11:59:00.000000', NULL, 1),
(48217, 865, 361, '<td valign="top">I like the angle. The cat is a bit out-of-focus, but I know (from experience!) that it is near impossible to get proper focus on an animal in motion, so I''m not going to cut much on that.</td>', 'I like the angle. The cat is a bit out-of-focus, but I know (from experience!) that it is near impossible to get proper focus on an animal in motion, so I''m not going to cut much on that.', '2002-04-15 12:27:00.000000', NULL, 1),
(48218, 865, 189, '<td valign="top">Kind of out of focus.</td>', 'Kind of out of focus.', '2002-04-15 12:34:00.000000', NULL, 1),
(48219, 865, 139, '<td valign="top">I wanted to get a shot like this, but couldn''t.  Excellent timing and composition.    Manual focus could have improved this if you have that option.   Even without the best focus, it gets a 10 from me.</td>', 'I wanted to get a shot like this, but couldn''t.  Excellent timing and composition.    Manual focus could have improved this if you have that option.   Even without the best focus, it gets a 10 from me.', '2002-04-15 12:40:00.000000', NULL, 1),
