(48324, 868, 1, '<td valign="top">Nice job showing the contrast between the focus''d water and the out of focus''d tree.</td>', 'Nice job showing the contrast between the focus''d water and the out of focus''d tree.', '2002-04-20 09:27:00.000000', NULL, 1),
