(48327, 869, 656, '<td valign="top">I''d have moved in a lot closer, and just got the lamp rather than the whole stand.  Meets the challenge but isn''t very dynamic/ exciting.</td>', 'I''d have moved in a lot closer, and just got the lamp rather than the whole stand.  Meets the challenge but isn''t very dynamic/ exciting.', '2002-04-15 08:02:00.000000', NULL, 1),
(48328, 869, 92, '<td valign="top">Great capture ! The color and light are just so cool. My only change would be to crop off the bottom just a bit more. NICE !</td>', 'Great capture ! The color and light are just so cool. My only change would be to crop off the bottom just a bit more. NICE !', '2002-04-15 09:34:00.000000', NULL, 1),
(48329, 869, 641, '<td valign="top">Interesting colors in this.</td>', 'Interesting colors in this.', '2002-04-15 10:18:00.000000', NULL, 1),
(48330, 869, 139, '<td valign="top">Good.  Next time try to catch the horizontal.</td>', 'Good.  Next time try to catch the horizontal.', '2002-04-15 11:00:00.000000', NULL, 1),
(48331, 869, 772, '<td valign="top">This is a cool photograph but I''m not impressed with it''s application to the "stopped motion" challenge.  In my humble opinion, motion cannot be stopped with a long exposure and no flash.  The photo is also slanted downward to the right.  Leveling the subject would have improved the photo.</td>', 'This is a cool photograph but I''m not impressed with it''s application to the "stopped motion" challenge.  In my humble opinion, motion cannot be stopped with a long exposure and no flash.  The photo is also slanted downward to the right.  Leveling the subject would have improved the photo.', '2002-04-15 11:56:00.000000', NULL, 1),
(48332, 869, 724, '<td valign="top">This might of been better with the wax hotter, and more bubbles.</td>', 'This might of been better with the wax hotter, and more bubbles.', '2002-04-15 22:35:00.000000', NULL, 1),
(48333, 869, 2, '<td valign="top">Off-center -- could be fixed with cropping or better shot framing.</td>', 'Off-center -- could be fixed with cropping or better shot framing.', '2002-04-16 11:24:00.000000', NULL, 1),
(48334, 869, 1103, '<td valign="top">bad</td>', 'bad', '2002-04-16 12:55:00.000000', NULL, 1),
(48335, 869, 441, '<td valign="top">nice lighting given out by this subject.</td>', 'nice lighting given out by this subject.', '2002-04-16 14:27:00.000000', NULL, 1),
