(48337, 869, 301, '<td valign="top">nice colours, but the bottom is just too dark for me</td>', 'nice colours, but the bottom is just too dark for me', '2002-04-17 10:06:00.000000', NULL, 1),
(48338, 869, 472, '<td valign="top">i love lava lamps. although the idea of ''stopped motion'' seems a little wasted on such.  you kind of set your self up here because you had to take the pic in the dark, with a slow shutter.  so your lava is blurred and not really stopped, even tho it was moving slow int he first place!</td>', 'i love lava lamps. although the idea of ''stopped motion'' seems a little wasted on such.  you kind of set your self up here because you had to take the pic in the dark, with a slow shutter.  so your lava is blurred and not really stopped, even tho it was moving slow int he first place!', '2002-04-17 12:05:00.000000', NULL, 1),
(48339, 869, 811, '<td valign="top">Good use of color.  Something in the lower left is distracting.</td>', 'Good use of color.  Something in the lower left is distracting.', '2002-04-17 15:55:00.000000', NULL, 1),
(48340, 869, 749, '<td valign="top">The bottom third of the photo is a bit redundant...</td>', 'The bottom third of the photo is a bit redundant...', '2002-04-17 17:17:00.000000', NULL, 1),
