(48360, 872, 656, '<td valign="top">Shame the focus is on the far bank, rather than on the splash.   Good try.</td>', 'Shame the focus is on the far bank, rather than on the splash.   Good try.', '2002-04-15 08:18:00.000000', NULL, 1),
