(48365, 872, 138, '<td valign="top">water.. go figure</td>', 'water.. go figure', '2002-04-15 15:00:00.000000', NULL, 1),
(48366, 872, 308, '<td valign="top">The splash looks great, but I think that it could have used some cropping to take out the empty space on the right 2/3 of the photo.</td>', 'The splash looks great, but I think that it could have used some cropping to take out the empty space on the right 2/3 of the photo.', '2002-04-15 15:54:00.000000', NULL, 1),
(48367, 872, 142, '<td valign="top">Great photo.  I''m just curious to know what made the splash.</td>', 'Great photo.  I''m just curious to know what made the splash.', '2002-04-15 17:16:00.000000', NULL, 1),
(48368, 872, 554, '<td valign="top">Wasn''t my top three but a 10 never the less. Just look at the clear water! Nice background too.</td>', 'Wasn''t my top three but a 10 never the less. Just look at the clear water! Nice background too.', '2002-04-15 18:29:00.000000', NULL, 1),
(48369, 872, 813, '<td valign="top">Beautiful. Really gets my attention thanks mainly to the compositon and the action. Great job!</td>', 'Beautiful. Really gets my attention thanks mainly to the compositon and the action. Great job!', '2002-04-15 19:09:00.000000', NULL, 1),
(48370, 872, 536, '<td valign="top">cute. I see the face but my eyes keep fixing on that interesting landscape. The splash seems to get in the way of me moving with the ripples to shore. I do like this, but feel you didn''t trust "us" without making a splash. :)</td>', 'cute. I see the face but my eyes keep fixing on that interesting landscape. The splash seems to get in the way of me moving with the ripples to shore. I do like this, but feel you didn''t trust "us" without making a splash. :)', '2002-04-15 20:09:00.000000', NULL, 1),
(48371, 872, 301, '<td valign="top">good effort.  I don''t really like having that right hand side being so empty though</td>', 'good effort.  I don''t really like having that right hand side being so empty though', '2002-04-17 11:08:00.000000', NULL, 1),
(48372, 872, 472, '<td valign="top">i like the off-center composition.</td>', 'i like the off-center composition.', '2002-04-17 11:56:00.000000', NULL, 1),
(48373, 872, 798, '<td valign="top">Skipping stones?</td>', 'Skipping stones?', '2002-04-17 12:02:00.000000', NULL, 1),
(48374, 872, 441, '<td valign="top">great splash, good shot well captured</td>', 'great splash, good shot well captured', '2002-04-17 17:06:00.000000', NULL, 1),
(48375, 872, 749, '<td valign="top">The contrast of the splash on the left and the near-still water to the right is great - lovely timing too</td>', 'The contrast of the splash on the left and the near-still water to the right is great - lovely timing too', '2002-04-17 18:02:00.000000', NULL, 1),
(48376, 872, 2, '<td valign="top">Pretty exciting water -- not-so-exciting setting/composition.</td>', 'Pretty exciting water -- not-so-exciting setting/composition.', '2002-04-18 00:14:00.000000', NULL, 1),
