INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(48379, 872, 587, '<td valign="top">Looks like "Wilson" ;) Great imagination, where was this taken though - Mars? The background is bizzare.</td>', 'Looks like "Wilson" ;) Great imagination, where was this taken though - Mars? The background is bizzare.', '2002-04-18 08:00:00.000000', NULL, 1),
(48380, 872, 671, '<td valign="top">Nice splash.  Good focus.  I like the way the spalsh is off center.  Eastern washington? Or Texas? Or?</td>', 'Nice splash.  Good focus.  I like the way the spalsh is off center.  Eastern washington? Or Texas? Or?', '2002-04-18 11:14:00.000000', NULL, 1),
(48381, 872, 933, '<td valign="top">A nice stop-motion image.  Technically sound.  well, maybe a little bit out of focus.</td>', 'A nice stop-motion image.  Technically sound.  well, maybe a little bit out of focus.', '2002-04-18 14:28:00.000000', NULL, 1),
(48382, 872, 1164, '<td valign="top">great timing</td>', 'great timing', '2002-04-18 16:15:00.000000', NULL, 1),
(48383, 872, 811, '<td valign="top">Good "stoppage."  Not quite enough action on the right side of the picture.  Crop it, maybe?</td>', 'Good "stoppage."  Not quite enough action on the right side of the picture.  Crop it, maybe?', '2002-04-18 19:07:00.000000', NULL, 1),
(48384, 872, 245, '<td valign="top">the holes ripping in the sheet of water look pretty cool but I wish the camera were tilted upwards a bit so capture more of the background.</td>', 'the holes ripping in the sheet of water look pretty cool but I wish the camera were tilted upwards a bit so capture more of the background.', '2002-04-19 02:51:00.000000', NULL, 1),
(48385, 872, 797, '<td valign="top">powerful splash. and nice rocky background. perhaps a little more towards the center would''ve been nice.</td>', 'powerful splash. and nice rocky background. perhaps a little more towards the center would''ve been nice.', '2002-04-19 04:00:00.000000', NULL, 1),
(48386, 872, 1041, '<td valign="top">Great idea, and picture taken at just the right moment.  Would''ve been nice if the whole splash was visible at the left and top.</td>', 'Great idea, and picture taken at just the right moment.  Would''ve been nice if the whole splash was visible at the left and top.', '2002-04-19 08:26:00.000000', NULL, 1),
(48387, 872, 1175, '<td valign="top">Cool picture, but if this picture was removed from this site, it wouldn''t be easy to tell what your subject is.</td>', 'Cool picture, but if this picture was removed from this site, it wouldn''t be easy to tell what your subject is.', '2002-04-19 09:44:00.000000', NULL, 1),
(48388, 872, 361, '<td valign="top">Another cool river-splash photo. That high splash of water is awesome!</td>', 'Another cool river-splash photo. That high splash of water is awesome!', '2002-04-19 16:14:00.000000', NULL, 1),
(48389, 872, 801, '<td valign="top">Good idea! I like it</td>', 'Good idea! I like it', '2002-04-20 06:02:00.000000', NULL, 1),
(48390, 872, 113, '<td valign="top">This is awesome.  You have a great eye.  I like your background,  the way you off centered your splash looks great.  It''s a little blurry, but I still count it high.</td>', 'This is awesome.  You have a great eye.  I like your background,  the way you off centered your splash looks great.  It''s a little blurry, but I still count it high.', '2002-04-20 06:11:00.000000', NULL, 1),
(48391, 872, 1, '<td valign="top">Nice catch w/ the face and all.  I think centering the splash would''ve been better.</td>', 'Nice catch w/ the face and all.  I think centering the splash would''ve been better.', '2002-04-20 09:50:00.000000', NULL, 1),
(48392, 872, 1202, '<td valign="top">I like this shot.   It has a story line of its own.   The background tells me it ia hotter than hell, and the answer to that is in the great splash.</td>', 'I like this shot.   It has a story line of its own.   The background tells me it ia hotter than hell, and the answer to that is in the great splash.', '2002-04-20 10:53:00.000000', NULL, 1),
(48393, 872, 637, '<td valign="top">a fortunate splash, eh?</td>', 'a fortunate splash, eh?', '2002-04-20 13:19:00.000000', NULL, 1),
(48394, 872, 806, '<td valign="top">good job. background is a bit distracting though.</td>', 'good job. background is a bit distracting though.', '2002-04-21 17:57:00.000000', NULL, 1),
(48395, 872, 554, '<td valign="top">I think this is in good focus. Just look at the foreground AND the background. Both in focus. How anyone could give below a five is beyond me.  Perfect framing is subjective.</td>', 'I think this is in good focus. Just look at the foreground AND the background. Both in focus. How anyone could give below a five is beyond me.  Perfect framing is subjective.', '2002-04-22 20:19:00.000000', NULL, 0),
(48396, 873, 509, '<td valign="top">Great sunset</td>', 'Great sunset', '2002-04-15 10:28:00.000000', NULL, 1),
(48397, 873, 656, '<td valign="top">I think a less central framing woul dhave been stronger, perhaps with the person more the the right ?  Nice silhouette though.</td>', 'I think a less central framing woul dhave been stronger, perhaps with the person more the the right ?  Nice silhouette though.', '2002-04-15 10:44:00.000000', NULL, 1),
(48398, 873, 139, '<td valign="top">Nice photo</td>', 'Nice photo', '2002-04-15 11:10:00.000000', NULL, 1),
(48399, 873, 675, '<td valign="top">those colors are great, but the stop action isn''t</td>', 'those colors are great, but the stop action isn''t', '2002-04-15 13:39:00.000000', NULL, 1),
(48400, 873, 203, '<td valign="top">I am not certain butm it sure looks like the arm has a motion blurr.  Nice shot but it does not work in this challenge for me.  At least it is more original than endless falling people, pets and drops of water (one of which will win this cliche ridden contest).</td>', 'I am not certain butm it sure looks like the arm has a motion blurr.  Nice shot but it does not work in this challenge for me.  At least it is more original than endless falling people, pets and drops of water (one of which will win this cliche ridden contest).', '2002-04-15 14:07:00.000000', NULL, 1),
(48401, 873, 718, '<td valign="top">I see a motion trail on the hand.</td>', 'I see a motion trail on the hand.', '2002-04-15 14:23:00.000000', NULL, 1),
(48402, 873, 361, '<td valign="top">Pretty background. I think the stopped-motion subject is too small in this picture. Maybe crop a bunch (if possible)to bring the subject closer. Actually, given the lighting, it looks like it might be very difficult to get a fast enough shutter to truely stop the motion, but I could be wrong.</td>', 'Pretty background. I think the stopped-motion subject is too small in this picture. Maybe crop a bunch (if possible)to bring the subject closer. Actually, given the lighting, it looks like it might be very difficult to get a fast enough shutter to truely stop the motion, but I could be wrong.', '2002-04-15 15:19:00.000000', NULL, 1),
(48403, 873, 554, '<td valign="top">Beautiful picture but I miss the stopaction. framed well though.</td>', 'Beautiful picture but I miss the stopaction. framed well though.', '2002-04-15 15:42:00.000000', NULL, 1),
(48404, 873, 661, '<td valign="top">Pretty sky.</td>', 'Pretty sky.', '2002-04-15 19:26:00.000000', NULL, 1),
(48405, 873, 772, '<td valign="top">I would vote high on this shot for a sunset challenge but it isn''t making the cut for a stopped motion challenge.  The ony moving item in the photo is the human and there is motion blur on his hand...</td>', 'I would vote high on this shot for a sunset challenge but it isn''t making the cut for a stopped motion challenge.  The ony moving item in the photo is the human and there is motion blur on his hand...', '2002-04-15 19:31:00.000000', NULL, 1),
(48406, 873, 1085, '<td valign="top">simply beautiful... i love the horizon and and and that guy....see that guy? yeah, the one walking there. splendid...just marvelous...<br/>seriously though, it''s a good picture.</td>', 'simply beautiful... i love the horizon and and and that guy....see that guy? yeah, the one walking there. splendid...just marvelous...seriously though, it''s a good picture.', '2002-04-15 20:42:00.000000', NULL, 1),
(48407, 873, 724, '<td valign="top">Beautiful Sunset, some blur on your subject.</td>', 'Beautiful Sunset, some blur on your subject.', '2002-04-15 22:54:00.000000', NULL, 1),
(48408, 873, 640, '<td valign="top">I love the sky, and its a great sillohette.</td>', 'I love the sky, and its a great sillohette.', '2002-04-16 01:08:00.000000', NULL, 1),
(48409, 873, 245, '<td valign="top">Although you''ve stopped some motion, this doesn''t scream ''stopped motion'' to me when i look at it.</td>', 'Although you''ve stopped some motion, this doesn''t scream ''stopped motion'' to me when i look at it.', '2002-04-16 04:46:00.000000', NULL, 1),
