(48581, 879, 671, '<td valign="top">nice stopped motion--you can make out the curl of his fin!  Great colors.</td>', 'nice stopped motion--you can make out the curl of his fin!  Great colors.', '2002-04-17 10:44:00.000000', NULL, 1),
(48582, 879, 811, '<td valign="top">Nice pic.  I really like bright colors against a black background.</td>', 'Nice pic.  I really like bright colors against a black background.', '2002-04-17 16:29:00.000000', NULL, 1),
(48583, 879, 749, '<td valign="top">Great colour, but I''m left wondering what the thing on the right is.</td>', 'Great colour, but I''m left wondering what the thing on the right is.', '2002-04-17 17:16:00.000000', NULL, 1),
