(48723, 884, 139, '<td valign="top">Congratulations on the win.</td>', 'Congratulations on the win.', '2002-04-15 10:59:00.000000', NULL, 1),
(48724, 884, 772, '<td valign="top">Billy Joe Bob is too close to the top of the frame but he is a talented acrobat.  I think a little added focus and sharpness would contribute to this overall quality of this photograph.</td>', 'Billy Joe Bob is too close to the top of the frame but he is a talented acrobat.  I think a little added focus and sharpness would contribute to this overall quality of this photograph.', '2002-04-15 15:06:00.000000', NULL, 1),
(48725, 884, 441, '<td valign="top">nice try - did he land ok?</td>', 'nice try - did he land ok?', '2002-04-15 16:22:00.000000', NULL, 1),
(48726, 884, 1085, '<td valign="top">great picture! very entertaining, more so than a penthouse movie and a handful of paper tissues, and i also like the "decisive moment" which this picture shows beautifully.... i''m sure good old Bresson would have loved this......if he hadn''t been dead, that is.....</td>', 'great picture! very entertaining, more so than a penthouse movie and a handful of paper tissues, and i also like the "decisive moment" which this picture shows beautifully.... i''m sure good old Bresson would have loved this......if he hadn''t been dead, that is.....', '2002-04-15 20:38:00.000000', NULL, 1),
(48727, 884, 813, '<td valign="top">would be much better if it were lighter. how about a flash next time.</td>', 'would be much better if it were lighter. how about a flash next time.', '2002-04-16 12:38:00.000000', NULL, 1),
(48728, 884, 910, '<td valign="top">too dark, but original</td>', 'too dark, but original', '2002-04-16 21:51:00.000000', NULL, 1),
