(48730, 884, 811, '<td valign="top">It''s blurry to me, and he has just about jumped out of the top of the picture.</td>', 'It''s blurry to me, and he has just about jumped out of the top of the picture.', '2002-04-17 15:37:00.000000', NULL, 1),
(48731, 884, 361, '<td valign="top">Too dark... need to see the legs, too. Otherwise, a good idea.</td>', 'Too dark... need to see the legs, too. Otherwise, a good idea.', '2002-04-17 15:42:00.000000', NULL, 1),
(48732, 884, 749, '<td valign="top">One word: lighting!</td>', 'One word: lighting!', '2002-04-17 17:32:00.000000', NULL, 1),
(48733, 884, 472, '<td valign="top">fairly typical. too dark.</td>', 'fairly typical. too dark.', '2002-04-17 17:50:00.000000', NULL, 1),
(48734, 884, 205, '<td valign="top">Why inside? And won what?</td>', 'Why inside? And won what?', '2002-04-18 02:55:00.000000', NULL, 1),
