(48736, 884, 245, '<td valign="top">the lighting needs a lot of work, and the camera seems slightly tilted to the right</td>', 'the lighting needs a lot of work, and the camera seems slightly tilted to the right', '2002-04-18 13:55:00.000000', NULL, 1),
(48737, 884, 933, '<td valign="top">Too dark, especially at the base of the image.</td>', 'Too dark, especially at the base of the image.', '2002-04-18 14:33:00.000000', NULL, 1),
(48738, 884, 714, '<td valign="top">I think your photo is to dark.  He is also out of focus.  I know he is jumping, but I can not see it.  I feel you could have done a better job if you put some effort into it.</td>', 'I think your photo is to dark.  He is also out of focus.  I know he is jumping, but I can not see it.  I feel you could have done a better job if you put some effort into it.', '2002-04-18 19:16:00.000000', NULL, 1),
