(48772, 886, 472, '<td valign="top">i like this image. dont get food on your camera. : )</td>', 'i like this image. dont get food on your camera. : )', '2002-04-18 08:49:00.000000', NULL, 1),
(48773, 886, 640, '<td valign="top">Looks like an interesting subject matter, but I cant'' quite catch what the action is!</td>', 'Looks like an interesting subject matter, but I cant'' quite catch what the action is!', '2002-04-18 08:53:00.000000', NULL, 1),
(48774, 886, 811, '<td valign="top">Good subject, makes me want to go to a Japanese Steakhouse near where I live.  :-)  A little dark, and though the motion is obviously a focal point, it is blurry, and detracts from the overall effectiveness.</td>', 'Good subject, makes me want to go to a Japanese Steakhouse near where I live.  :-)  A little dark, and though the motion is obviously a focal point, it is blurry, and detracts from the overall effectiveness.', '2002-04-18 19:10:00.000000', NULL, 1),
