(48776, 886, 862, '<td valign="top">Need more light on the subject.</td>', 'Need more light on the subject.', '2002-04-19 08:07:00.000000', NULL, 1),
(48777, 886, 1175, '<td valign="top">This could have been a great picture.  I like the face on the right looking on in amazement.  The chef working like nothing.  But the subject is blurred and not really stopped.</td>', 'This could have been a great picture.  I like the face on the right looking on in amazement.  The chef working like nothing.  But the subject is blurred and not really stopped.', '2002-04-19 14:44:00.000000', NULL, 1),
