(48779, 886, 113, '<td valign="top">I think I would have come in closer on his hands and left his head out.  Onion is blurred.</td>', 'I think I would have come in closer on his hands and left his head out.  Onion is blurred.', '2002-04-20 05:05:00.000000', NULL, 1),
(48780, 886, 1202, '<td valign="top">Not bad for poor lighting conditions.   Nearly stopped subject with distracting foreground.</td>', 'Not bad for poor lighting conditions.   Nearly stopped subject with distracting foreground.', '2002-04-20 09:52:00.000000', NULL, 1),
(48781, 886, 1, '<td valign="top">Capturing the breaking of the egg would''ve been more dramatic.</td>', 'Capturing the breaking of the egg would''ve been more dramatic.', '2002-04-20 10:03:00.000000', NULL, 1),
(48782, 886, 637, '<td valign="top">oops..... trails</td>', 'oops..... trails', '2002-04-20 13:27:00.000000', NULL, 1),
(48783, 886, 933, '<td valign="top">Kind of dark and out of focus.</td>', 'Kind of dark and out of focus.', '2002-04-21 02:53:00.000000', NULL, 1),
