(48961, 890, 142, '<td valign="top">I like the way you incorporated a piece of your culture in your entry.</td>', 'I like the way you incorporated a piece of your culture in your entry.', '2002-04-19 22:00:00.000000', NULL, 1),
(48962, 890, 113, '<td valign="top">I have to grant you most original in this challenge.  The photo as a whole though is blurred.  I might have just shot the woman and left out all of the other stuff.</td>', 'I have to grant you most original in this challenge.  The photo as a whole though is blurred.  I might have just shot the woman and left out all of the other stuff.', '2002-04-20 04:35:00.000000', NULL, 1),
