(48966, 890, 806, '<td valign="top">out of focus</td>', 'out of focus', '2002-04-21 18:48:00.000000', NULL, 1),
(48967, 893, 107, '<td valign="top">lovely use of colour.</td>', 'lovely use of colour.', '2002-04-15 06:33:00.000000', NULL, 1),
(48968, 893, 641, '<td valign="top">I love the color and and the contrast of the black and blue.</td>', 'I love the color and and the contrast of the black and blue.', '2002-04-15 10:03:00.000000', NULL, 1),
(48969, 893, 813, '<td valign="top">Good idea. This would be beautiful if you cropped the image in a tight vertical off center to the right. The emphasis would then visually be placed on the candle and the flame.</td>', 'Good idea. This would be beautiful if you cropped the image in a tight vertical off center to the right. The emphasis would then visually be placed on the candle and the flame.', '2002-04-15 10:35:00.000000', NULL, 1),
(48970, 893, 656, '<td valign="top">A fresher candle might have been less dirty and given an overall cleaner picture ?   Framing is a bit too loose, could do with being closer.</td>', 'A fresher candle might have been less dirty and given an overall cleaner picture ?   Framing is a bit too loose, could do with being closer.', '2002-04-15 10:40:00.000000', NULL, 1),
(48971, 893, 772, '<td valign="top">I saw this same phenomenon in the popcorn photo in this challenge.  Your candle flame is absorbing the blue light from the rest of the image.  I''m not sure that a candle flame is the best choice of subjects for a ''stopped motion'' challenge.  The composition of this photograph is nice.  I''m not impressed with its association with ''stopped motion''.</td>', 'I saw this same phenomenon in the popcorn photo in this challenge.  Your candle flame is absorbing the blue light from the rest of the image.  I''m not sure that a candle flame is the best choice of subjects for a ''stopped motion'' challenge.  The composition of this photograph is nice.  I''m not impressed with its association with ''stopped motion''.', '2002-04-15 12:16:00.000000', NULL, 1),
(48972, 893, 138, '<td valign="top">i have the same candle :)</td>', 'i have the same candle :)', '2002-04-15 15:01:00.000000', NULL, 1),
(48973, 893, 441, '<td valign="top">original interesting subject but maybe a little small and insignificant</td>', 'original interesting subject but maybe a little small and insignificant', '2002-04-15 17:06:00.000000', NULL, 1),
(48974, 893, 131, '<td valign="top">that''s stop action allright.</td>', 'that''s stop action allright.', '2002-04-15 19:42:00.000000', NULL, 1),
(48975, 893, 2, '<td valign="top">A blue flame?  What kind of candle has a blue flame?  Hue alterations are not allowed by challenge rules.</td>', 'A blue flame?  What kind of candle has a blue flame?  Hue alterations are not allowed by challenge rules.', '2002-04-16 11:33:00.000000', NULL, 1),
(48976, 893, 749, '<td valign="top">Nice composition - I''m curious as to how you got the flame as solid white, yet the wax turquoise.</td>', 'Nice composition - I''m curious as to how you got the flame as solid white, yet the wax turquoise.', '2002-04-17 17:47:00.000000', NULL, 1),
(48977, 893, 472, '<td valign="top">pretty candle. nice white balance. hard to really get the impression of motion from this one.</td>', 'pretty candle. nice white balance. hard to really get the impression of motion from this one.', '2002-04-17 17:52:00.000000', NULL, 1),
(48978, 893, 1061, '<td valign="top">color would be better</td>', 'color would be better', '2002-04-18 00:36:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(48979, 893, 587, '<td valign="top">I am being drawn to the top, flameless portion of your candle - good pic of flame though.</td>', 'I am being drawn to the top, flameless portion of your candle - good pic of flame though.', '2002-04-18 07:25:00.000000', NULL, 1),
(48980, 893, 862, '<td valign="top">This is not really what I would call a stop action shot.</td>', 'This is not really what I would call a stop action shot.', '2002-04-18 08:30:00.000000', NULL, 1),
(48981, 893, 543, '<td valign="top">Subtle.  Soot on the candle detracts, and the composition isn''t the most interesting, but nice.</td>', 'Subtle.  Soot on the candle detracts, and the composition isn''t the most interesting, but nice.', '2002-04-18 10:05:00.000000', NULL, 1),
(48982, 893, 245, '<td valign="top">the cool greenish cast to this conflicts with the warm flame, sepia might have been a better choice.</td>', 'the cool greenish cast to this conflicts with the warm flame, sepia might have been a better choice.', '2002-04-18 14:02:00.000000', NULL, 1),
(48983, 893, 205, '<td valign="top">There is something confusing about this picture it almost looks like you blue toned the whole thing.</td>', 'There is something confusing about this picture it almost looks like you blue toned the whole thing.', '2002-04-18 14:33:00.000000', NULL, 1),
(48984, 893, 811, '<td valign="top">I like the black background.  A clean candle would have made a nicer contrast, I think.</td>', 'I like the black background.  A clean candle would have made a nicer contrast, I think.', '2002-04-18 19:08:00.000000', NULL, 1),
(48985, 893, 739, '<td valign="top">The title allowed me to interpret motion into this picture, though I cannot infer that from just the picture.</td>', 'The title allowed me to interpret motion into this picture, though I cannot infer that from just the picture.', '2002-04-19 01:17:00.000000', NULL, 1),
(48986, 893, 361, '<td valign="top">Nice, sharp picture.</td>', 'Nice, sharp picture.', '2002-04-19 14:08:00.000000', NULL, 1),
(48987, 893, 1175, '<td valign="top">Doesn''t imply enough motion.</td>', 'Doesn''t imply enough motion.', '2002-04-19 15:26:00.000000', NULL, 1),
(48988, 893, 142, '<td valign="top">The lighting makes this an interesting photo.</td>', 'The lighting makes this an interesting photo.', '2002-04-19 22:03:00.000000', NULL, 1),
(48989, 893, 113, '<td valign="top">wellllll,</td>', 'wellllll,', '2002-04-20 06:23:00.000000', NULL, 1),
(48990, 893, 1202, '<td valign="top">Nope.   Keep shooting</td>', 'Nope.   Keep shooting', '2002-04-20 11:26:00.000000', NULL, 1),
(48991, 893, 346, '<td valign="top">The shot would could have been stronger, if the candle was shot more off center, or maybe as a macro shot.</td>', 'The shot would could have been stronger, if the candle was shot more off center, or maybe as a macro shot.', '2002-04-20 22:40:00.000000', NULL, 1),
(48992, 893, 933, '<td valign="top">Hmmm.  I think I like this more after seeng it a few times.  Seems a tad out of focus, but otherwise nice.  Good colors.</td>', 'Hmmm.  I think I like this more after seeng it a few times.  Seems a tad out of focus, but otherwise nice.  Good colors.', '2002-04-21 02:44:00.000000', NULL, 1),
(48993, 893, 1, '<td valign="top">Since the flame is enclosed in glass, I can''t see how this is a "candle in the wind".  Also I''m wondering how you got the flame to be the same color as the candle.</td>', 'Since the flame is enclosed in glass, I can''t see how this is a "candle in the wind".  Also I''m wondering how you got the flame to be the same color as the candle.', '2002-04-21 12:10:00.000000', NULL, 1),
(48994, 894, 509, '<td valign="top">I really like the color of the water in the pool, if you had been able to get a shot from a higher ground so you could isolate the fountain and the pool (eliminate the building) this would be awesome.</td>', 'I really like the color of the water in the pool, if you had been able to get a shot from a higher ground so you could isolate the fountain and the pool (eliminate the building) this would be awesome.', '2002-04-15 10:27:00.000000', NULL, 1),
(48995, 894, 139, '<td valign="top">Pretty good</td>', 'Pretty good', '2002-04-15 11:07:00.000000', NULL, 1),
(48996, 894, 92, '<td valign="top">This is a nice subject but a closer shot that would get cutout the hose in the water and the building ect would be nicer:)</td>', 'This is a nice subject but a closer shot that would get cutout the hose in the water and the building ect would be nicer:)', '2002-04-15 11:30:00.000000', NULL, 1),
(48997, 894, 656, '<td valign="top">Meets the challenge but not very exciting - the background could have been simpler to make this stronger ?</td>', 'Meets the challenge but not very exciting - the background could have been simpler to make this stronger ?', '2002-04-15 11:45:00.000000', NULL, 1),
(48998, 894, 772, '<td valign="top">This is a nice fountain.  I can also see the stopped motion here.  I''m trying to find something that ''moves'' me in this photograph.  Technically, there is very little wrong with it.  Visually, I''m struggling with it.  I can''t really offer you any suggestions on how to improve this photo.  The surrounding environment may be distracting me from the subject.  Maybe I can''t see enough detail of the stopped motion.  The detail is lost in the distance.  Keep up the good efforts!</td>', 'This is a nice fountain.  I can also see the stopped motion here.  I''m trying to find something that ''moves'' me in this photograph.  Technically, there is very little wrong with it.  Visually, I''m struggling with it.  I can''t really offer you any suggestions on how to improve this photo.  The surrounding environment may be distracting me from the subject.  Maybe I can''t see enough detail of the stopped motion.  The detail is lost in the distance.  Keep up the good efforts!', '2002-04-15 12:08:00.000000', NULL, 1),
(48999, 894, 189, '<td valign="top">Water, Water Everywhere !</td>', 'Water, Water Everywhere !', '2002-04-15 12:42:00.000000', NULL, 1),
(49000, 894, 641, '<td valign="top">Pretty blue water,  good colors.</td>', 'Pretty blue water,  good colors.', '2002-04-15 12:57:00.000000', NULL, 1),
(49001, 894, 138, '<td valign="top">water.. go figure</td>', 'water.. go figure', '2002-04-15 15:02:00.000000', NULL, 1),
(49002, 894, 748, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2002-04-15 15:14:00.000000', NULL, 1),
(49003, 894, 1031, '<td valign="top">Why does some part os the fountain always end up against a cloudy sky? I think next time I try I''ll use one of those indoor ones they have at the big hardware stores, maybe with a curtain behind it...</td>', 'Why does some part os the fountain always end up against a cloudy sky? I think next time I try I''ll use one of those indoor ones they have at the big hardware stores, maybe with a curtain behind it...', '2002-04-15 21:21:00.000000', NULL, 1),
(49004, 894, 245, '<td valign="top">just as the fountain reaches it''s apex it hits the sky and you lose what could be a powerful focus of interest in bland clouds.</td>', 'just as the fountain reaches it''s apex it hits the sky and you lose what could be a powerful focus of interest in bland clouds.', '2002-04-16 04:18:00.000000', NULL, 1),
(49005, 894, 142, '<td valign="top">You captured the movement very well.  I think a closer shot and some cropping of the background would make this an outstanding photo.  Good job.</td>', 'You captured the movement very well.  I think a closer shot and some cropping of the background would make this an outstanding photo.  Good job.', '2002-04-16 13:47:00.000000', NULL, 1),
(49006, 894, 813, '<td valign="top">good color in the pool, needs better isolation of subject</td>', 'good color in the pool, needs better isolation of subject', '2002-04-16 14:54:00.000000', NULL, 1),
(49007, 894, 441, '<td valign="top">good original shot well captured - could u have taken this at night with flash to one or both sides to make subject more prominent and getting rid of unhelpfull backdrop and unwanted bits like the hose in the pool?</td>', 'good original shot well captured - could u have taken this at night with flash to one or both sides to make subject more prominent and getting rid of unhelpfull backdrop and unwanted bits like the hose in the pool?', '2002-04-17 03:18:00.000000', NULL, 1),
(49008, 894, 1061, '<td valign="top">another angle would get rid of the hose?</td>', 'another angle would get rid of the hose?', '2002-04-18 00:23:00.000000', NULL, 1),
(49009, 894, 205, '<td valign="top">The background is kind of bland.</td>', 'The background is kind of bland.', '2002-04-18 02:27:00.000000', NULL, 1),
(49010, 894, 472, '<td valign="top">sure did stop it!  i recommend a couple things:  get closer to the fountain (zoom or physically).  expose a little bit more than your meter wants to to brighten up the water, or use a fillflash, OR shoot it with the sun behind you.</td>', 'sure did stop it!  i recommend a couple things:  get closer to the fountain (zoom or physically).  expose a little bit more than your meter wants to to brighten up the water, or use a fillflash, OR shoot it with the sun behind you.', '2002-04-18 08:48:00.000000', NULL, 1),
(49011, 894, 301, '<td valign="top">not the most interesting subject or background.  Maybe try using DOF</td>', 'not the most interesting subject or background.  Maybe try using DOF', '2002-04-18 10:20:00.000000', NULL, 1),
(49012, 894, 933, '<td valign="top">Nice colors, but the composition could use a little spicing up!</td>', 'Nice colors, but the composition could use a little spicing up!', '2002-04-18 14:09:00.000000', NULL, 1),
