(49108, 899, 189, '<td valign="top">Best JUMP shot so far......eerr</td>', 'Best JUMP shot so far......eerr', '2002-04-15 12:46:00.000000', NULL, 1),
(49109, 899, 641, '<td valign="top">Cool capture, I like it better with the trampoline cropped out.</td>', 'Cool capture, I like it better with the trampoline cropped out.', '2002-04-15 12:55:00.000000', NULL, 1),
(49110, 899, 279, '<td valign="top">Too dark! Man, though, it''s a great angle.</td>', 'Too dark! Man, though, it''s a great angle.', '2002-04-15 13:13:00.000000', NULL, 1),
(49111, 899, 1031, '<td valign="top">On my monitor the figure seems to be oversharpened, but otherwise I like the composition and title.</td>', 'On my monitor the figure seems to be oversharpened, but otherwise I like the composition and title.', '2002-04-15 14:17:00.000000', NULL, 1),
(49112, 899, 661, '<td valign="top">Looks like fun.  To bad it''s so dark.</td>', 'Looks like fun.  To bad it''s so dark.', '2002-04-15 15:17:00.000000', NULL, 1),
(49113, 899, 885, '<td valign="top">a little too dark. i think it might have been neat with the trampoline at the bottom cropped out, so he''d just be floating.</td>', 'a little too dark. i think it might have been neat with the trampoline at the bottom cropped out, so he''d just be floating.', '2002-04-15 15:23:00.000000', NULL, 1),
(49114, 899, 813, '<td valign="top">Good shot. Would it be improved with levels adjustment. for better contrast?</td>', 'Good shot. Would it be improved with levels adjustment. for better contrast?', '2002-04-15 19:27:00.000000', NULL, 1),
(49115, 899, 446, '<td valign="top">Looks like a fun shot.  Wish the exposure would have been brighter to bring out more detail.</td>', 'Looks like a fun shot.  Wish the exposure would have been brighter to bring out more detail.', '2002-04-15 19:31:00.000000', NULL, 1),
(49116, 899, 772, '<td valign="top">This is a good stopped motion photo.  I would rather see from the other side.  I don''t like photos of people from behind.  The contrast needs a little assistance too.  The detail of the moving subject is very dark.</td>', 'This is a good stopped motion photo.  I would rather see from the other side.  I don''t like photos of people from behind.  The contrast needs a little assistance too.  The detail of the moving subject is very dark.', '2002-04-15 19:33:00.000000', NULL, 1),
(49117, 899, 748, '<td valign="top">I hope he landed on his feet!</td>', 'I hope he landed on his feet!', '2002-04-16 10:44:00.000000', NULL, 1),
(49118, 899, 361, '<td valign="top">Good stopped motion. Photo too dark.</td>', 'Good stopped motion. Photo too dark.', '2002-04-16 14:23:00.000000', NULL, 1),
(49119, 899, 441, '<td valign="top">well captured, stopped and focussed.</td>', 'well captured, stopped and focussed.', '2002-04-16 16:13:00.000000', NULL, 1),
(49120, 899, 1024, '<td valign="top">This would be a great picture as opposed to just a good one if it was not so dark and more detail was visible.</td>', 'This would be a great picture as opposed to just a good one if it was not so dark and more detail was visible.', '2002-04-16 16:37:00.000000', NULL, 1),
(49121, 899, 301, '<td valign="top">an interesting view on life ... oh there''s something coming out of the guys rear end!!!</td>', 'an interesting view on life ... oh there''s something coming out of the guys rear end!!!', '2002-04-17 10:13:00.000000', NULL, 1),
(49122, 899, 671, '<td valign="top">The curled toe is my favorite part.</td>', 'The curled toe is my favorite part.', '2002-04-17 10:56:00.000000', NULL, 1),
(49123, 899, 472, '<td valign="top">good shot!  it is a bit dark though. i would have preferred to blow out the sky a bit more so we could see the jumper better.</td>', 'good shot!  it is a bit dark though. i would have preferred to blow out the sky a bit more so we could see the jumper better.', '2002-04-17 12:02:00.000000', NULL, 1),
(49124, 899, 749, '<td valign="top">Very impressive timing, but what exactly is going on?</td>', 'Very impressive timing, but what exactly is going on?', '2002-04-17 18:21:00.000000', NULL, 1),
(49125, 899, 205, '<td valign="top">Too dark, but nice how you got him inverted</td>', 'Too dark, but nice how you got him inverted', '2002-04-18 02:34:00.000000', NULL, 1),
(49126, 899, 587, '<td valign="top">''flipping out'' or ''ripping out'' what''s wrong with his pants? Interesting background, just not for this pic.</td>', '''flipping out'' or ''ripping out'' what''s wrong with his pants? Interesting background, just not for this pic.', '2002-04-18 07:54:00.000000', NULL, 1),
(49127, 899, 142, '<td valign="top">Good photo.  Now if you could just bring in those beautiful mountains a little closer....</td>', 'Good photo.  Now if you could just bring in those beautiful mountains a little closer....', '2002-04-18 11:27:00.000000', NULL, 1),
(49128, 899, 933, '<td valign="top">Too dark.  This would have been much better if the levels and/or brightness had been adjusted a bit.</td>', 'Too dark.  This would have been much better if the levels and/or brightness had been adjusted a bit.', '2002-04-18 11:37:00.000000', NULL, 1),
(49129, 899, 245, '<td valign="top">like a ninja? they''re always flipping out, you know.</td>', 'like a ninja? they''re always flipping out, you know.', '2002-04-19 02:33:00.000000', NULL, 1),
(49130, 899, 797, '<td valign="top">that must''ve really tough to execute! kudos! only a little dim overall.</td>', 'that must''ve really tough to execute! kudos! only a little dim overall.', '2002-04-19 03:59:00.000000', NULL, 1),
(49131, 899, 1175, '<td valign="top">bad lighting</td>', 'bad lighting', '2002-04-19 08:50:00.000000', NULL, 1),
(49132, 899, 2, '<td valign="top">Really cool catching him in this position!  My suggestion would be trying this shot at different times of day to get better lighting and more exciting color.</td>', 'Really cool catching him in this position!  My suggestion would be trying this shot at different times of day to get better lighting and more exciting color.', '2002-04-19 10:13:00.000000', NULL, 1),
(49133, 899, 811, '<td valign="top">Wish I could see his face.</td>', 'Wish I could see his face.', '2002-04-19 10:21:00.000000', NULL, 1),
(49134, 899, 1184, '<td valign="top">Creates the illusion of cliff jumping. Exellent!</td>', 'Creates the illusion of cliff jumping. Exellent!', '2002-04-19 13:10:00.000000', NULL, 1),
(49135, 899, 113, '<td valign="top">I really like this photo.  It would make a good commercial or ad.  Good clarity of your subject, nice background, works well together.</td>', 'I really like this photo.  It would make a good commercial or ad.  Good clarity of your subject, nice background, works well together.', '2002-04-20 05:20:00.000000', NULL, 1),
(49136, 899, 1202, '<td valign="top">You got the stopping down, now you can work on composition.  My question is did the boy ruin your landscape or did the landscape ruin the boy.   Think about it and come back with a killer picture next time.</td>', 'You got the stopping down, now you can work on composition.  My question is did the boy ruin your landscape or did the landscape ruin the boy.   Think about it and come back with a killer picture next time.', '2002-04-20 11:31:00.000000', NULL, 1),
(49137, 899, 1, '<td valign="top">Nice catch.</td>', 'Nice catch.', '2002-04-21 11:42:00.000000', NULL, 1),
(49138, 899, 806, '<td valign="top">a little out of focus, and/or a bit dark.... but funny!</td>', 'a little out of focus, and/or a bit dark.... but funny!', '2002-04-21 18:14:00.000000', NULL, 1),
(49139, 899, 790, '<td valign="top">don''t try this at home!</td>', 'don''t try this at home!', '2002-04-21 20:50:00.000000', NULL, 1),
(49140, 900, 156, '<td valign="top">what a happy picture!</td>', 'what a happy picture!', '2002-04-15 08:40:00.000000', NULL, 1),
(49141, 900, 92, '<td valign="top">GREAT capture ! The beautiful colors really add to this. The only thing I would think could have made it a bit better is to be down lower or crop out the top a bit, but that might take part of his tail:( .</td>', 'GREAT capture ! The beautiful colors really add to this. The only thing I would think could have made it a bit better is to be down lower or crop out the top a bit, but that might take part of his tail:( .', '2002-04-15 08:45:00.000000', NULL, 1),
(49142, 900, 641, '<td valign="top">I love this. Great color and fun shot!</td>', 'I love this. Great color and fun shot!', '2002-04-15 09:50:00.000000', NULL, 1),
(49143, 900, 656, '<td valign="top">cool - are they linked ? :)   Bit too far away, would have been stronger with less green on the right.  Nice entry though.</td>', 'cool - are they linked ? :)   Bit too far away, would have been stronger with less green on the right.  Nice entry though.', '2002-04-15 10:04:00.000000', NULL, 1),
(49144, 900, 139, '<td valign="top">How long did it take you to get this?  I really like it!</td>', 'How long did it take you to get this?  I really like it!', '2002-04-15 12:35:00.000000', NULL, 1),
(49145, 900, 734, '<td valign="top">great composition</td>', 'great composition', '2002-04-15 12:38:00.000000', NULL, 1),
(49146, 900, 714, '<td valign="top">Nice picture.</td>', 'Nice picture.', '2002-04-15 12:50:00.000000', NULL, 1),
(49147, 900, 279, '<td valign="top">I''m a sucker for smiling labs! Good shot too.</td>', 'I''m a sucker for smiling labs! Good shot too.', '2002-04-15 13:07:00.000000', NULL, 1),
(49148, 900, 361, '<td valign="top">Nice, clear, crisp shot. Background is not distracting. How on earth did you get them in step?!!!</td>', 'Nice, clear, crisp shot. Background is not distracting. How on earth did you get them in step?!!!', '2002-04-15 13:14:00.000000', NULL, 1),
(49149, 900, 326, '<td valign="top">wonderful job...they are beautiful!</td>', 'wonderful job...they are beautiful!', '2002-04-15 14:07:00.000000', NULL, 1),
(49150, 900, 509, '<td valign="top">Nice shot</td>', 'Nice shot', '2002-04-15 14:18:00.000000', NULL, 1),
(49151, 900, 142, '<td valign="top">Great photo.  I love how the dog''s personalities show so well.</td>', 'Great photo.  I love how the dog''s personalities show so well.', '2002-04-15 17:03:00.000000', NULL, 1),
(49152, 900, 772, '<td valign="top">This is a very nice photo.  The contrast and composition is excellent.  One of the subtleties of this photo that sets off the ''stopped motion'' challenge is the collar tag from the dog on the left.  It''s suspended !  Good job!</td>', 'This is a very nice photo.  The contrast and composition is excellent.  One of the subtleties of this photo that sets off the ''stopped motion'' challenge is the collar tag from the dog on the left.  It''s suspended !  Good job!', '2002-04-15 17:38:00.000000', NULL, 1),
(49153, 900, 782, '<td valign="top">How long did it take you to teach them to run in step?<br/>Good exposure</td>', 'How long did it take you to teach them to run in step?Good exposure', '2002-04-15 18:41:00.000000', NULL, 1),
(49154, 900, 724, '<td valign="top">Beautiful, Fun and great timing!!</td>', 'Beautiful, Fun and great timing!!', '2002-04-15 22:38:00.000000', NULL, 1),
(49155, 900, 245, '<td valign="top">Just being a stickler here, I would have tried to get a shot with the dogs'' tails away from all the trees and such in the background. It also feels a little washed out to me, a darker exposure and more contrast might help.</td>', 'Just being a stickler here, I would have tried to get a shot with the dogs'' tails away from all the trees and such in the background. It also feels a little washed out to me, a darker exposure and more contrast might help.', '2002-04-16 04:32:00.000000', NULL, 1),
(49156, 900, 748, '<td valign="top">Were you calling the cadence? Nice Shot!</td>', 'Were you calling the cadence? Nice Shot!', '2002-04-16 10:42:00.000000', NULL, 1),
(49157, 900, 2, '<td valign="top">Very cool picture!  Though it definitely would have been tough to coordinate, I''d like this picture more without the trash can and trees in the upper part of the frame.</td>', 'Very cool picture!  Though it definitely would have been tough to coordinate, I''d like this picture more without the trash can and trees in the upper part of the frame.', '2002-04-16 11:29:00.000000', NULL, 1),
(49158, 900, 255, '<td valign="top">wow, i love this! almost makes me want to trade my huskies in on a couple of labs!!:) you get a 10!</td>', 'wow, i love this! almost makes me want to trade my huskies in on a couple of labs!!:) you get a 10!', '2002-04-16 15:50:00.000000', NULL, 1),
(49159, 900, 671, '<td valign="top">excellent focus, interesting subject, well framed.</td>', 'excellent focus, interesting subject, well framed.', '2002-04-17 10:55:00.000000', NULL, 1),
(49160, 900, 749, '<td valign="top">Feels a little oversaturated, and slightly off-centre</td>', 'Feels a little oversaturated, and slightly off-centre', '2002-04-17 16:54:00.000000', NULL, 1),
(49161, 900, 441, '<td valign="top">nice shot</td>', 'nice shot', '2002-04-17 17:30:00.000000', NULL, 1),
(49162, 900, 472, '<td valign="top">it;s a funny pic, nice idea and the dogs are cute.  hmm, i just wish both of their tongues were out, and their tales were at the same angle. then it would be super symmetry!</td>', 'it;s a funny pic, nice idea and the dogs are cute.  hmm, i just wish both of their tongues were out, and their tales were at the same angle. then it would be super symmetry!', '2002-04-17 17:49:00.000000', NULL, 1),
(49163, 900, 933, '<td valign="top">I like dogs.  Dogs rule.</td>', 'I like dogs.  Dogs rule.', '2002-04-17 18:59:00.000000', NULL, 1),
(49164, 900, 1132, '<td valign="top">Sharp.</td>', 'Sharp.', '2002-04-17 19:36:00.000000', NULL, 1),
(49165, 900, 543, '<td valign="top">Great catch, and well focused and exposed.  A slightly higher point of view would have resulted in a better background, but you''ve got to grab these as you can (and there''s always Photoshop).</td>', 'Great catch, and well focused and exposed.  A slightly higher point of view would have resulted in a better background, but you''ve got to grab these as you can (and there''s always Photoshop).', '2002-04-18 12:06:00.000000', NULL, 1),
(49166, 900, 715, '<td valign="top">I think you caught the moving dogs very well. I like the way the paws of the dogs are synchronized. <br/>One minor point though: the small parts of the trees in the background are a little disturbing, especialy the one behind the dogs tail.</td>', 'I think you caught the moving dogs very well. I like the way the paws of the dogs are synchronized. One minor point though: the small parts of the trees in the background are a little disturbing, especialy the one behind the dogs tail.', '2002-04-18 13:57:00.000000', NULL, 1),
(49167, 900, 205, '<td valign="top">I really have no complaints here except maybe if they were running?</td>', 'I really have no complaints here except maybe if they were running?', '2002-04-18 14:28:00.000000', NULL, 1),
(49168, 900, 797, '<td valign="top">ball in and tongue out! ingenious! must''ve been so hard to execute this shot. great work.</td>', 'ball in and tongue out! ingenious! must''ve been so hard to execute this shot. great work.', '2002-04-19 02:45:00.000000', NULL, 1),
(49169, 900, 301, '<td valign="top">Well focused, but not the most interesting of pics</td>', 'Well focused, but not the most interesting of pics', '2002-04-19 08:40:00.000000', NULL, 1),
(49170, 900, 811, '<td valign="top">When you consider the area around their mouths, you can really see how much motion was truly stopped.  Good job, beautiful dogs.</td>', 'When you consider the area around their mouths, you can really see how much motion was truly stopped.  Good job, beautiful dogs.', '2002-04-19 10:19:00.000000', NULL, 1),
(49171, 900, 1175, '<td valign="top">Nice shot.  Would have been cooler if the dog was in the air catching that ball though.  Doesn''t imply enough motion.</td>', 'Nice shot.  Would have been cooler if the dog was in the air catching that ball though.  Doesn''t imply enough motion.', '2002-04-19 14:39:00.000000', NULL, 1),
(49172, 900, 689, '<td valign="top">Slightly over-exposed ...</td>', 'Slightly over-exposed ...', '2002-04-19 21:39:00.000000', NULL, 1),
(49173, 900, 113, '<td valign="top">Yes, nice dogs.  Twins?</td>', 'Yes, nice dogs.  Twins?', '2002-04-20 06:14:00.000000', NULL, 1),
(49174, 900, 1, '<td valign="top">Not the most stopped of action.  Maybe of the dogs catching the ball mid-air would''ve been more dramatic.</td>', 'Not the most stopped of action.  Maybe of the dogs catching the ball mid-air would''ve been more dramatic.', '2002-04-20 09:46:00.000000', NULL, 1),
(49175, 900, 1202, '<td valign="top">I can''t help but like the dogs.   Yes they are stopped, too bad the background couldn''t have been all grass.</td>', 'I can''t help but like the dogs.   Yes they are stopped, too bad the background couldn''t have been all grass.', '2002-04-20 10:00:00.000000', NULL, 1),
(49176, 900, 661, '<td valign="top">Thank you for all the great comments.  I took this picture at the Dog Park in Encino, CA.  I don''t own any dogs.  The two dogs are mother and daughter.  I did take several pictures of  jumping dogs but none of them was clear enough to submit and not get the "needs better focus" comment.  This picture took two sessions at the dog park.</td>', 'Thank you for all the great comments.  I took this picture at the Dog Park in Encino, CA.  I don''t own any dogs.  The two dogs are mother and daughter.  I did take several pictures of  jumping dogs but none of them was clear enough to submit and not get the "needs better focus" comment.  This picture took two sessions at the dog park.', '2002-04-22 08:58:00.000000', NULL, 0),
(49177, 901, 92, '<td valign="top">WoW ! Talk about timing of shutter lag ! You did great at being able to capture this. Great cropping also. Nice job!</td>', 'WoW ! Talk about timing of shutter lag ! You did great at being able to capture this. Great cropping also. Nice job!', '2002-04-15 07:59:00.000000', NULL, 1),
(49178, 901, 641, '<td valign="top">I like the composition and the lines in this. Nice</td>', 'I like the composition and the lines in this. Nice', '2002-04-15 09:48:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(49179, 901, 1024, '<td valign="top">If this would have been cropped a little tighter, it would have been better.  Still a good picture.</td>', 'If this would have been cropped a little tighter, it would have been better.  Still a good picture.', '2002-04-15 10:09:00.000000', NULL, 1),
(49180, 901, 656, '<td valign="top">Nice - bit too centrally framed - maybe with the candle further to the side would have been stronger ?  Or perhaps a vertical shot, rather than a horizontal frame.</td>', 'Nice - bit too centrally framed - maybe with the candle further to the side would have been stronger ?  Or perhaps a vertical shot, rather than a horizontal frame.', '2002-04-15 10:33:00.000000', NULL, 1),
(49181, 901, 675, '<td valign="top">good transitions photo, also good stop action</td>', 'good transitions photo, also good stop action', '2002-04-15 13:38:00.000000', NULL, 1),
(49182, 901, 748, '<td valign="top">Great shot, good focus.</td>', 'Great shot, good focus.', '2002-04-15 14:55:00.000000', NULL, 1),
(49183, 901, 734, '<td valign="top">Great detail, i hope you didnt burn your hand.</td>', 'Great detail, i hope you didnt burn your hand.', '2002-04-15 17:38:00.000000', NULL, 1),
(49184, 901, 714, '<td valign="top">Good photo.</td>', 'Good photo.', '2002-04-15 19:19:00.000000', NULL, 1),
(49185, 901, 813, '<td valign="top">Excellent execution of a good idea. I would have rated it higher if it were not framed nearly dead center.</td>', 'Excellent execution of a good idea. I would have rated it higher if it were not framed nearly dead center.', '2002-04-15 19:19:00.000000', NULL, 1),
(49186, 901, 772, '<td valign="top">This is an interesting photo.  Fire isn''t an easy subject to shot stopped motion since it has a natural blur to it.  The igniting match adds some excitement to this photo.</td>', 'This is an interesting photo.  Fire isn''t an easy subject to shot stopped motion since it has a natural blur to it.  The igniting match adds some excitement to this photo.', '2002-04-15 19:21:00.000000', NULL, 1),
(49187, 901, 884, '<td valign="top">Eerie effect. Also, I''m a pyro, haha. Nice!</td>', 'Eerie effect. Also, I''m a pyro, haha. Nice!', '2002-04-15 21:24:00.000000', NULL, 1),
(49188, 901, 1, '<td valign="top">Cool shot, I think the exposure works well.  Bright enough to see the match and candle, and dim enough to not expose the fire TOO much.</td>', 'Cool shot, I think the exposure works well.  Bright enough to see the match and candle, and dim enough to not expose the fire TOO much.', '2002-04-16 07:56:00.000000', NULL, 1),
(49189, 901, 640, '<td valign="top">A nice flame. I think just the candle and single flame would have been nicer</td>', 'A nice flame. I think just the candle and single flame would have been nicer', '2002-04-16 09:42:00.000000', NULL, 1),
(49190, 901, 255, '<td valign="top">i can hear the sizzle!</td>', 'i can hear the sizzle!', '2002-04-16 15:44:00.000000', NULL, 1),
(49191, 901, 441, '<td valign="top">good interesting shot - nice setup</td>', 'good interesting shot - nice setup', '2002-04-16 16:21:00.000000', NULL, 1),
(49192, 901, 472, '<td valign="top">i like the spark coming off the match head.</td>', 'i like the spark coming off the match head.', '2002-04-17 11:52:00.000000', NULL, 1),
(49193, 901, 749, '<td valign="top">The first thing this reminded me of was the title sequence of Mission: Impossible :o)</td>', 'The first thing this reminded me of was the title sequence of Mission: Impossible :o)', '2002-04-17 18:35:00.000000', NULL, 1),
(49194, 901, 933, '<td valign="top">Seems a bit out of focus.</td>', 'Seems a bit out of focus.', '2002-04-17 18:57:00.000000', NULL, 1),
(49195, 901, 1132, '<td valign="top">Neat idea.</td>', 'Neat idea.', '2002-04-17 22:59:00.000000', NULL, 1),
(49196, 901, 205, '<td valign="top">its seems to me like a faster shutter speed was needed</td>', 'its seems to me like a faster shutter speed was needed', '2002-04-18 03:03:00.000000', NULL, 1),
(49197, 901, 543, '<td valign="top">Nice transition photo.  Looks like there''s a hair on the match, and I''d crop the sides and go for a vertical comp.</td>', 'Nice transition photo.  Looks like there''s a hair on the match, and I''d crop the sides and go for a vertical comp.', '2002-04-18 10:10:00.000000', NULL, 1),
(49198, 901, 245, '<td valign="top">you cheater, the candle was already burning when you stuck the match into it. ;) it''s a cool shot nonetheless! I wouldn''t have have framed the candle right int he center, though.<br/></td>', 'you cheater, the candle was already burning when you stuck the match into it. ;) it''s a cool shot nonetheless! I wouldn''t have have framed the candle right int he center, though.', '2002-04-18 13:24:00.000000', NULL, 1),
(49199, 901, 1164, '<td valign="top">Great Idea</td>', 'Great Idea', '2002-04-18 16:06:00.000000', NULL, 1),
(49200, 901, 1141, '<td valign="top">Nice coloring</td>', 'Nice coloring', '2002-04-18 18:17:00.000000', NULL, 1),
(49201, 901, 142, '<td valign="top">Well done.  I like this twist on stop action and it is an appealing photo.</td>', 'Well done.  I like this twist on stop action and it is an appealing photo.', '2002-04-18 21:00:00.000000', NULL, 1),
(49202, 901, 797, '<td valign="top">oh this is beatiful. i thought of doing a candle being blown out myself, but this is better!</td>', 'oh this is beatiful. i thought of doing a candle being blown out myself, but this is better!', '2002-04-19 08:33:00.000000', NULL, 1),
(49203, 901, 811, '<td valign="top">Good "crispness" on the match and candle.  I liked this shot.</td>', 'Good "crispness" on the match and candle.  I liked this shot.', '2002-04-19 09:23:00.000000', NULL, 1),
(49204, 901, 1175, '<td valign="top">This is a great photo.</td>', 'This is a great photo.', '2002-04-19 19:32:00.000000', NULL, 1),
(49205, 901, 113, '<td valign="top">Very nice, bet that was a hard one.</td>', 'Very nice, bet that was a hard one.', '2002-04-20 05:03:00.000000', NULL, 1),
(49206, 901, 1135, '<td valign="top">Nice</td>', 'Nice', '2002-04-21 18:09:00.000000', NULL, 1),
(49207, 901, 806, '<td valign="top">i like how you caught the spark at the end of the match. i might crop off part of the dark area on the right, and even a bit off the left where the match goes into darkness so as to keep the candle and flame a bit off center, and creating a vertical shot which would be in keeping with the shape of the subject.</td>', 'i like how you caught the spark at the end of the match. i might crop off part of the dark area on the right, and even a bit off the left where the match goes into darkness so as to keep the candle and flame a bit off center, and creating a vertical shot which would be in keeping with the shape of the subject.', '2002-04-21 18:28:00.000000', NULL, 1),
(49208, 901, 790, '<td valign="top">nice close up</td>', 'nice close up', '2002-04-21 20:51:00.000000', NULL, 1),
