(49211, 902, 656, '<td valign="top">Looks like the statue of liberty rising from the water!</td>', 'Looks like the statue of liberty rising from the water!', '2002-04-15 11:45:00.000000', NULL, 1),
(49212, 902, 189, '<td valign="top">Water, Water Everywhere !</td>', 'Water, Water Everywhere !', '2002-04-15 12:34:00.000000', NULL, 1),
(49213, 902, 772, '<td valign="top">I like this photograph!!  This is a very nice example of stopped motion.  All compositional elements are fine with me.  I''m trying to decide what the blue background is doing to help the photo. Im not sure that its giving me the contrast that I would like to see but, none-the-less, this is nice work :)</td>', 'I like this photograph!!  This is a very nice example of stopped motion.  All compositional elements are fine with me.  I''m trying to decide what the blue background is doing to help the photo. Im not sure that its giving me the contrast that I would like to see but, none-the-less, this is nice work :)', '2002-04-15 12:42:00.000000', NULL, 1),
