(49224, 902, 205, '<td valign="top">A bit dark, and way too obvious that your only light source was your flash. Almost looks like it some blob figure giving the socialist salute.</td>', 'A bit dark, and way too obvious that your only light source was your flash. Almost looks like it some blob figure giving the socialist salute.', '2002-04-16 18:39:00.000000', NULL, 1),
(49225, 902, 773, '<td valign="top">Very curious what the title means...could it mean "person rising from water"?  Nice shot.</td>', 'Very curious what the title means...could it mean "person rising from water"?  Nice shot.', '2002-04-16 20:16:00.000000', NULL, 1),
(49226, 902, 749, '<td valign="top">Perfect focus and timing, plus the purple reflections help keep the photo from feeling too monotone</td>', 'Perfect focus and timing, plus the purple reflections help keep the photo from feeling too monotone', '2002-04-17 16:24:00.000000', NULL, 1),
(49227, 902, 1132, '<td valign="top">I like the form of the splash. It almost looks like a person with their hands reaching out - perhaps drowning. I think the picture could be enhanced with a different colored background. Perhaps red?</td>', 'I like the form of the splash. It almost looks like a person with their hands reaching out - perhaps drowning. I think the picture could be enhanced with a different colored background. Perhaps red?', '2002-04-17 16:24:00.000000', NULL, 1),
(49228, 902, 472, '<td valign="top">i see her, i see the naiad!  very cool concept : ) only thing is i would do a lot more levels tweaking.</td>', 'i see her, i see the naiad!  very cool concept : ) only thing is i would do a lot more levels tweaking.', '2002-04-17 17:47:00.000000', NULL, 1),
(49229, 902, 933, '<td valign="top">A little too dark.  Would have been better without the shadow in the backgroud.  Try pulling the oject away from the background.</td>', 'A little too dark.  Would have been better without the shadow in the backgroud.  Try pulling the oject away from the background.', '2002-04-17 18:56:00.000000', NULL, 1),
(49230, 902, 587, '<td valign="top">Great shot. Am I the only one to see a ''jump shot'' in this? I like the shadow, wish it was a little lighter though.</td>', 'Great shot. Am I the only one to see a ''jump shot'' in this? I like the shadow, wish it was a little lighter though.', '2002-04-17 19:40:00.000000', NULL, 1),
