(49232, 902, 543, '<td valign="top">Move the glass about 14 feet from the wall and you''d have something.  It''s a cool catch, but that flash shadow really hinders it.</td>', 'Move the glass about 14 feet from the wall and you''d have something.  It''s a cool catch, but that flash shadow really hinders it.', '2002-04-18 09:30:00.000000', NULL, 1),
(49233, 902, 671, '<td valign="top">Great stop action, the color accents are nice.  I can see the water sprite clearly.</td>', 'Great stop action, the color accents are nice.  I can see the water sprite clearly.', '2002-04-18 11:04:00.000000', NULL, 1),
(49234, 902, 491, '<td valign="top">Great stop motion.  It looks like an ice statue.</td>', 'Great stop motion.  It looks like an ice statue.', '2002-04-18 19:50:00.000000', NULL, 1),
(49235, 902, 245, '<td valign="top">I would have cropped off the reflection of the flash in the glass, it''s a little distracting</td>', 'I would have cropped off the reflection of the flash in the glass, it''s a little distracting', '2002-04-19 02:32:00.000000', NULL, 1),
