(49375, 916, 205, '<td valign="top">I''m having a hard time telling what this is but it looks cool</td>', 'I''m having a hard time telling what this is but it looks cool', '2002-04-18 02:48:00.000000', NULL, 1),
(49376, 916, 543, '<td valign="top">Very interesting, and well composed.  The three flash spots up left are a bummer, though.  Might show better with a + gamma adjustment.</td>', 'Very interesting, and well composed.  The three flash spots up left are a bummer, though.  Might show better with a + gamma adjustment.', '2002-04-18 09:13:00.000000', NULL, 1),
