(49413, 917, 554, '<td valign="top">A lot of talent on both sides of the lens</td>', 'A lot of talent on both sides of the lens', '2002-04-17 22:02:00.000000', NULL, 1),
(49414, 917, 2, '<td valign="top">Nice colors.  I like the choice just to show the arms of the juggler.  And I''m sure the request to catch the entire red and yellow objects is a tough one, but I think it would have yielded even better results.</td>', 'Nice colors.  I like the choice just to show the arms of the juggler.  And I''m sure the request to catch the entire red and yellow objects is a tough one, but I think it would have yielded even better results.', '2002-04-18 00:25:00.000000', NULL, 1),
