(49749, 927, 749, '<td valign="top">Interesting use of the wire fence, helps emphasise the pitcher and ball as separate.</td>', 'Interesting use of the wire fence, helps emphasise the pitcher and ball as separate.', '2002-04-17 18:32:00.000000', NULL, 1),
