(49763, 929, 641, '<td valign="top">Bet she was tired after all jumping. I like the shot, but the background is too busy and takes away from the subject.</td>', 'Bet she was tired after all jumping. I like the shot, but the background is too busy and takes away from the subject.', '2002-04-15 10:21:00.000000', NULL, 1),
(49764, 929, 772, '<td valign="top">I wonder what this photo would look like with a tighter crop around the child?  I''m not sure, but I think the subject may be slightly out of focus.</td>', 'I wonder what this photo would look like with a tighter crop around the child?  I''m not sure, but I think the subject may be slightly out of focus.', '2002-04-15 10:26:00.000000', NULL, 1),
(49765, 929, 656, '<td valign="top">cool action shot - definatly a keeper.  The background is too cluttered though, which distracts from the subject - a different location would have cleaned that up a lot.</td>', 'cool action shot - definatly a keeper.  The background is too cluttered though, which distracts from the subject - a different location would have cleaned that up a lot.', '2002-04-15 10:32:00.000000', NULL, 1),
(49766, 929, 139, '<td valign="top">Good title, good photo.  If the background was not too bad, I would have faced the other way to change the shadows.</td>', 'Good title, good photo.  If the background was not too bad, I would have faced the other way to change the shadows.', '2002-04-15 11:04:00.000000', NULL, 1),
(49767, 929, 714, '<td valign="top">Good job, but her face is a little out of focus.</td>', 'Good job, but her face is a little out of focus.', '2002-04-15 12:25:00.000000', NULL, 1),
(49768, 929, 189, '<td valign="top">ooh i Love kidz!</td>', 'ooh i Love kidz!', '2002-04-15 12:38:00.000000', NULL, 1),
(49769, 929, 718, '<td valign="top">Nice height.  She''s going to be an athlete.</td>', 'Nice height.  She''s going to be an athlete.', '2002-04-15 14:21:00.000000', NULL, 1),
(49770, 929, 748, '<td valign="top">Focus is a bit better on the background than the subject, but still a nice shot.</td>', 'Focus is a bit better on the background than the subject, but still a nice shot.', '2002-04-15 15:01:00.000000', NULL, 1),
(49771, 929, 724, '<td valign="top">Great jump!! The shirt is a bit blown out though.</td>', 'Great jump!! The shirt is a bit blown out though.', '2002-04-15 22:52:00.000000', NULL, 1),
(49772, 929, 640, '<td valign="top">Good high jump! I would have prefered it a little closer up</td>', 'Good high jump! I would have prefered it a little closer up', '2002-04-16 01:30:00.000000', NULL, 1),
(49773, 929, 813, '<td valign="top">Very nice, good focus, excellent action, love the joyfullness, nice color</td>', 'Very nice, good focus, excellent action, love the joyfullness, nice color', '2002-04-16 13:56:00.000000', NULL, 1),
(49774, 929, 441, '<td valign="top">nice pic, well caught.</td>', 'nice pic, well caught.', '2002-04-16 14:18:00.000000', NULL, 1),
(49775, 929, 910, '<td valign="top">great composition.</td>', 'great composition.', '2002-04-16 21:52:00.000000', NULL, 1),
(49776, 929, 671, '<td valign="top">This really captures the essence of spring.  What a great shot!</td>', 'This really captures the essence of spring.  What a great shot!', '2002-04-17 10:49:00.000000', NULL, 1),
(49777, 929, 472, '<td valign="top">sort of typical shot, altho the child is cute and she is very high off the ground!</td>', 'sort of typical shot, altho the child is cute and she is very high off the ground!', '2002-04-17 17:45:00.000000', NULL, 1),
(49778, 929, 587, '<td valign="top">I like how you made it look like she''s 5 feet off the ground - great photo.</td>', 'I like how you made it look like she''s 5 feet off the ground - great photo.', '2002-04-17 19:46:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(49779, 929, 2, '<td valign="top">Great action -- slightly out of focus.</td>', 'Great action -- slightly out of focus.', '2002-04-18 00:21:00.000000', NULL, 1),
(49780, 929, 205, '<td valign="top">Shes got a lot of bounce for a little girl, yet shes a little out focus</td>', 'Shes got a lot of bounce for a little girl, yet shes a little out focus', '2002-04-18 02:51:00.000000', NULL, 1),
(49781, 929, 301, '<td valign="top">I would have tried to blur out the background</td>', 'I would have tried to blur out the background', '2002-04-18 10:28:00.000000', NULL, 1),
(49782, 929, 142, '<td valign="top">A little more focus on the girl and a slightly different angle (perhaps towards the tree a little more) would make this a perfect shot.  Otherwise it is a cute picture.</td>', 'A little more focus on the girl and a slightly different angle (perhaps towards the tree a little more) would make this a perfect shot.  Otherwise it is a cute picture.', '2002-04-18 11:29:00.000000', NULL, 1),
(49783, 929, 739, '<td valign="top">Man, that''s a lot of air for the jump.  You picked a good subject who is having a ton of fun.</td>', 'Man, that''s a lot of air for the jump.  You picked a good subject who is having a ton of fun.', '2002-04-19 01:41:00.000000', NULL, 1),
(49784, 929, 797, '<td valign="top">very sprightly! nice.</td>', 'very sprightly! nice.', '2002-04-19 03:50:00.000000', NULL, 1),
(49785, 929, 811, '<td valign="top">The background is distracting.</td>', 'The background is distracting.', '2002-04-19 10:28:00.000000', NULL, 1),
(49786, 929, 933, '<td valign="top">not overly crisp stop-motion.  The subject kind of gets lost against the fance and shed.</td>', 'not overly crisp stop-motion.  The subject kind of gets lost against the fance and shed.', '2002-04-19 11:10:00.000000', NULL, 1),
(49787, 929, 1175, '<td valign="top">Good picture out of focus.</td>', 'Good picture out of focus.', '2002-04-19 11:10:00.000000', NULL, 1),
(49788, 929, 361, '<td valign="top">Ooops! She looks a little out of focus. Otherwise, good idea, good color, good stopped motion.</td>', 'Ooops! She looks a little out of focus. Otherwise, good idea, good color, good stopped motion.', '2002-04-19 14:16:00.000000', NULL, 1),
(49789, 929, 689, '<td valign="top">A little blurred and over-exposed ... nice effort though!</td>', 'A little blurred and over-exposed ... nice effort though!', '2002-04-19 21:34:00.000000', NULL, 1),
(49790, 929, 113, '<td valign="top">Did a nice job of centering.  Nice picture.</td>', 'Did a nice job of centering.  Nice picture.', '2002-04-20 06:22:00.000000', NULL, 1),
(49791, 929, 1, '<td valign="top">Wow!  That child can really jump high.  Cute shot.</td>', 'Wow!  That child can really jump high.  Cute shot.', '2002-04-21 11:36:00.000000', NULL, 1),
(49792, 929, 245, '<td valign="top">you could have darkened this exposure a lot when you took the photo to put more color in the sky and keep more detail in her shirt, the brightest areas are really hot. The sliver of tree along the right feels weird, too... I''d have either cropped most of it off or tried to capture more of it.</td>', 'you could have darkened this exposure a lot when you took the photo to put more color in the sky and keep more detail in her shirt, the brightest areas are really hot. The sliver of tree along the right feels weird, too... I''d have either cropped most of it off or tried to capture more of it.', '2002-04-22 00:36:00.000000', NULL, 1),
(49793, 930, 772, '<td valign="top">This is nice!  Kudos on a difficult photograph... For my constructive criticism on this shot, I would like to comment on depth of field.  The top portion of the water stream is losing focus as it gets closer to the top of the photo.  The only way to correct that, other than a smaller aperture, would be to shoot this shot at a flatter angle, which would have dectracted from the ripples in the back of the photo.  There is also a bubble in front of the water stream that is out of focus.  The ''splash'' effect you have here is really nice!</td>', 'This is nice!  Kudos on a difficult photograph... For my constructive criticism on this shot, I would like to comment on depth of field.  The top portion of the water stream is losing focus as it gets closer to the top of the photo.  The only way to correct that, other than a smaller aperture, would be to shoot this shot at a flatter angle, which would have dectracted from the ripples in the back of the photo.  There is also a bubble in front of the water stream that is out of focus.  The ''splash'' effect you have here is really nice!', '2002-04-15 07:44:00.000000', NULL, 1),
(49794, 930, 641, '<td valign="top">I really like that color, a little blurred on the edges though.</td>', 'I really like that color, a little blurred on the edges though.', '2002-04-15 10:05:00.000000', NULL, 1),
(49795, 930, 139, '<td valign="top">Pretty good, except for the focus.   If you don''t have manual focus, try this.  Put your hand in the stream of water, and make the camera auto focus.  Remove your hand, and click.</td>', 'Pretty good, except for the focus.   If you don''t have manual focus, try this.  Put your hand in the stream of water, and make the camera auto focus.  Remove your hand, and click.', '2002-04-15 11:05:00.000000', NULL, 1),
(49796, 930, 656, '<td valign="top">nice, but a bit out of focus/ not sharp enough.</td>', 'nice, but a bit out of focus/ not sharp enough.', '2002-04-15 11:40:00.000000', NULL, 1),
(49797, 930, 189, '<td valign="top">Average</td>', 'Average', '2002-04-15 12:32:00.000000', NULL, 1),
(49798, 930, 279, '<td valign="top">Pretty, but needs a deeper depth of focus.</td>', 'Pretty, but needs a deeper depth of focus.', '2002-04-15 12:50:00.000000', NULL, 1),
(49799, 930, 1031, '<td valign="top">I like the color...looks more like a "pour" than a "drip" though...</td>', 'I like the color...looks more like a "pour" than a "drip" though...', '2002-04-15 14:20:00.000000', NULL, 1),
(49800, 930, 509, '<td valign="top">So far my favorite of the water shots, love the turquois tint, 10</td>', 'So far my favorite of the water shots, love the turquois tint, 10', '2002-04-15 14:22:00.000000', NULL, 1),
(49801, 930, 138, '<td valign="top">water.. go figure</td>', 'water.. go figure', '2002-04-15 15:02:00.000000', NULL, 1),
(49802, 930, 782, '<td valign="top">I like the almost solarized effect on the water.</td>', 'I like the almost solarized effect on the water.', '2002-04-15 19:17:00.000000', NULL, 1),
(49803, 930, 1, '<td valign="top">Great shot with a nice green/metallic hue.  Well done.</td>', 'Great shot with a nice green/metallic hue.  Well done.', '2002-04-15 21:16:00.000000', NULL, 1),
(49804, 930, 797, '<td valign="top">Nice gurgly feel to the shot! Light is well reflected. Only a little off-focus, unless that is intended.</td>', 'Nice gurgly feel to the shot! Light is well reflected. Only a little off-focus, unless that is intended.', '2002-04-16 00:56:00.000000', NULL, 1),
(49805, 930, 640, '<td valign="top">beautiful. I especially like the swirl</td>', 'beautiful. I especially like the swirl', '2002-04-16 01:11:00.000000', NULL, 1),
(49806, 930, 2, '<td valign="top">Very cool color choice to make the water shot more appealing.</td>', 'Very cool color choice to make the water shot more appealing.', '2002-04-16 11:13:00.000000', NULL, 1),
(49807, 930, 142, '<td valign="top">Great job.</td>', 'Great job.', '2002-04-16 13:36:00.000000', NULL, 1),
(49808, 930, 813, '<td valign="top">plop, it would be great if there were more drops in mid air the tones are good though and the composition is adequate</td>', 'plop, it would be great if there were more drops in mid air the tones are good though and the composition is adequate', '2002-04-16 18:09:00.000000', NULL, 1),
(49809, 930, 1064, '<td valign="top">the color of the water is wonderful. the drops in front are a bit blurry, though</td>', 'the color of the water is wonderful. the drops in front are a bit blurry, though', '2002-04-16 18:51:00.000000', NULL, 1),
(49810, 930, 205, '<td valign="top">Not very sharp its apparent a faster shutter speed was needed along with a better focus.</td>', 'Not very sharp its apparent a faster shutter speed was needed along with a better focus.', '2002-04-16 19:09:00.000000', NULL, 1),
(49811, 930, 910, '<td valign="top">great color</td>', 'great color', '2002-04-16 21:28:00.000000', NULL, 1),
(49812, 930, 472, '<td valign="top">wonderful texture on the water.</td>', 'wonderful texture on the water.', '2002-04-17 12:07:00.000000', NULL, 1),
(49813, 930, 811, '<td valign="top">I like the perspective on this picture.</td>', 'I like the perspective on this picture.', '2002-04-17 14:13:00.000000', NULL, 1),
(49814, 930, 441, '<td valign="top">technically good pic, well stopped running flow ..</td>', 'technically good pic, well stopped running flow ..', '2002-04-17 16:07:00.000000', NULL, 1),
(49815, 930, 749, '<td valign="top">Nice ripples, but the focus lets this one down.</td>', 'Nice ripples, but the focus lets this one down.', '2002-04-17 18:01:00.000000', NULL, 1),
(49816, 930, 587, '<td valign="top">good color, good clarity - makes me thirsty ;)</td>', 'good color, good clarity - makes me thirsty ;)', '2002-04-18 06:56:00.000000', NULL, 1),
(49817, 930, 933, '<td valign="top">Nice, but a tad blurry.</td>', 'Nice, but a tad blurry.', '2002-04-18 14:20:00.000000', NULL, 1),
(49818, 930, 1164, '<td valign="top">Good job</td>', 'Good job', '2002-04-18 16:11:00.000000', NULL, 1),
(49819, 930, 245, '<td valign="top">that''s not a drip, it''s a stream! it''s too bad the bubble up front is out of focus, a longer depth of field would be nice.</td>', 'that''s not a drip, it''s a stream! it''s too bad the bubble up front is out of focus, a longer depth of field would be nice.', '2002-04-19 02:35:00.000000', NULL, 1),
(49820, 930, 1175, '<td valign="top">Looks nice.  Too cliche.</td>', 'Looks nice.  Too cliche.', '2002-04-19 11:30:00.000000', NULL, 1),
(49821, 930, 113, '<td valign="top">I really like the color and the texture of this photo.  Nice job.</td>', 'I really like the color and the texture of this photo.  Nice job.', '2002-04-20 04:40:00.000000', NULL, 1),
(49822, 930, 1202, '<td valign="top">Good stop action, neat color and contrast.   To be a winner for me it needs to include a stronger interest factor.</td>', 'Good stop action, neat color and contrast.   To be a winner for me it needs to include a stronger interest factor.', '2002-04-20 09:56:00.000000', NULL, 1),
(49823, 930, 637, '<td valign="top">well done</td>', 'well done', '2002-04-20 13:28:00.000000', NULL, 1),
(49824, 930, 554, '<td valign="top">Very good. I would have liked it better with more light but I am kind of a lighting nut.  Try playing with light sometime.</td>', 'Very good. I would have liked it better with more light but I am kind of a lighting nut.  Try playing with light sometime.', '2002-04-20 17:55:00.000000', NULL, 1),
(49825, 931, 92, '<td valign="top">It''s a shame this turned out so dark:( Maybe more focus on the subjects and brighter would have worked better for you.</td>', 'It''s a shame this turned out so dark:( Maybe more focus on the subjects and brighter would have worked better for you.', '2002-04-15 08:47:00.000000', NULL, 1),
(49826, 931, 641, '<td valign="top">Good subject matter, wish the lighting was better though.</td>', 'Good subject matter, wish the lighting was better though.', '2002-04-15 10:19:00.000000', NULL, 1),
(49827, 931, 772, '<td valign="top">I like the stopped motion concept of this photo but I believe the lighting needs a little adjustment.  The overall photo is a little dark.  I believe that this particular shot would have been better framed in a vertical photo rather than horizontal.</td>', 'I like the stopped motion concept of this photo but I believe the lighting needs a little adjustment.  The overall photo is a little dark.  I believe that this particular shot would have been better framed in a vertical photo rather than horizontal.', '2002-04-15 10:29:00.000000', NULL, 1),
(49828, 931, 714, '<td valign="top">You could have used better lighting.  Great idea. :)</td>', 'You could have used better lighting.  Great idea. :)', '2002-04-15 10:52:00.000000', NULL, 1),
(49829, 931, 656, '<td valign="top">Dynamic, but needs flash to be better exposed.</td>', 'Dynamic, but needs flash to be better exposed.', '2002-04-15 11:46:00.000000', NULL, 1),
(49830, 931, 326, '<td valign="top">Could of been a little brighter..But I still like it!</td>', 'Could of been a little brighter..But I still like it!', '2002-04-15 13:52:00.000000', NULL, 1),
(49831, 931, 509, '<td valign="top">Nice subject, picture is a little too dark though.</td>', 'Nice subject, picture is a little too dark though.', '2002-04-15 14:19:00.000000', NULL, 1),
(49832, 931, 441, '<td valign="top">action not fully stopped in this one. portrait shot and closer would have helped</td>', 'action not fully stopped in this one. portrait shot and closer would have helped', '2002-04-15 17:09:00.000000', NULL, 1),
(49833, 931, 813, '<td valign="top">This is a good idea that needs more light shined on it.</td>', 'This is a good idea that needs more light shined on it.', '2002-04-15 19:28:00.000000', NULL, 1),
(49834, 931, 131, '<td valign="top">too dark. action is moderate</td>', 'too dark. action is moderate', '2002-04-15 19:44:00.000000', NULL, 1),
(49835, 931, 1031, '<td valign="top">I would have tried to adjust the contrast to bring out more detail in the foreground figures while trying to maintain the overall ambience, but that''s just my style...</td>', 'I would have tried to adjust the contrast to bring out more detail in the foreground figures while trying to maintain the overall ambience, but that''s just my style...', '2002-04-15 21:34:00.000000', NULL, 1),
(49836, 931, 724, '<td valign="top">Abit dark, and some blur too.</td>', 'Abit dark, and some blur too.', '2002-04-15 22:51:00.000000', NULL, 1),
(49837, 931, 352, '<td valign="top">Appears a bit dark.</td>', 'Appears a bit dark.', '2002-04-15 22:56:00.000000', NULL, 1),
(49838, 931, 640, '<td valign="top">a bit dark</td>', 'a bit dark', '2002-04-16 10:07:00.000000', NULL, 1),
(49839, 931, 2, '<td valign="top">Great action shot -- though the lighting is obviously tough to work with.  Maybe experiment with different manual settings getting ready for this shot to try to get as much light as possible.</td>', 'Great action shot -- though the lighting is obviously tough to work with.  Maybe experiment with different manual settings getting ready for this shot to try to get as much light as possible.', '2002-04-16 14:50:00.000000', NULL, 1),
(49840, 931, 910, '<td valign="top">too dark</td>', 'too dark', '2002-04-16 21:28:00.000000', NULL, 1),
(49841, 931, 671, '<td valign="top">Good idea, too dark, a little blurred.  Nice title.</td>', 'Good idea, too dark, a little blurred.  Nice title.', '2002-04-17 10:58:00.000000', NULL, 1),
(49842, 931, 472, '<td valign="top">sure is uneven!  i wonder how you could have made it less dark?  maybe get closer to the fighters with your flash.</td>', 'sure is uneven!  i wonder how you could have made it less dark?  maybe get closer to the fighters with your flash.', '2002-04-17 18:08:00.000000', NULL, 1),
(49843, 931, 749, '<td valign="top">Needs a bit more lighting! IMO,the composition would have benefitted from the camera being slightly more to the left, thus bringing the background fight into view.</td>', 'Needs a bit more lighting! IMO,the composition would have benefitted from the camera being slightly more to the left, thus bringing the background fight into view.', '2002-04-17 18:15:00.000000', NULL, 1),
(49844, 931, 205, '<td valign="top">Its pretty dark</td>', 'Its pretty dark', '2002-04-18 02:53:00.000000', NULL, 1),
(49845, 931, 933, '<td valign="top">This image is so dark you can barely make out the subjects.</td>', 'This image is so dark you can barely make out the subjects.', '2002-04-18 14:27:00.000000', NULL, 1),
(49846, 931, 811, '<td valign="top">A little more light, and being a little closer would have made this picture very effective.</td>', 'A little more light, and being a little closer would have made this picture very effective.', '2002-04-18 15:22:00.000000', NULL, 1),
(49847, 931, 1165, '<td valign="top">Poorly exposed</td>', 'Poorly exposed', '2002-04-18 18:29:00.000000', NULL, 1),
(49848, 931, 142, '<td valign="top">If the lighting was better and you cropped in closer to the opponents, then this would be a great action photo.</td>', 'If the lighting was better and you cropped in closer to the opponents, then this would be a great action photo.', '2002-04-18 21:10:00.000000', NULL, 1),
(49849, 931, 245, '<td valign="top">Well stopped motion for such poor lighting. I would have tried standing near the window so it''s light was striking the side of the people nearest to me. There''s also a ton of compression artifacting, I notice that the picture is 30K when it could be saved up to 150K, you''re losing  a lot of detail you don''t need to be.</td>', 'Well stopped motion for such poor lighting. I would have tried standing near the window so it''s light was striking the side of the people nearest to me. There''s also a ton of compression artifacting, I notice that the picture is 30K when it could be saved up to 150K, you''re losing  a lot of detail you don''t need to be.', '2002-04-19 02:44:00.000000', NULL, 1),
(49850, 931, 797, '<td valign="top">a bit dim. for a fight shot, could be more ''in your face''-ish.</td>', 'a bit dim. for a fight shot, could be more ''in your face''-ish.', '2002-04-19 03:50:00.000000', NULL, 1),
(49851, 931, 862, '<td valign="top">Need more light on the subjects.</td>', 'Need more light on the subjects.', '2002-04-19 08:22:00.000000', NULL, 1),
(49852, 931, 301, '<td valign="top">Nice action shot here.  It''s a little bit dark tho</td>', 'Nice action shot here.  It''s a little bit dark tho', '2002-04-19 08:36:00.000000', NULL, 1),
(49853, 931, 1175, '<td valign="top">too dark. try to get emotions on faces.</td>', 'too dark. try to get emotions on faces.', '2002-04-19 10:36:00.000000', NULL, 1),
(49854, 931, 361, '<td valign="top">Sure wish this wasn''t so dark. It is a really good photo otherwise. What would have been neat is if you could have used the flash and gotten close enough for it to be effective--that would probably "black-out" the background and make the white uniforms really stand out.</td>', 'Sure wish this wasn''t so dark. It is a really good photo otherwise. What would have been neat is if you could have used the flash and gotten close enough for it to be effective--that would probably "black-out" the background and make the white uniforms really stand out.', '2002-04-19 16:35:00.000000', NULL, 1),
(49855, 931, 689, '<td valign="top">A lot of blurring ... next time try a brighter lit subject ... sometimes not even a flash can stop motion.</td>', 'A lot of blurring ... next time try a brighter lit subject ... sometimes not even a flash can stop motion.', '2002-04-19 21:33:00.000000', NULL, 1),
(49856, 931, 113, '<td valign="top">Good shot.  Brighter would have been nice.</td>', 'Good shot.  Brighter would have been nice.', '2002-04-20 05:37:00.000000', NULL, 1),
(49857, 931, 1, '<td valign="top">The image is a bit dark.</td>', 'The image is a bit dark.', '2002-04-20 09:57:00.000000', NULL, 1),
(49858, 931, 346, '<td valign="top">great idea! Cropping the shot might have made a stronger image.</td>', 'great idea! Cropping the shot might have made a stronger image.', '2002-04-20 17:17:00.000000', NULL, 1),
(49859, 931, 1135, '<td valign="top">Too dark, I would like to see her face.</td>', 'Too dark, I would like to see her face.', '2002-04-21 18:05:00.000000', NULL, 1),
(49860, 931, 806, '<td valign="top">a little dark, but i know this is hard to catch, i''ve tried! nice job! maybe crop off the kid standing to the right in the background which would put the subject a bit off center, too.</td>', 'a little dark, but i know this is hard to catch, i''ve tried! nice job! maybe crop off the kid standing to the right in the background which would put the subject a bit off center, too.', '2002-04-21 18:30:00.000000', NULL, 1),
(49861, 931, 790, '<td valign="top">that kick is headed to a far off place</td>', 'that kick is headed to a far off place', '2002-04-21 20:53:00.000000', NULL, 1),
(49862, 932, 1055, '<td valign="top">It looks like she''s about to get hit by a car, but I like it.  I just wish it were more centered.</td>', 'It looks like she''s about to get hit by a car, but I like it.  I just wish it were more centered.', '2002-04-15 09:27:00.000000', NULL, 1),
(49863, 932, 641, '<td valign="top">Good stop motion.. looks like she''s floating.</td>', 'Good stop motion.. looks like she''s floating.', '2002-04-15 10:13:00.000000', NULL, 1),
(49864, 932, 656, '<td valign="top">Funky shot - very Cartier-Bresson-like.  Backgorund lets it down a bit - you couldn''t have got her to jump over that water in the background ? :)</td>', 'Funky shot - very Cartier-Bresson-like.  Backgorund lets it down a bit - you couldn''t have got her to jump over that water in the background ? :)', '2002-04-15 11:44:00.000000', NULL, 1),
(49865, 932, 139, '<td valign="top">I think she''s about to take off flying!  I love the idea.</td>', 'I think she''s about to take off flying!  I love the idea.', '2002-04-15 12:46:00.000000', NULL, 1),
