(49964, 935, 1175, '<td valign="top">Good idea.  Frontal picture of jugler with three colored balls and facial expression would have been great.</td>', 'Good idea.  Frontal picture of jugler with three colored balls and facial expression would have been great.', '2002-04-19 11:12:00.000000', NULL, 1),
(49965, 935, 933, '<td valign="top">Th background is kind of distracting.  Would be more interesting if there was another ball or something to help balance out the shot a little more.</td>', 'Th background is kind of distracting.  Would be more interesting if there was another ball or something to help balance out the shot a little more.', '2002-04-21 02:50:00.000000', NULL, 1),
(49966, 935, 346, '<td valign="top">good stop action shot, but not enough to hold my attention</td>', 'good stop action shot, but not enough to hold my attention', '2002-04-21 08:16:00.000000', NULL, 1),
(49967, 935, 1, '<td valign="top">One handed juggling?  A traditional juggling shot should contain two hands and 3 or more objects, no?</td>', 'One handed juggling?  A traditional juggling shot should contain two hands and 3 or more objects, no?', '2002-04-21 11:45:00.000000', NULL, 1),
(49968, 936, 107, '<td valign="top">Its a decent picture.. I might have zoomed in a bit closer to the guy.. he gets a bit lost amongst the background.  Does the use of black and white add anything to this picture?</td>', 'Its a decent picture.. I might have zoomed in a bit closer to the guy.. he gets a bit lost amongst the background.  Does the use of black and white add anything to this picture?', '2002-04-15 06:26:00.000000', NULL, 1),
(49969, 936, 656, '<td valign="top">Lovely shot.  Good composition, with strong leading in lines and some good diagonals.  Jogger is placed well, with plenty of room to ''run in to''.  Could have been a bit tighter cropped into the top, to hide the sliver of sky in the top right.  Also the jogger might have been better seconds earlier, when against the stone, rather than infront of the tree.   Great entry.</td>', 'Lovely shot.  Good composition, with strong leading in lines and some good diagonals.  Jogger is placed well, with plenty of room to ''run in to''.  Could have been a bit tighter cropped into the top, to hide the sliver of sky in the top right.  Also the jogger might have been better seconds earlier, when against the stone, rather than infront of the tree.   Great entry.', '2002-04-15 08:18:00.000000', NULL, 1),
(49970, 936, 641, '<td valign="top">Good composition, I''m a sucker for b/w shots. But it is a good too.</td>', 'Good composition, I''m a sucker for b/w shots. But it is a good too.', '2002-04-15 10:00:00.000000', NULL, 1),
(49971, 936, 205, '<td valign="top">A skateboarder would have been much better<br/></td>', 'A skateboarder would have been much better', '2002-04-15 10:11:00.000000', NULL, 1),
(49972, 936, 734, '<td valign="top">Nice contrast, good use of b&amp;w</td>', 'Nice contrast, good use of b&w', '2002-04-15 12:34:00.000000', NULL, 1),
(49973, 936, 279, '<td valign="top">Another one where I think the use of B&amp;W was questionable. There''s not enough contrast or tight enough framing between the runner and the background to really make him or her pop out, I almost didn''t notice her at first!</td>', 'Another one where I think the use of B&W was questionable. There''s not enough contrast or tight enough framing between the runner and the background to really make him or her pop out, I almost didn''t notice her at first!', '2002-04-15 13:09:00.000000', NULL, 1),
(49974, 936, 92, '<td valign="top">Just too much area and not enough subject:( Maybe try to put your focus and cropping to be more on the main subject in your photo:)</td>', 'Just too much area and not enough subject:( Maybe try to put your focus and cropping to be more on the main subject in your photo:)', '2002-04-15 14:38:00.000000', NULL, 1),
(49975, 936, 772, '<td valign="top">I love black and whites.  This is an excellent photo but I would like to see a more dramatic instance of stopped motion.</td>', 'I love black and whites.  This is an excellent photo but I would like to see a more dramatic instance of stopped motion.', '2002-04-15 16:07:00.000000', NULL, 1),
(49976, 936, 813, '<td valign="top">Loves the black and white.</td>', 'Loves the black and white.', '2002-04-15 19:22:00.000000', NULL, 1),
(49977, 936, 661, '<td valign="top">Good composition.</td>', 'Good composition.', '2002-04-15 19:35:00.000000', NULL, 1),
(49978, 936, 1, '<td valign="top">Cool shot, something about it just works.</td>', 'Cool shot, something about it just works.', '2002-04-15 21:40:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(49979, 936, 910, '<td valign="top">nice composition.  But a little too much composition and not enough stopped motion.</td>', 'nice composition.  But a little too much composition and not enough stopped motion.', '2002-04-16 03:59:00.000000', NULL, 1),
(49980, 936, 245, '<td valign="top">His head gets kinda lost in the trees, I think it would look nice if he were completely in front of a wall. The black an white works really well for this subject!</td>', 'His head gets kinda lost in the trees, I think it would look nice if he were completely in front of a wall. The black an white works really well for this subject!', '2002-04-16 04:45:00.000000', NULL, 1),
(49981, 936, 142, '<td valign="top">I like how you have captured the jogger in mid air.  Great job.</td>', 'I like how you have captured the jogger in mid air.  Great job.', '2002-04-16 13:58:00.000000', NULL, 1),
(49982, 936, 255, '<td valign="top">i love this picture!</td>', 'i love this picture!', '2002-04-16 15:56:00.000000', NULL, 1),
(49983, 936, 441, '<td valign="top">fine composition but very little detail of stopped motion</td>', 'fine composition but very little detail of stopped motion', '2002-04-16 16:24:00.000000', NULL, 1),
(49984, 936, 308, '<td valign="top">Great contrast, great composition, great setup.  I love this photo!</td>', 'Great contrast, great composition, great setup.  I love this photo!', '2002-04-16 18:45:00.000000', NULL, 1),
(49985, 936, 332, '<td valign="top">I don''t think it captures ''Stop Motion'' very well. But I liked it!</td>', 'I don''t think it captures ''Stop Motion'' very well. But I liked it!', '2002-04-16 20:48:00.000000', NULL, 1),
(49986, 936, 811, '<td valign="top">Possibly cropped to maked the runner more obvious, say on the left or in the foreground?</td>', 'Possibly cropped to maked the runner more obvious, say on the left or in the foreground?', '2002-04-17 11:58:00.000000', NULL, 1),
(49987, 936, 472, '<td valign="top">nice compositin.</td>', 'nice compositin.', '2002-04-17 12:12:00.000000', NULL, 1),
(49988, 936, 933, '<td valign="top">A little underexposed, but the more I looked at it, the more I liked it.  Nice shot.</td>', 'A little underexposed, but the more I looked at it, the more I liked it.  Nice shot.', '2002-04-17 18:44:00.000000', NULL, 1),
(49989, 936, 2, '<td valign="top">Nice composition.  I like your choice to shoot this in b&amp;w.  Though I think stamina would have been going UP the stairs :)</td>', 'Nice composition.  I like your choice to shoot this in b&w.  Though I think stamina would have been going UP the stairs :)', '2002-04-18 00:18:00.000000', NULL, 1),
(49990, 936, 1061, '<td valign="top">Nice BW</td>', 'Nice BW', '2002-04-18 00:21:00.000000', NULL, 1),
(49991, 936, 587, '<td valign="top">...Nike,....Just Do It......would make a great ad for them! would like to have seen him completely off the ground.</td>', '...Nike,....Just Do It......would make a great ad for them! would like to have seen him completely off the ground.', '2002-04-18 07:56:00.000000', NULL, 1),
(49992, 936, 1141, '<td valign="top">I love the way you combined architecture and movement.</td>', 'I love the way you combined architecture and movement.', '2002-04-18 18:14:00.000000', NULL, 1),
(49993, 936, 797, '<td valign="top">wow. i like the way you use the steps to convey depth/perspective. lovely shot.</td>', 'wow. i like the way you use the steps to convey depth/perspective. lovely shot.', '2002-04-19 02:41:00.000000', NULL, 1),
(49994, 936, 1175, '<td valign="top">Ironically I like everything except for the runner.  His feet are placed too close to eachother so it doesn''t imply enough movement.  This would have been great if he had been jumping down that downgrade.</td>', 'Ironically I like everything except for the runner.  His feet are placed too close to eachother so it doesn''t imply enough movement.  This would have been great if he had been jumping down that downgrade.', '2002-04-19 19:37:00.000000', NULL, 1),
(49995, 936, 637, '<td valign="top">doesn''t clearly indicate motion to me</td>', 'doesn''t clearly indicate motion to me', '2002-04-20 13:27:00.000000', NULL, 1),
(49996, 936, 244, '<td valign="top">Nice use of leading lines in this picture, the black and white was a nice choice it adds a good overall mood to this picture.</td>', 'Nice use of leading lines in this picture, the black and white was a nice choice it adds a good overall mood to this picture.', '2002-04-20 16:26:00.000000', NULL, 1),
(49997, 936, 739, '<td valign="top">I like the diagonal like formed by the steps.  It''s gives a strong visual clue of motion.  This is the first picture I noticed that took advantage of lines to convey motion.</td>', 'I like the diagonal like formed by the steps.  It''s gives a strong visual clue of motion.  This is the first picture I noticed that took advantage of lines to convey motion.', '2002-04-20 20:44:00.000000', NULL, 1),
(49998, 936, 806, '<td valign="top">i''m losing the subject in the background.</td>', 'i''m losing the subject in the background.', '2002-04-21 18:38:00.000000', NULL, 1),
(49999, 936, 790, '<td valign="top">it would''ve been better if your subject was falling</td>', 'it would''ve been better if your subject was falling', '2002-04-21 20:56:00.000000', NULL, 1),
(50000, 936, 113, '<td valign="top">I really like this photo.  Especially in the B&amp;W.  Good depth and great composition.</td>', 'I really like this photo.  Especially in the B&W.  Good depth and great composition.', '2002-04-21 22:53:00.000000', NULL, 1),
(50001, 938, 156, '<td valign="top">a tad blurry but really cute, i love the ears</td>', 'a tad blurry but really cute, i love the ears', '2002-04-15 08:27:00.000000', NULL, 1),
(50002, 938, 1055, '<td valign="top">goats are always good!</td>', 'goats are always good!', '2002-04-15 09:37:00.000000', NULL, 1),
(50003, 938, 641, '<td valign="top">Very cute photo, and a good shot.</td>', 'Very cute photo, and a good shot.', '2002-04-15 09:42:00.000000', NULL, 1),
(50004, 938, 92, '<td valign="top">What a cool shot ! My only suggestion would be to get lower to the ground but that''s not always easy to do at a spur of the moment shot. This is well done:)</td>', 'What a cool shot ! My only suggestion would be to get lower to the ground but that''s not always easy to do at a spur of the moment shot. This is well done:)', '2002-04-15 09:49:00.000000', NULL, 1),
(50005, 938, 205, '<td valign="top">I didn''t know you could mix a goat with a bunny</td>', 'I didn''t know you could mix a goat with a bunny', '2002-04-15 10:25:00.000000', NULL, 1),
(50006, 938, 656, '<td valign="top">good motion, dull background</td>', 'good motion, dull background', '2002-04-15 11:43:00.000000', NULL, 1),
(50007, 938, 142, '<td valign="top">This photo is cute, very original, well executed.  You captured the challenge perfectly.</td>', 'This photo is cute, very original, well executed.  You captured the challenge perfectly.', '2002-04-15 12:26:00.000000', NULL, 1),
(50008, 938, 714, '<td valign="top">Cute.  I like the shadow as well as the goat.</td>', 'Cute.  I like the shadow as well as the goat.', '2002-04-15 12:29:00.000000', NULL, 1),
(50009, 938, 189, '<td valign="top">Ooh ANimals!!!!!</td>', 'Ooh ANimals!!!!!', '2002-04-15 12:41:00.000000', NULL, 1),
(50010, 938, 326, '<td valign="top">So cute.......Great job!</td>', 'So cute.......Great job!', '2002-04-15 14:53:00.000000', NULL, 1),
(50011, 938, 1031, '<td valign="top">Wish I felt that good (sigh)...</td>', 'Wish I felt that good (sigh)...', '2002-04-15 14:58:00.000000', NULL, 1),
(50012, 938, 527, '<td valign="top">Goats are so funny. I think the perspective is a little bland. I think I would have planted my self real low in the dirt and taken a shot looking up at the goat for a real dynamic shot.</td>', 'Goats are so funny. I think the perspective is a little bland. I think I would have planted my self real low in the dirt and taken a shot looking up at the goat for a real dynamic shot.', '2002-04-15 17:58:00.000000', NULL, 1),
(50013, 938, 772, '<td valign="top">This is a cute photo.. the shadow makes it happen.  I lower camera angle may have helped display that the goat is floating...</td>', 'This is a cute photo.. the shadow makes it happen.  I lower camera angle may have helped display that the goat is floating...', '2002-04-15 18:42:00.000000', NULL, 1),
(50014, 938, 113, '<td valign="top">When the pic first came up all I saw was one ear.  It looked like a cobra.  Scared me!   What a cutie.  Good job, got him with all four off the ground.</td>', 'When the pic first came up all I saw was one ear.  It looked like a cobra.  Scared me!   What a cutie.  Good job, got him with all four off the ground.', '2002-04-16 07:09:00.000000', NULL, 1),
(50015, 938, 301, '<td valign="top">the ears are sooooo funny ... what did you do ... drop the kid from a great height??? :)</td>', 'the ears are sooooo funny ... what did you do ... drop the kid from a great height??? :)', '2002-04-16 08:43:00.000000', NULL, 1),
(50016, 938, 813, '<td valign="top">cute, i like the way the shadow reveals that the goat is airborne</td>', 'cute, i like the way the shadow reveals that the goat is airborne', '2002-04-16 12:31:00.000000', NULL, 1),
(50017, 938, 193, '<td valign="top">Great with the shadow!</td>', 'Great with the shadow!', '2002-04-16 14:43:00.000000', NULL, 1),
(50018, 938, 689, '<td valign="top">Still a little blurring on the legs and tail ...</td>', 'Still a little blurring on the legs and tail ...', '2002-04-16 21:57:00.000000', NULL, 1),
(50019, 938, 1124, '<td valign="top">hehe cute!</td>', 'hehe cute!', '2002-04-17 02:23:00.000000', NULL, 1),
(50020, 938, 671, '<td valign="top">The ears are great!</td>', 'The ears are great!', '2002-04-17 10:59:00.000000', NULL, 1),
(50021, 938, 472, '<td valign="top">aww, that''s so cute, i have a soft spot for baby live stock.</td>', 'aww, that''s so cute, i have a soft spot for baby live stock.', '2002-04-17 11:55:00.000000', NULL, 1),
(50022, 938, 798, '<td valign="top">One of the Billy goats gruff is escaping!</td>', 'One of the Billy goats gruff is escaping!', '2002-04-17 12:03:00.000000', NULL, 1),
(50023, 938, 441, '<td valign="top">good shot, well captured and composed</td>', 'good shot, well captured and composed', '2002-04-17 16:09:00.000000', NULL, 1),
(50024, 938, 749, '<td valign="top">The shadow really makes this shot, but the rest of the background feels saturated.</td>', 'The shadow really makes this shot, but the rest of the background feels saturated.', '2002-04-17 17:34:00.000000', NULL, 1),
(50025, 938, 2, '<td valign="top">Great shot for such a difficult subject.  A lower angle might have helped, as you could have eliminated the distraction of the shadow.  Easier said than done, I know... :D</td>', 'Great shot for such a difficult subject.  A lower angle might have helped, as you could have eliminated the distraction of the shadow.  Easier said than done, I know... :D', '2002-04-18 00:32:00.000000', NULL, 1),
(50026, 938, 587, '<td valign="top">goats fly? ;) Cute photo, find the skid in background distracting from this critter though.</td>', 'goats fly? ;) Cute photo, find the skid in background distracting from this critter though.', '2002-04-18 06:58:00.000000', NULL, 1),
(50027, 938, 543, '<td valign="top">Good exposure on the mixed fur (the one white patch is blown) - not an easy thing to do.  The shadow is great, and I can feel the exhuberance.  BG would be distracting, but it''s appropriately "goaty" and environmental.  Nice work.</td>', 'Good exposure on the mixed fur (the one white patch is blown) - not an easy thing to do.  The shadow is great, and I can feel the exhuberance.  BG would be distracting, but it''s appropriately "goaty" and environmental.  Nice work.', '2002-04-18 12:14:00.000000', NULL, 1),
(50028, 938, 245, '<td valign="top">gaaah! so cuuuuute! the shadow is perfect, you can really tell it''s in the air!</td>', 'gaaah! so cuuuuute! the shadow is perfect, you can really tell it''s in the air!', '2002-04-18 14:04:00.000000', NULL, 1),
(50029, 938, 933, '<td valign="top">Nice balance with subject and shadow.</td>', 'Nice balance with subject and shadow.', '2002-04-18 14:17:00.000000', NULL, 1),
(50030, 938, 811, '<td valign="top">The shadow actually adds a neat effect.</td>', 'The shadow actually adds a neat effect.', '2002-04-18 15:33:00.000000', NULL, 1),
(50031, 938, 797, '<td valign="top">how''d u get old billy to jump? the use of shadows to tell us THIS IS STOP ACTION NOT A DEAD GOAT is great. high marks!</td>', 'how''d u get old billy to jump? the use of shadows to tell us THIS IS STOP ACTION NOT A DEAD GOAT is great. high marks!', '2002-04-19 02:34:00.000000', NULL, 1),
(50032, 938, 1175, '<td valign="top">Nice shot.  Good timing.  A lower angle would be great for this picture.</td>', 'Nice shot.  Good timing.  A lower angle would be great for this picture.', '2002-04-19 19:50:00.000000', NULL, 1),
(50033, 938, 1, '<td valign="top">This seems just like a point and shoot kind of shot.  Maybe a more artistic approach could''ve been made with a different angle... Perhaps a lower angle to make the goat seem very tall.</td>', 'This seems just like a point and shoot kind of shot.  Maybe a more artistic approach could''ve been made with a different angle... Perhaps a lower angle to make the goat seem very tall.', '2002-04-20 09:32:00.000000', NULL, 1),
(50034, 938, 1202, '<td valign="top">Cute picture but has remaining action that was not stopped.</td>', 'Cute picture but has remaining action that was not stopped.', '2002-04-20 11:46:00.000000', NULL, 1),
(50035, 938, 806, '<td valign="top">cute, and very good catch!</td>', 'cute, and very good catch!', '2002-04-21 18:59:00.000000', NULL, 1),
(50036, 938, 245, '<td valign="top">This was totally one of my favorites, in my universe you would have scored a lot higher. :)</td>', 'This was totally one of my favorites, in my universe you would have scored a lot higher. :)', '2002-04-22 02:38:00.000000', NULL, 0),
(50037, 938, 142, '<td valign="top">I totally agree with Mousie.  This is one of those once in a lifetime shots.  You should be very proud of your submission.</td>', 'I totally agree with Mousie.  This is one of those once in a lifetime shots.  You should be very proud of your submission.', '2002-04-23 13:37:00.000000', NULL, 0),
(50038, 938, 361, '<td valign="top">Thank you all so much for your coments! Mousie &amp; Shortredneck, I am glad you like my photo. It took so many tries to get a good in-the-air shot that was anywhere near in focus!</td>', 'Thank you all so much for your coments! Mousie & Shortredneck, I am glad you like my photo. It took so many tries to get a good in-the-air shot that was anywhere near in focus!', '2002-04-25 12:21:00.000000', NULL, 0),
(50039, 939, 772, '<td valign="top">I like the fog in this photo.  The effect of stopped motion in this photo is OK too.  To improve this photo, I may have cropped differently to eliminate the empty space at the top of the shot.  I don''t know if you could have had the camera lower to the ground, but if so, it may have created a more dramatic effect.</td>', 'I like the fog in this photo.  The effect of stopped motion in this photo is OK too.  To improve this photo, I may have cropped differently to eliminate the empty space at the top of the shot.  I don''t know if you could have had the camera lower to the ground, but if so, it may have created a more dramatic effect.', '2002-04-15 09:23:00.000000', NULL, 1),
(50040, 939, 641, '<td valign="top">Good shot, the red jumps out at you.</td>', 'Good shot, the red jumps out at you.', '2002-04-15 09:44:00.000000', NULL, 1),
(50041, 939, 656, '<td valign="top">good air , but too much sky.  Need to be closer in or more tightly cropped to have a good impact.  Crappy weather didn''t help you much.</td>', 'good air , but too much sky.  Need to be closer in or more tightly cropped to have a good impact.  Crappy weather didn''t help you much.', '2002-04-15 10:08:00.000000', NULL, 1),
(50042, 939, 139, '<td valign="top">The picture is too grey for me.  That, and there are what looks like compression artifacts here.</td>', 'The picture is too grey for me.  That, and there are what looks like compression artifacts here.', '2002-04-15 10:51:00.000000', NULL, 1),
(50043, 939, 885, '<td valign="top">I like the fogginess, it makes it stand out from other snowboard pictures i''ve seen.</td>', 'I like the fogginess, it makes it stand out from other snowboard pictures i''ve seen.', '2002-04-15 15:35:00.000000', NULL, 1),
(50044, 939, 734, '<td valign="top">im a fan of snowboading, but I might have waited for a nicer day to shoot.</td>', 'im a fan of snowboading, but I might have waited for a nicer day to shoot.', '2002-04-15 17:43:00.000000', NULL, 1),
(50045, 939, 714, '<td valign="top">Maybe if you had more of the snowboarder and less of the surroundings I might like it better.</td>', 'Maybe if you had more of the snowboarder and less of the surroundings I might like it better.', '2002-04-15 18:46:00.000000', NULL, 1),
(50046, 939, 813, '<td valign="top">Kawabunga!!</td>', 'Kawabunga!!', '2002-04-15 19:09:00.000000', NULL, 1),
(50047, 939, 661, '<td valign="top">Big air, as they say.  Tricky subject with the limited light.</td>', 'Big air, as they say.  Tricky subject with the limited light.', '2002-04-15 19:38:00.000000', NULL, 1),
(50048, 939, 910, '<td valign="top">a little dark</td>', 'a little dark', '2002-04-16 03:53:00.000000', NULL, 1),
(50049, 939, 446, '<td valign="top">I like your viewing angle.  Very interesting subject.  As constructive criticism, you may have tried to overexpose the scene a little more.  As you may already know, when shooting in a bright scene, such as snow or very bright sunlight, the camera will tend to meter for a short exposure or small (numerically large) aperture as it tries to average the scene to neutral grey.  You then have to overexpose the shot to compensate for this if your subject is a darker object in the scene.  I think this probably would have been a fabulous photo if the exposure would have been "nailed".  Again, please take this in the spirit it is intended as I have no desire to "tell you something you already know".  Nice work.</td>', 'I like your viewing angle.  Very interesting subject.  As constructive criticism, you may have tried to overexpose the scene a little more.  As you may already know, when shooting in a bright scene, such as snow or very bright sunlight, the camera will tend to meter for a short exposure or small (numerically large) aperture as it tries to average the scene to neutral grey.  You then have to overexpose the shot to compensate for this if your subject is a darker object in the scene.  I think this probably would have been a fabulous photo if the exposure would have been "nailed".  Again, please take this in the spirit it is intended as I have no desire to "tell you something you already know".  Nice work.', '2002-04-16 17:46:00.000000', NULL, 1),
(50050, 939, 445, '<td valign="top">nice stop too bad about the bad snow conditions</td>', 'nice stop too bad about the bad snow conditions', '2002-04-16 21:29:00.000000', NULL, 1),
(50051, 939, 441, '<td valign="top">well captured and stopped in what looks pretty poor lighting conditions -  good external flash would have helped to light and colour the subject making it stand out darkening the backdrop and giving u a faster shutter speed - allowing you to get even closer to the subject - just my thoughts - additional equipment is not always at your disposal.</td>', 'well captured and stopped in what looks pretty poor lighting conditions -  good external flash would have helped to light and colour the subject making it stand out darkening the backdrop and giving u a faster shutter speed - allowing you to get even closer to the subject - just my thoughts - additional equipment is not always at your disposal.', '2002-04-17 03:23:00.000000', NULL, 1),
(50052, 939, 301, '<td valign="top">bloody boarders ... nice shot though :)  Shame about the board sticking out in the background</td>', 'bloody boarders ... nice shot though :)  Shame about the board sticking out in the background', '2002-04-17 10:18:00.000000', NULL, 1),
(50053, 939, 472, '<td valign="top">cool. i would have preferred to see the jumper in profile.</td>', 'cool. i would have preferred to see the jumper in profile.', '2002-04-17 12:08:00.000000', NULL, 1),
(50054, 939, 749, '<td valign="top">The red board really stands out and attracts the eye, but needs to be a bit more central</td>', 'The red board really stands out and attracts the eye, but needs to be a bit more central', '2002-04-17 17:00:00.000000', NULL, 1),
(50055, 939, 142, '<td valign="top">You did a good job stopping the motion.  This would have been a more appealing photo if it were taken on a nicer day.</td>', 'You did a good job stopping the motion.  This would have been a more appealing photo if it were taken on a nicer day.', '2002-04-18 11:19:00.000000', NULL, 1),
(50056, 939, 933, '<td valign="top">I like the contrast of the red against the grey of the rest of the image.</td>', 'I like the contrast of the red against the grey of the rest of the image.', '2002-04-18 14:20:00.000000', NULL, 1),
