(50153, 944, 2, '<td valign="top">Good subject for the challege :)</td>', 'Good subject for the challege :)', '2002-04-16 14:58:00.000000', NULL, 1),
(50154, 944, 173, '<td valign="top">Nice albino cat!</td>', 'Nice albino cat!', '2002-04-16 16:21:00.000000', NULL, 1),
(50155, 944, 748, '<td valign="top">A cute shot, but the carpet is a little distracting.</td>', 'A cute shot, but the carpet is a little distracting.', '2002-04-16 17:00:00.000000', NULL, 1),
(50156, 944, 813, '<td valign="top">the picture by itself does not say cat fight, they could just as well be sleeping, would rate higher if it were a more interesting composition</td>', 'the picture by itself does not say cat fight, they could just as well be sleeping, would rate higher if it were a more interesting composition', '2002-04-16 18:06:00.000000', NULL, 1),
(50157, 944, 472, '<td valign="top">heehe these guys are so cute</td>', 'heehe these guys are so cute', '2002-04-17 12:13:00.000000', NULL, 1),
(50158, 944, 811, '<td valign="top">So that''s what a cat looks like still.  I don''t think mine ever is:-)</td>', 'So that''s what a cat looks like still.  I don''t think mine ever is:-)', '2002-04-17 14:33:00.000000', NULL, 1),
(50159, 944, 441, '<td valign="top">like the lighting - no harsh flash shadows</td>', 'like the lighting - no harsh flash shadows', '2002-04-17 17:21:00.000000', NULL, 1),
(50160, 944, 749, '<td valign="top">Redeye, the bane of cat and dog photographers... good focus though.</td>', 'Redeye, the bane of cat and dog photographers... good focus though.', '2002-04-17 17:43:00.000000', NULL, 1),
(50161, 944, 361, '<td valign="top">I like it! Only suggestion would be to back up a bit and get more of the cats in the picture, but you got enough to tell what is going on.</td>', 'I like it! Only suggestion would be to back up a bit and get more of the cats in the picture, but you got enough to tell what is going on.', '2002-04-17 18:45:00.000000', NULL, 1),
(50162, 944, 1061, '<td valign="top">i hate cats</td>', 'i hate cats', '2002-04-18 00:48:00.000000', NULL, 1),
(50163, 944, 205, '<td valign="top">They look like they are playing not fighting</td>', 'They look like they are playing not fighting', '2002-04-18 02:31:00.000000', NULL, 1),
(50164, 944, 933, '<td valign="top">This one just doesn''t grab me for some reason.</td>', 'This one just doesn''t grab me for some reason.', '2002-04-18 14:40:00.000000', NULL, 1),
(50165, 944, 142, '<td valign="top">I love it when cats wrestle like this.  I know it isn''t easy to avoid but the red eye on the white cat kind of takes away from the picture.  Otherwise it is a cute photo.</td>', 'I love it when cats wrestle like this.  I know it isn''t easy to avoid but the red eye on the white cat kind of takes away from the picture.  Otherwise it is a cute photo.', '2002-04-18 21:20:00.000000', NULL, 1),
(50166, 944, 739, '<td valign="top">Could not have seen the motion without the title.  Even so, it''s difficult to imagine the action by looking at the picture.</td>', 'Could not have seen the motion without the title.  Even so, it''s difficult to imagine the action by looking at the picture.', '2002-04-19 01:27:00.000000', NULL, 1),
(50167, 944, 797, '<td valign="top">did it take 354 shots to get this? hard work!</td>', 'did it take 354 shots to get this? hard work!', '2002-04-19 08:22:00.000000', NULL, 1),
(50168, 944, 1164, '<td valign="top">No motion stoped</td>', 'No motion stoped', '2002-04-19 10:34:00.000000', NULL, 1),
(50169, 944, 1175, '<td valign="top">Cute cats.  Hard to figure out what motion was stopped.  May want to try to paly with your angles.</td>', 'Cute cats.  Hard to figure out what motion was stopped.  May want to try to paly with your angles.', '2002-04-19 10:38:00.000000', NULL, 1),
(50170, 944, 1, '<td valign="top">Red-eye reduction is key when using the flash on people/animals.</td>', 'Red-eye reduction is key when using the flash on people/animals.', '2002-04-20 09:49:00.000000', NULL, 1),
(50171, 944, 637, '<td valign="top">not clearly in motion</td>', 'not clearly in motion', '2002-04-20 13:25:00.000000', NULL, 1),
(50172, 944, 245, '<td valign="top">i''d love to see some teeth!</td>', 'i''d love to see some teeth!', '2002-04-22 00:16:00.000000', NULL, 1),
(50173, 945, 193, '<td valign="top">Great sky!</td>', 'Great sky!', '2002-04-15 07:43:00.000000', NULL, 1),
(50174, 945, 1055, '<td valign="top">nice feel</td>', 'nice feel', '2002-04-15 09:45:00.000000', NULL, 1),
(50175, 945, 656, '<td valign="top">Nice capture.  Picture is a bit ''flat'' could do with some contrast adjustments to make it really ''snap''</td>', 'Nice capture.  Picture is a bit ''flat'' could do with some contrast adjustments to make it really ''snap''', '2002-04-15 10:06:00.000000', NULL, 1),
(50176, 945, 279, '<td valign="top">Fantastic, really fantastic. The angle of the fence is amazing, the angle of the boy''s body, everything.</td>', 'Fantastic, really fantastic. The angle of the fence is amazing, the angle of the boy''s body, everything.', '2002-04-15 12:59:00.000000', NULL, 1),
(50177, 945, 675, '<td valign="top">cool</td>', 'cool', '2002-04-15 13:34:00.000000', NULL, 1),
(50178, 945, 509, '<td valign="top">Reference to "The Natural"?  Good picture, a bit grainy though.</td>', 'Reference to "The Natural"?  Good picture, a bit grainy though.', '2002-04-15 14:24:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(50179, 945, 203, '<td valign="top">The ball seems to have blurr or focus problems.</td>', 'The ball seems to have blurr or focus problems.', '2002-04-15 14:26:00.000000', NULL, 1),
(50180, 945, 772, '<td valign="top">I have issues with people photogrphed from behind.  I do see the stopped ball in the photo and recognized this as the stopped motion.  The visual impact of this photo would be enhanced if the shot was a vertical orientation rather than horizontal and if shot from the other side of the batter.</td>', 'I have issues with people photogrphed from behind.  I do see the stopped ball in the photo and recognized this as the stopped motion.  The visual impact of this photo would be enhanced if the shot was a vertical orientation rather than horizontal and if shot from the other side of the batter.', '2002-04-15 15:10:00.000000', NULL, 1),
(50181, 945, 933, '<td valign="top">Image seems kind of low res.  Was this scanned?  Also a little too dark.</td>', 'Image seems kind of low res.  Was this scanned?  Also a little too dark.', '2002-04-15 15:57:00.000000', NULL, 1),
(50182, 945, 308, '<td valign="top">The composition is very good - the photo gives a sense of where the ball is coming from and where it is going to return.  However, I think that it would have been helped if his legs weren''t cut off like that - it just seems awkward and I think the full body would have made this a truly superb photo.</td>', 'The composition is very good - the photo gives a sense of where the ball is coming from and where it is going to return.  However, I think that it would have been helped if his legs weren''t cut off like that - it just seems awkward and I think the full body would have made this a truly superb photo.', '2002-04-15 15:59:00.000000', NULL, 1),
(50183, 945, 441, '<td valign="top">great sky formation - did he hit it?</td>', 'great sky formation - did he hit it?', '2002-04-15 17:26:00.000000', NULL, 1),
(50184, 945, 527, '<td valign="top">but was it a homer? The fence kind of distracts me. Did you consider the other side of the boy to also get an expression to add some more emotion to the scene?</td>', 'but was it a homer? The fence kind of distracts me. Did you consider the other side of the boy to also get an expression to add some more emotion to the scene?', '2002-04-15 17:42:00.000000', NULL, 1),
(50185, 945, 536, '<td valign="top">I would have preferred "he" wasn''t cut off at the calf. But a very nice photo. Good job.</td>', 'I would have preferred "he" wasn''t cut off at the calf. But a very nice photo. Good job.', '2002-04-15 17:52:00.000000', NULL, 1),
(50186, 945, 813, '<td valign="top">Not bad. I like the sky and the overall framing. I think it would benefit from adjusting levels. Could make it more dramatic.</td>', 'Not bad. I like the sky and the overall framing. I think it would benefit from adjusting levels. Could make it more dramatic.', '2002-04-15 18:59:00.000000', NULL, 1),
(50187, 945, 661, '<td valign="top">Nice Action shot.  Slightly out of focus.</td>', 'Nice Action shot.  Slightly out of focus.', '2002-04-15 19:41:00.000000', NULL, 1),
(50188, 945, 724, '<td valign="top">Nice shot, good timing!</td>', 'Nice shot, good timing!', '2002-04-15 22:40:00.000000', NULL, 1),
(50189, 945, 640, '<td valign="top">Nice shot. I would have liked to see the ball a little closer up</td>', 'Nice shot. I would have liked to see the ball a little closer up', '2002-04-16 01:26:00.000000', NULL, 1),
(50190, 945, 245, '<td valign="top">I like how the fence adds to the inwards thrust of the picture, anticipating the ball''s motion before it''s even hit.</td>', 'I like how the fence adds to the inwards thrust of the picture, anticipating the ball''s motion before it''s even hit.', '2002-04-16 05:01:00.000000', NULL, 1),
(50191, 945, 361, '<td valign="top">Good Shot! Could have been a little brighter.</td>', 'Good Shot! Could have been a little brighter.', '2002-04-16 16:56:00.000000', NULL, 1),
(50192, 945, 910, '<td valign="top">cool composition</td>', 'cool composition', '2002-04-16 21:28:00.000000', NULL, 1),
(50193, 945, 472, '<td valign="top">nice picture. great sky.  if you have pshop try autolevels to even it out a little.</td>', 'nice picture. great sky.  if you have pshop try autolevels to even it out a little.', '2002-04-17 17:46:00.000000', NULL, 1),
(50194, 945, 749, '<td valign="top">Good timing! The off-centre batter and ball help emphasise where the ball came from and is just about to go to.</td>', 'Good timing! The off-centre batter and ball help emphasise where the ball came from and is just about to go to.', '2002-04-17 17:49:00.000000', NULL, 1),
(50195, 945, 2, '<td valign="top">Really cool composition -- even the sky seems to play a key role in setting the mood.  Nicely done.</td>', 'Really cool composition -- even the sky seems to play a key role in setting the mood.  Nicely done.', '2002-04-18 00:20:00.000000', NULL, 1),
(50196, 945, 205, '<td valign="top">this has a small amount of compression</td>', 'this has a small amount of compression', '2002-04-18 02:32:00.000000', NULL, 1),
(50197, 945, 862, '<td valign="top">Good idea, but focus on the ball for best results (easier said than done).</td>', 'Good idea, but focus on the ball for best results (easier said than done).', '2002-04-18 08:22:00.000000', NULL, 1),
(50198, 945, 543, '<td valign="top">Nice sky, but imagine it with his feet and without the fence (or even just without the fence).</td>', 'Nice sky, but imagine it with his feet and without the fence (or even just without the fence).', '2002-04-18 09:39:00.000000', NULL, 1),
(50199, 945, 811, '<td valign="top">More ball, less scenery.  It almost gets lost in the picture, to me.</td>', 'More ball, less scenery.  It almost gets lost in the picture, to me.', '2002-04-18 19:15:00.000000', NULL, 1),
(50200, 945, 142, '<td valign="top">This is good stop action.  I think that more of a closeup of the boy would draw the attention to the ball and bat.  As it is, I can''t help but look over towards the trees and clouds.  I can''t help it, you took the photo on such a pretty day.</td>', 'This is good stop action.  I think that more of a closeup of the boy would draw the attention to the ball and bat.  As it is, I can''t help but look over towards the trees and clouds.  I can''t help it, you took the photo on such a pretty day.', '2002-04-18 21:17:00.000000', NULL, 1),
(50201, 945, 797, '<td valign="top">hard to execute! well done.</td>', 'hard to execute! well done.', '2002-04-19 02:44:00.000000', NULL, 1),
(50202, 945, 889, '<td valign="top">Batter Up. I hope he didnt swing at that, its high and outside.</td>', 'Batter Up. I hope he didnt swing at that, its high and outside.', '2002-04-19 13:07:00.000000', NULL, 1),
(50203, 945, 1068, '<td valign="top">Only one question, who is that sexy boy?</td>', 'Only one question, who is that sexy boy?', '2002-04-19 13:16:00.000000', NULL, 1),
(50204, 945, 1191, '<td valign="top">What timing, a split second later and the ball would hev been hidden.  Great photo.</td>', 'What timing, a split second later and the ball would hev been hidden.  Great photo.', '2002-04-19 16:11:00.000000', NULL, 1),
(50205, 945, 1175, '<td valign="top">Nice Timing.  I would have prefered it from the oposie side so we could see the expression on the batter''s face.</td>', 'Nice Timing.  I would have prefered it from the oposie side so we could see the expression on the batter''s face.', '2002-04-19 19:48:00.000000', NULL, 1),
(50206, 945, 113, '<td valign="top">I like the composition and your stopped action ball turned out great just above the fence.</td>', 'I like the composition and your stopped action ball turned out great just above the fence.', '2002-04-20 04:47:00.000000', NULL, 1),
(50207, 945, 1202, '<td valign="top">The ball is definately stopped, but would be a lot better if the pitcher was included.</td>', 'The ball is definately stopped, but would be a lot better if the pitcher was included.', '2002-04-20 09:30:00.000000', NULL, 1),
(50208, 945, 1, '<td valign="top">Looks like it''s gonna be a strike...  The ball is prety close and he''s hardly beginning to swing.</td>', 'Looks like it''s gonna be a strike...  The ball is prety close and he''s hardly beginning to swing.', '2002-04-21 11:43:00.000000', NULL, 1),
(50209, 945, 1135, '<td valign="top">Looks a little late on the swing, like the composition.</td>', 'Looks a little late on the swing, like the composition.', '2002-04-21 17:58:00.000000', NULL, 1),
(50210, 945, 352, '<td valign="top">You got a great sky and angle here.</td>', 'You got a great sky and angle here.', '2002-04-21 22:46:00.000000', NULL, 1),
(50211, 946, 1034, '<td valign="top">All I can say is, "Amazing!"</td>', 'All I can say is, "Amazing!"', '2002-04-15 02:10:00.000000', NULL, 1),
(50212, 946, 674, '<td valign="top">I find this a very appealing photo! main subject very sharp. Lovely colours. A winner I feel!</td>', 'I find this a very appealing photo! main subject very sharp. Lovely colours. A winner I feel!', '2002-04-15 03:21:00.000000', NULL, 1),
(50213, 946, 107, '<td valign="top">very nice zoom.</td>', 'very nice zoom.', '2002-04-15 06:50:00.000000', NULL, 1),
(50214, 946, 92, '<td valign="top">Breath taking capture ! I would hang it on my wall ! Soooo feel free to email this to me haha WoW ! This is a great one !</td>', 'Breath taking capture ! I would hang it on my wall ! Soooo feel free to email this to me haha WoW ! This is a great one !', '2002-04-15 08:47:00.000000', NULL, 1),
(50215, 946, 1024, '<td valign="top">The blurred background really makes the subject stand out on the picture.  Very well done!</td>', 'The blurred background really makes the subject stand out on the picture.  Very well done!', '2002-04-15 09:01:00.000000', NULL, 1),
(50216, 946, 1055, '<td valign="top">this is an A+</td>', 'this is an A+', '2002-04-15 09:40:00.000000', NULL, 1),
(50217, 946, 301, '<td valign="top">absolutely gorgeous.  Beautiful focus and depth of field.  Got no idea how u do that when the bird could fly anywhere</td>', 'absolutely gorgeous.  Beautiful focus and depth of field.  Got no idea how u do that when the bird could fly anywhere', '2002-04-15 10:57:00.000000', NULL, 1),
(50218, 946, 1041, '<td valign="top">Nice shot.  Definitely stopped the action here.  One of the top pictures in my mind.</td>', 'Nice shot.  Definitely stopped the action here.  One of the top pictures in my mind.', '2002-04-15 11:12:00.000000', NULL, 1),
(50219, 946, 656, '<td valign="top">Great use of DoF to blur the background.</td>', 'Great use of DoF to blur the background.', '2002-04-15 11:41:00.000000', NULL, 1),
(50220, 946, 714, '<td valign="top">I love this photo.  WOW!  I can''t say that there is anything wrong with this photo.  :)  I give this a 10</td>', 'I love this photo.  WOW!  I can''t say that there is anything wrong with this photo.  :)  I give this a 10', '2002-04-15 12:28:00.000000', NULL, 1),
(50221, 946, 279, '<td valign="top">Wow! Just a TINY bit of wider framing so as to not lose that wing would''ve made this perfect. What a beautiful shot anyway though, the detail on the wing is staggering.</td>', 'Wow! Just a TINY bit of wider framing so as to not lose that wing would''ve made this perfect. What a beautiful shot anyway though, the detail on the wing is staggering.', '2002-04-15 13:07:00.000000', NULL, 1),
(50222, 946, 675, '<td valign="top">great job</td>', 'great job', '2002-04-15 13:35:00.000000', NULL, 1),
(50223, 946, 772, '<td valign="top">This is going to be very difficult for me not to rate this photograph highly.  This is an AWESOME photo.  The composition is almost perfect.  The wing is a little close to the bottom of the frame.  The sharpness, detail, and perfect depth of field here makes this a phenomenal photograph.  I am voting on this photograph by the same method I voted on another GREAT bird photograph.  It would receive a 10 if the challenge was Birds.  A gliding bird is a rather stationary object.  I can''t buy into this as a great interpretation of the challenge of "stopped motion".  I related this to photographing a ferrari riding on a flatbed rail car in my earlier comments on another photograph.  Kudos on the GREAT photo and keep up the good work.</td>', 'This is going to be very difficult for me not to rate this photograph highly.  This is an AWESOME photo.  The composition is almost perfect.  The wing is a little close to the bottom of the frame.  The sharpness, detail, and perfect depth of field here makes this a phenomenal photograph.  I am voting on this photograph by the same method I voted on another GREAT bird photograph.  It would receive a 10 if the challenge was Birds.  A gliding bird is a rather stationary object.  I can''t buy into this as a great interpretation of the challenge of "stopped motion".  I related this to photographing a ferrari riding on a flatbed rail car in my earlier comments on another photograph.  Kudos on the GREAT photo and keep up the good work.', '2002-04-15 13:42:00.000000', NULL, 1),
(50224, 946, 509, '<td valign="top">I wish the beach in the background had a little more focus (shoulda told the seagull to slow down!), very good detail on the gull</td>', 'I wish the beach in the background had a little more focus (shoulda told the seagull to slow down!), very good detail on the gull', '2002-04-15 14:14:00.000000', NULL, 1),
(50225, 946, 326, '<td valign="top">A shot to be proud of....Nice job!</td>', 'A shot to be proud of....Nice job!', '2002-04-15 14:51:00.000000', NULL, 1),
(50226, 946, 748, '<td valign="top">Really nice .. good depth of field.</td>', 'Really nice .. good depth of field.', '2002-04-15 14:59:00.000000', NULL, 1),
(50227, 946, 641, '<td valign="top">beautiful shot.</td>', 'beautiful shot.', '2002-04-15 15:20:00.000000', NULL, 1),
(50228, 946, 661, '<td valign="top">Wow!  Great detail.</td>', 'Wow!  Great detail.', '2002-04-15 15:28:00.000000', NULL, 1),
(50229, 946, 718, '<td valign="top">Nice focus.</td>', 'Nice focus.', '2002-04-15 15:37:00.000000', NULL, 1),
(50230, 946, 142, '<td valign="top">Great photo.  Very sharp and good interpretation of the challenge.</td>', 'Great photo.  Very sharp and good interpretation of the challenge.', '2002-04-15 16:21:00.000000', NULL, 1),
(50231, 946, 527, '<td valign="top">Finally, someone who knows the value of blurring the backgound. I like it a lot. Maybe I would have tried to keep the wing tip from touching the bottom edge but I''m not sure. I think I want to just keep looking at it.</td>', 'Finally, someone who knows the value of blurring the backgound. I like it a lot. Maybe I would have tried to keep the wing tip from touching the bottom edge but I''m not sure. I think I want to just keep looking at it.', '2002-04-15 18:13:00.000000', NULL, 1),
(50232, 946, 782, '<td valign="top">Well exposed and good focus.  Nice composition.</td>', 'Well exposed and good focus.  Nice composition.', '2002-04-15 19:09:00.000000', NULL, 1),
(50233, 946, 813, '<td valign="top">Very nice indeed. Excellent depth of field, good focus, composition etc.</td>', 'Very nice indeed. Excellent depth of field, good focus, composition etc.', '2002-04-15 19:24:00.000000', NULL, 1),
(50234, 946, 536, '<td valign="top">Fantasic. Stunning detail</td>', 'Fantasic. Stunning detail', '2002-04-15 19:25:00.000000', NULL, 1),
(50235, 946, 446, '<td valign="top">Nice capture.  I rated this high.</td>', 'Nice capture.  I rated this high.', '2002-04-15 20:35:00.000000', NULL, 1),
(50236, 946, 1, '<td valign="top">Cool shot, though I like the one on your site better.  The wing span was more full.</td>', 'Cool shot, though I like the one on your site better.  The wing span was more full.', '2002-04-15 21:38:00.000000', NULL, 1),
(50237, 946, 1031, '<td valign="top">My camera can''t do that...</td>', 'My camera can''t do that...', '2002-04-15 21:43:00.000000', NULL, 1),
(50238, 946, 352, '<td valign="top">Magnificent!</td>', 'Magnificent!', '2002-04-15 22:50:00.000000', NULL, 1),
(50239, 946, 724, '<td valign="top">Nice!!</td>', 'Nice!!', '2002-04-15 22:58:00.000000', NULL, 1),
(50240, 946, 640, '<td valign="top">Just beautiful</td>', 'Just beautiful', '2002-04-16 01:23:00.000000', NULL, 1),
(50241, 946, 881, '<td valign="top">A shame that the tip of the wing was clipped a little, otherwise an excellent photo!</td>', 'A shame that the tip of the wing was clipped a little, otherwise an excellent photo!', '2002-04-16 01:36:00.000000', NULL, 1),
(50242, 946, 113, '<td valign="top">This is very nice.  It just seems like something isn''t quite right about it.  Like you should be able to see some of his other wing or a foot.  The seagulls I know always fly with their feet hanging down.  Hmmmm.</td>', 'This is very nice.  It just seems like something isn''t quite right about it.  Like you should be able to see some of his other wing or a foot.  The seagulls I know always fly with their feet hanging down.  Hmmmm.', '2002-04-16 07:16:00.000000', NULL, 1),
(50243, 946, 1066, '<td valign="top">My favorite animal photo in this challenge.  great clarity for the bird, great out of focus background giving depth but not distracting the image.  One of my top 5</td>', 'My favorite animal photo in this challenge.  great clarity for the bird, great out of focus background giving depth but not distracting the image.  One of my top 5', '2002-04-16 10:25:00.000000', NULL, 1),
(50244, 946, 1078, '<td valign="top">Great shot -- perfect focus -- would have loved it even more if the wing had made it completely into the image space instead of being just cropped out</td>', 'Great shot -- perfect focus -- would have loved it even more if the wing had made it completely into the image space instead of being just cropped out', '2002-04-16 13:11:00.000000', NULL, 1),
(50245, 946, 1057, '<td valign="top">Great pic,well done</td>', 'Great pic,well done', '2002-04-16 13:46:00.000000', NULL, 1),
(50246, 946, 441, '<td valign="top">superb interesting shot, lovely detail, well stopped</td>', 'superb interesting shot, lovely detail, well stopped', '2002-04-16 14:30:00.000000', NULL, 1),
(50247, 946, 255, '<td valign="top">this is an awesome shot! 10 for you!</td>', 'this is an awesome shot! 10 for you!', '2002-04-16 15:57:00.000000', NULL, 1),
(50248, 946, 205, '<td valign="top">If there was one thing I had to complain about in this one its that the bird should have been a little bit more to the right.</td>', 'If there was one thing I had to complain about in this one its that the bird should have been a little bit more to the right.', '2002-04-16 18:08:00.000000', NULL, 1),
(50249, 946, 308, '<td valign="top">Very well done with some remarkable detail.  It only could have been better if the bottom wing wasn''t cut off.  Otherwise, great!</td>', 'Very well done with some remarkable detail.  It only could have been better if the bottom wing wasn''t cut off.  Otherwise, great!', '2002-04-16 18:47:00.000000', NULL, 1),
(50250, 946, 332, '<td valign="top">Good job. Depth Of Field is pretty nice. It''s gonna be in the top 5 :)</td>', 'Good job. Depth Of Field is pretty nice. It''s gonna be in the top 5 :)', '2002-04-16 20:50:00.000000', NULL, 1),
(50251, 946, 910, '<td valign="top">I like how the background is blurred (out of focus)</td>', 'I like how the background is blurred (out of focus)', '2002-04-16 22:10:00.000000', NULL, 1),
